INSERT INTO socialapp.t_posts
    (id, content, visibility, author_id, post_type, moderation_status, event_details, images, created_at, updated_at) VALUES
    (100001, 'Buổi chia sẻ về tối ưu truy vấn N+1 — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9001, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: tối ưu truy vấn N+1","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Bật @BatchSize (hay default_batch_fetch_size) gom các lượt gọi lazy thành một câu WHERE id IN (...), nên 1.000 bản ghi chỉ còn vài chục truy vấn thay vì một nghìn.","startTime":"2026-09-17T18:30:00+07:00","endTime":"2026-09-17T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":null,"onlineUrl":"https://meet.google.com/seed-event-100001","maxAttendees":20}'::jsonb, NULL, now() - INTERVAL '8 days', now() - INTERVAL '8 days'),
    (100002, 'Ngồi lại nói chuyện chọn TTL cho cache — buổi này đã diễn ra, video và slide mình để ở phần bình luận.', 'PUBLIC', 9143, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: chọn TTL cho cache","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Rắc thêm 10-20% jitter ngẫu nhiên vào TTL để tránh hàng loạt key hết hạn cùng lúc — nguyên nhân phổ biến nhất của cache stampede.","startTime":"2026-08-17T18:30:00+07:00","endTime":"2026-08-17T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":"Toong Coworking, 126 Nguyễn Thị Minh Khai, Quận 3, TP.HCM","onlineUrl":null,"maxAttendees":30}'::jsonb, NULL, now() - INTERVAL '25 days', now() - INTERVAL '25 days'),
    (100003, 'Chia sẻ nội bộ về đánh index đúng thứ tự cột — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9041, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: đánh index đúng thứ tự cột","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Quy tắc leftmost prefix: một index tổ hợp chỉ dùng được cho truy vấn lọc đúng các cột nằm ở đầu index, theo đúng thứ tự khai.","startTime":"2026-10-04T18:30:00+07:00","endTime":"2026-10-04T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":"Circo Coworking, 267 Nguyễn Thị Minh Khai, Quận 1, TP.HCM","onlineUrl":null,"maxAttendees":40}'::jsonb, NULL, now() - INTERVAL '29 days', now() - INTERVAL '29 days'),
    (100004, 'Một buổi tối bàn về chuyển sang virtual threads — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9072, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: chuyển sang virtual threads","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Virtual thread không loại bỏ nút thắt, nó dời nút thắt xuống tầng dưới: khi trần connection pool biến mất, hàng đợi truy vấn database trở thành điểm nghẽn kế tiếp.","startTime":"2026-11-15T18:30:00+07:00","endTime":"2026-11-15T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":null,"onlineUrl":"https://meet.google.com/seed-event-100004","maxAttendees":50}'::jsonb, NULL, now() - INTERVAL '45 days', now() - INTERVAL '45 days'),
    (100005, 'Meetup nhỏ về tách monolith thành service — buổi này đã diễn ra, video và slide mình để ở phần bình luận.', 'PUBLIC', 9377, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: tách monolith thành service","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Strangler fig: bọc route cũ sau một lớp proxy rồi chuyển từng phần sang service mới, hệ thống cũ vẫn chạy suốt quá trình chuyển thay vì viết lại toàn bộ cùng lúc.","startTime":"2026-05-07T18:30:00+07:00","endTime":"2026-05-07T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":"Hive Coworking, 94 Xuân Thuỷ, Cầu Giấy, Hà Nội","onlineUrl":null,"maxAttendees":60}'::jsonb, NULL, now() - INTERVAL '133 days', now() - INTERVAL '133 days'),
    (100006, 'Cà phê kỹ thuật: chuyện thiết kế API phân trang — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9158, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: thiết kế API phân trang","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Phân trang theo offset (LIMIT/OFFSET) chậm dần khi offset lớn vì database vẫn phải quét qua các dòng bị bỏ; phân trang theo cursor giữ tốc độ ổn định bất kể trang thứ mấy.","startTime":"2026-09-12T18:30:00+07:00","endTime":"2026-09-12T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":"Đại học Bách khoa Đà Nẵng, 54 Nguyễn Lương Bằng","onlineUrl":null,"maxAttendees":70}'::jsonb, NULL, now() - INTERVAL '14 days', now() - INTERVAL '14 days'),
    (100007, 'Kể chuyện nghề: xử lý idempotency cho webhook — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9295, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: xử lý idempotency cho webhook","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Client gửi kèm Idempotency-Key duy nhất trên header; server lưu key đó cùng kết quả lần xử lý đầu, các lần gọi lại cùng key chỉ trả lại đúng kết quả cũ.","startTime":"2026-09-21T18:30:00+07:00","endTime":"2026-09-21T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":null,"onlineUrl":"https://meet.google.com/seed-event-100007","maxAttendees":80}'::jsonb, NULL, now() - INTERVAL '23 days', now() - INTERVAL '23 days'),
    (100008, 'Nhóm mình mở buổi nói về chuẩn hoá log có traceId — buổi này đã diễn ra, video và slide mình để ở phần bình luận.', 'PUBLIC', 9016, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: chuẩn hoá log có traceId","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Một traceId sinh ở tầng gateway rồi truyền xuyên suốt qua header HTTP và context của hàng đợi, nối được toàn bộ đường đi của một request qua nhiều service chỉ bằng một lượt tìm log.","startTime":"2026-07-06T18:30:00+07:00","endTime":"2026-07-06T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":"Toong Coworking, 126 Nguyễn Thị Minh Khai, Quận 3, TP.HCM","onlineUrl":null,"maxAttendees":90}'::jsonb, NULL, now() - INTERVAL '63 days', now() - INTERVAL '63 days'),
    (100009, 'Chiều thứ sáu bàn về đo p99 thay vì trung bình — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9448, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: đo p99 thay vì trung bình","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Độ trễ không phân phối chuẩn mà lệch đuôi dài: một số ít request rất chậm (GC pause, cold start, retry, tranh chấp khoá) đủ sức kéo dài đuôi mà không ảnh hưởng tới trung bình.","startTime":"2026-11-16T18:30:00+07:00","endTime":"2026-11-16T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":"Circo Coworking, 267 Nguyễn Thị Minh Khai, Quận 1, TP.HCM","onlineUrl":null,"maxAttendees":20}'::jsonb, NULL, now() - INTERVAL '27 days', now() - INTERVAL '27 days'),
    (100010, 'Buổi chia sẻ về giảm thời gian build CI — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9255, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: giảm thời gian build CI","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Cache node_modules theo hash của lockfile đưa một bước cài đặt phụ thuộc từ 6-12 phút xuống còn 15-30 giây khi cache trúng.","startTime":"2026-10-28T18:30:00+07:00","endTime":"2026-10-28T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":null,"onlineUrl":"https://meet.google.com/seed-event-100010","maxAttendees":30}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100011, 'Ngồi lại nói chuyện viết test không phụ thuộc thứ tự — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9031, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: viết test không phụ thuộc thứ tự","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Test phụ thuộc thứ tự thường bắt nguồn từ state tĩnh dùng chung (static field, singleton chưa reset) hoặc dữ liệu test A để lại mà test B vô tình đọc phải.","startTime":"2026-10-21T18:30:00+07:00","endTime":"2026-10-21T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":"Hive Coworking, 94 Xuân Thuỷ, Cầu Giấy, Hà Nội","onlineUrl":null,"maxAttendees":40}'::jsonb, NULL, now() - INTERVAL '36 days', now() - INTERVAL '36 days'),
    (100012, 'Chia sẻ nội bộ về mock ít đi, dùng testcontainers — buổi này đã diễn ra, video và slide mình để ở phần bình luận.', 'PUBLIC', 9069, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: mock ít đi, dùng testcontainers","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Mock database không bắt được lỗi migration, connection pool hay timeout thật — những thứ chỉ hiện ra khi chạy trên một instance database thật.","startTime":"2026-06-30T18:30:00+07:00","endTime":"2026-06-30T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":"Đại học Bách khoa Đà Nẵng, 54 Nguyễn Lương Bằng","onlineUrl":null,"maxAttendees":50}'::jsonb, NULL, now() - INTERVAL '67 days', now() - INTERVAL '67 days'),
    (100013, 'Một buổi tối bàn về dựng design token dùng chung — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9072, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: dựng design token dùng chung","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Design token tách biến thiết kế (màu, khoảng cách, kiểu chữ) khỏi từng nền tảng, rồi biên dịch ra native code riêng cho iOS, Android và web từ đúng một nguồn.","startTime":"2026-11-01T18:30:00+07:00","endTime":"2026-11-01T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":null,"onlineUrl":"https://meet.google.com/seed-event-100013","maxAttendees":60}'::jsonb, NULL, now() - INTERVAL '27 days', now() - INTERVAL '27 days'),
    (100014, 'Meetup nhỏ về giảm layout shift — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9001, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: giảm layout shift","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Telegraph Media Group cải thiện CLS ở phân vị 75 từ 0,25 xuống 0,1, kéo tỉ lệ trang đạt chuẩn Core Web Vitals từ 57% lên 72%, theo case study với Google.","startTime":"2026-09-27T18:30:00+07:00","endTime":"2026-09-27T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":"Toong Coworking, 126 Nguyễn Thị Minh Khai, Quận 3, TP.HCM","onlineUrl":null,"maxAttendees":70}'::jsonb, NULL, now() - INTERVAL '34 days', now() - INTERVAL '34 days'),
    (100015, 'Cà phê kỹ thuật: chuyện làm form truy cập được bằng bàn phím — buổi này đã diễn ra, video và slide mình để ở phần bình luận.', 'PUBLIC', 9157, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: làm form truy cập được bằng bàn phím","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. WCAG 2.1.1 đòi mọi phần tử tương tác dùng được trọn vẹn chỉ bằng bàn phím: Tab/Shift+Tab di chuyển focus, Enter kích hoạt, phím mũi tên điều hướng trong dropdown và radio.","startTime":"2026-05-19T18:30:00+07:00","endTime":"2026-05-19T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":"Circo Coworking, 267 Nguyễn Thị Minh Khai, Quận 1, TP.HCM","onlineUrl":null,"maxAttendees":80}'::jsonb, NULL, now() - INTERVAL '110 days', now() - INTERVAL '110 days'),
    (100016, 'Kể chuyện nghề: chia bundle theo route — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9001, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: chia bundle theo route","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Code splitting theo route chỉ tải phần JavaScript cần cho trang đang xem, thay vì gộp toàn bộ ứng dụng vào một bundle duy nhất tải ngay từ lần đầu.","startTime":"2026-11-11T18:30:00+07:00","endTime":"2026-11-11T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":null,"onlineUrl":"https://meet.google.com/seed-event-100016","maxAttendees":90}'::jsonb, NULL, now() - INTERVAL '28 days', now() - INTERVAL '28 days'),
    (100017, 'Nhóm mình mở buổi nói về quản lý state không cần thư viện — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9092, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: quản lý state không cần thư viện","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. State của server (dữ liệu fetch), state URL và state UI cục bộ nên xử lý bằng cách khác nhau — không có một công cụ nào hợp cho mọi loại state.","startTime":"2026-09-08T18:30:00+07:00","endTime":"2026-09-08T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":"Hive Coworking, 94 Xuân Thuỷ, Cầu Giấy, Hà Nội","onlineUrl":null,"maxAttendees":20}'::jsonb, NULL, now() - INTERVAL '11 days', now() - INTERVAL '11 days'),
    (100018, 'Chiều thứ sáu bàn về đồng bộ dữ liệu khi mất mạng — buổi này đã diễn ra, video và slide mình để ở phần bình luận.', 'PUBLIC', 9011, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: đồng bộ dữ liệu khi mất mạng","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. CRDT cho phép nhiều thiết bị ghi độc lập rồi hợp nhất về cùng một kết quả mà không cần máy chủ trọng tài, miễn phép hợp là giao hoán và không phụ thuộc thứ tự.","startTime":"2026-06-05T18:30:00+07:00","endTime":"2026-06-05T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":"Đại học Bách khoa Đà Nẵng, 54 Nguyễn Lương Bằng","onlineUrl":null,"maxAttendees":30}'::jsonb, NULL, now() - INTERVAL '99 days', now() - INTERVAL '99 days'),
    (100019, 'Buổi chia sẻ về giảm kích thước app — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9377, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: giảm kích thước app","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Android App Bundle giảm trung bình khoảng 35% dung lượng tải về vì chỉ đóng gói đúng phần tài nguyên khớp thiết bị người dùng, thay vì mọi biến thể màn hình/kiến trúc CPU.","startTime":"2026-09-09T18:30:00+07:00","endTime":"2026-09-09T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":null,"onlineUrl":"https://meet.google.com/seed-event-100019","maxAttendees":40}'::jsonb, NULL, now() - INTERVAL '34 days', now() - INTERVAL '34 days'),
    (100020, 'Ngồi lại nói chuyện bảo mật token trên thiết bị — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9224, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: bảo mật token trên thiết bị","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. iOS Keychain và Android Keystore mã hoá secret bằng khoá sinh trong phần cứng bảo mật (Secure Enclave / TEE), nên kể cả thiết bị bị chiếm quyền cũng khó trích xuất trực tiếp khoá gốc.","startTime":"2026-10-12T18:30:00+07:00","endTime":"2026-10-12T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":"Toong Coworking, 126 Nguyễn Thị Minh Khai, Quận 3, TP.HCM","onlineUrl":null,"maxAttendees":50}'::jsonb, NULL, now() - INTERVAL '26 days', now() - INTERVAL '26 days'),
    (100021, 'Chia sẻ nội bộ về rà soát phụ thuộc bên thứ ba — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9011, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: rà soát phụ thuộc bên thứ ba","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Sự cố Log4Shell (CVE-2021-44228) ảnh hưởng hàng triệu ứng dụng vì phần lớn không biết mình dùng Log4j — khoảng 60% dự án Java dùng nó như một dependency gián tiếp, chôn sâu trong cây phụ thuộc.","startTime":"2026-09-10T18:30:00+07:00","endTime":"2026-09-10T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":"Circo Coworking, 267 Nguyễn Thị Minh Khai, Quận 1, TP.HCM","onlineUrl":null,"maxAttendees":60}'::jsonb, NULL, now() - INTERVAL '2 days', now() - INTERVAL '2 days'),
    (100022, 'Một buổi tối bàn về dựng pipeline triển khai xanh-lam — buổi này đã diễn ra, video và slide mình để ở phần bình luận.', 'PUBLIC', 9173, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: dựng pipeline triển khai xanh-lam","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Hai môi trường production giống hệt nhau — một đang chạy, một đứng chờ. Bản mới lên môi trường chờ, kiểm xong thì load balancer chuyển hướng traffic sang đó.","startTime":"2026-05-09T18:30:00+07:00","endTime":"2026-05-09T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":null,"onlineUrl":"https://meet.google.com/seed-event-100022","maxAttendees":70}'::jsonb, NULL, now() - INTERVAL '120 days', now() - INTERVAL '120 days'),
    (100023, 'Meetup nhỏ về đặt resource limit cho pod — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9131, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: đặt resource limit cho pod","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Exit code 137 trong kubectl describe pod gần như luôn là OOMKilled — kernel Linux giết tiến trình khi vượt giới hạn bộ nhớ đã khai.","startTime":"2026-10-19T18:30:00+07:00","endTime":"2026-10-19T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":"Hive Coworking, 94 Xuân Thuỷ, Cầu Giấy, Hà Nội","onlineUrl":null,"maxAttendees":80}'::jsonb, NULL, now() - INTERVAL '4 days', now() - INTERVAL '4 days'),
    (100024, 'Cà phê kỹ thuật: chuyện chuyển state Terraform lên remote — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9456, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: chuyển state Terraform lên remote","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Từ Terraform 1.10, backend S3 tự khoá state bằng use_lockfile = true, không còn bắt buộc phải dựng thêm bảng DynamoDB riêng cho việc khoá như trước.","startTime":"2026-11-21T18:30:00+07:00","endTime":"2026-11-21T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":"Đại học Bách khoa Đà Nẵng, 54 Nguyễn Lương Bằng","onlineUrl":null,"maxAttendees":90}'::jsonb, NULL, now() - INTERVAL '37 days', now() - INTERVAL '37 days'),
    (100025, 'Kể chuyện nghề: giảm hoá đơn cloud — buổi này đã diễn ra, video và slide mình để ở phần bình luận.', 'PUBLIC', 9366, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: giảm hoá đơn cloud","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Nhiều đội đạt mức giảm 25-40% chi phí cloud trong 90 ngày đầu chỉ bằng rightsizing và dọn tài nguyên nhàn rỗi, chưa cần tái kiến trúc.","startTime":"2026-08-14T18:30:00+07:00","endTime":"2026-08-14T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":null,"onlineUrl":"https://meet.google.com/seed-event-100025","maxAttendees":20}'::jsonb, NULL, now() - INTERVAL '25 days', now() - INTERVAL '25 days'),
    (100026, 'Nhóm mình mở buổi nói về đưa mô hình từ notebook lên production — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9001, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: đưa mô hình từ notebook lên production","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Công cụ kiểm dữ liệu tối ưu cho notebook thường thêm độ trễ không chấp nhận được khi ép chạy trong một pipeline real-time — công cụ hợp cho notebook chưa chắc hợp cho production.","startTime":"2026-11-24T18:30:00+07:00","endTime":"2026-11-24T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":"Toong Coworking, 126 Nguyễn Thị Minh Khai, Quận 3, TP.HCM","onlineUrl":null,"maxAttendees":30}'::jsonb, NULL, now() - INTERVAL '1 days', now() - INTERVAL '1 days'),
    (100027, 'Chiều thứ sáu bàn về làm sạch dữ liệu đầu vào — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9387, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: làm sạch dữ liệu đầu vào","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Giá trị thiếu và giá trị trùng lặp gần đúng (cùng một khách hàng viết hoa/viết thường khác nhau) là hai nguồn lỗi phổ biến nhất khi gộp dữ liệu từ nhiều hệ thống.","startTime":"2026-10-31T18:30:00+07:00","endTime":"2026-10-31T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":"Circo Coworking, 267 Nguyễn Thị Minh Khai, Quận 1, TP.HCM","onlineUrl":null,"maxAttendees":40}'::jsonb, NULL, now() - INTERVAL '21 days', now() - INTERVAL '21 days'),
    (100028, 'Buổi chia sẻ về chọn giữa batch và streaming — buổi này đã diễn ra, video và slide mình để ở phần bình luận.', 'PUBLIC', 9496, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: chọn giữa batch và streaming","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Batch xử lý dữ liệu theo lô định kỳ — đơn giản vận hành, độ trễ cao; streaming xử lý từng sự kiện gần như ngay lập tức — độ trễ thấp, đổi lại phức tạp hơn khi xử lý lỗi.","startTime":"2026-06-12T18:30:00+07:00","endTime":"2026-06-12T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":null,"onlineUrl":"https://meet.google.com/seed-event-100028","maxAttendees":50}'::jsonb, NULL, now() - INTERVAL '84 days', now() - INTERVAL '84 days'),
    (100029, 'Ngồi lại nói chuyện đánh giá chất lượng embedding — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9488, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: đánh giá chất lượng embedding","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. MTEB đo tám loại tác vụ trên hàng chục bộ dữ liệu và hơn trăm ngôn ngữ, nhưng cho RAG chỉ tác vụ retrieval là quan trọng — điểm MTEB tổng có thể đánh lừa nếu mô hình mạnh ở phân loại nhưng yếu ở tìm kiếm.","startTime":"2026-10-01T18:30:00+07:00","endTime":"2026-10-01T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":"Hive Coworking, 94 Xuân Thuỷ, Cầu Giấy, Hà Nội","onlineUrl":null,"maxAttendees":60}'::jsonb, NULL, now() - INTERVAL '2 days', now() - INTERVAL '2 days'),
    (100030, 'Chia sẻ nội bộ về viết prompt ổn định qua nhiều lần chạy — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9289, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: viết prompt ổn định qua nhiều lần chạy","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Tỉ lệ bất ổn định từng đo được tăng từ khoảng 9,5% ở temperature 0,0 lên gần 20% ở temperature 1,0 trong một khảo sát trên nhiều mô hình — temperature thấp giảm rủi ro chứ không đảm bảo ổn định tuyệt đối.","startTime":"2026-09-08T18:30:00+07:00","endTime":"2026-09-08T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":"Đại học Bách khoa Đà Nẵng, 54 Nguyễn Lương Bằng","onlineUrl":null,"maxAttendees":70}'::jsonb, NULL, now() - INTERVAL '38 days', now() - INTERVAL '38 days'),
    (100031, 'Một buổi tối bàn về phỏng vấn không hỏi thuật toán — đăng ký sớm còn chỗ nhé cả nhà.', 'PUBLIC', 9163, 'EVENT', 'APPROVED', '{"eventTitle":"Buổi chia sẻ: phỏng vấn không hỏi thuật toán","eventDescription":"Trình bày 30 phút, hỏi đáp 30 phút. Một quy trình phỏng vấn dựa trên bài tập sát việc thật (đọc mã có sẵn, sửa một lỗi cụ thể) được cho là dự đoán hiệu quả công việc tốt hơn câu hỏi thuật toán kinh điển.","startTime":"2026-10-21T18:30:00+07:00","endTime":"2026-10-21T21:00:00+07:00","timezone":"Asia/Ho_Chi_Minh","location":null,"onlineUrl":"https://meet.google.com/seed-event-100031","maxAttendees":80}'::jsonb, NULL, now() - INTERVAL '12 days', now() - INTERVAL '12 days'),
