    (100097, 'Phiên bản typescript mình thấy dễ đọc nhất trong mấy cách đã thử.', 'PUBLIC', 9373, 'CODE_SNIPPET', 'APPROVED', '{"language":"typescript","code":"export function useDebounced<T>(value: T, delay = 300): T {\n  const [v, setV] = useState(value);\n  useEffect(() => {\n    const id = setTimeout(() => setV(value), delay);\n    return () => clearTimeout(id);\n  }, [value, delay]);\n  return v;\n}"}'::jsonb, NULL, now() - INTERVAL '1 days', now() - INTERVAL '1 days'),
