INSERT INTO socialapp.t_posts
    (id, content, visibility, author_id, post_type, moderation_status, article_details, images, created_at, updated_at) VALUES
    (100241, 'Ghi chép về tối ưu truy vấn N+1. Bật @BatchSize (hay default_batch_fetch_size) gom các lượt gọi lazy thành một câu WHERE id IN (...), nên 1.000 bản ghi chỉ còn vài chục truy vấn thay vì một nghìn. JOIN FETCH giải đúng một quan hệ trong một câu truy vấn, nhưng đổi FetchType sang EAGER để né N+1 chỉ khiến nó nặng hơn — Hibernate vẫn phát sinh truy vấn phụ cho từng dòng.', 'PUBLIC', 9385, 'ARTICLE', 'APPROVED', '{"title":"Ghi chép về tối ưu truy vấn N+1","coverImage":"${minioUrl}/post-media/posts/100241/cover.png","summary":"Bật @BatchSize (hay default_batch_fetch_size) gom các lượt gọi lazy thành một câu WHERE id IN (...), nên 1.000 bản ghi chỉ còn vài chục truy vấn thay vì một nghìn."}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100242, 'Nhìn lại hành trình chọn TTL cho cache. Một khoá mutex ngắn hạn cho đúng một request đi tái tạo cache khi miss, các request còn lại chờ hoặc nhận bản cũ, thay vì để tất cả cùng dội xuống database. Stale-while-revalidate trả ngay giá trị đã hết hạn cho người dùng trong lúc một tiến trình nền âm thầm làm mới, nên không request nào phải chờ origin.', 'PUBLIC', 9426, 'ARTICLE', 'APPROVED', '{"title":"Nhìn lại hành trình chọn TTL cho cache","coverImage":null,"summary":"Một khoá mutex ngắn hạn cho đúng một request đi tái tạo cache khi miss, các request còn lại chờ hoặc nhận bản cũ, thay vì để tất cả cùng dội xuống database."}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100243, 'Chuyện đánh index đúng thứ tự cột, từ đầu tới lúc ổn. Một truy vấn lọc ba cột trên bảng triệu dòng từng đi từ Parallel Seq Scan 17ms xuống Index Only Scan 0,6ms sau khi thêm đúng index tổ hợp khớp thứ tự lọc. Quy tắc leftmost prefix: một index tổ hợp chỉ dùng được cho truy vấn lọc đúng các cột nằm ở đầu index, theo đúng thứ tự khai.', 'PUBLIC', 9456, 'ARTICLE', 'APPROVED', '{"title":"Chuyện đánh index đúng thứ tự cột, từ đầu tới lúc ổn","coverImage":null,"summary":"Một truy vấn lọc ba cột trên bảng triệu dòng từng đi từ Parallel Seq Scan 17ms xuống Index Only Scan 0,6ms sau khi thêm đúng index tổ hợp khớp thứ tự lọc."}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100244, 'Những gì mình học được khi chuyển sang virtual threads. Virtual thread không loại bỏ nút thắt, nó dời nút thắt xuống tầng dưới: khi trần connection pool biến mất, hàng đợi truy vấn database trở thành điểm nghẽn kế tiếp. ThreadLocal dùng sai với virtual thread gây rò rỉ bộ nhớ âm thầm — virtual thread không được gộp lại (pool) như platform thread nên state cũ không bao giờ được dọn.', 'PUBLIC', 9346, 'ARTICLE', 'APPROVED', '{"title":"Những gì mình học được khi chuyển sang virtual threads","coverImage":null,"summary":"Virtual thread không loại bỏ nút thắt, nó dời nút thắt xuống tầng dưới: khi trần connection pool biến mất, hàng đợi truy vấn database trở thành điểm nghẽn kế tiếp."}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100245, 'Nhật ký tách monolith thành service. Ranh giới service nên theo bounded context của nghiệp vụ, không theo lớp kỹ thuật — tách riêng ''service database'' hay ''service UI'' là dấu hiệu sai hướng. Chi phí ẩn lớn nhất không nằm ở hạ tầng mà ở giao tiếp giữa các service: một transaction từng gọn trong một câu SQL giờ cần saga hoặc outbox pattern để giữ nhất quán.', 'PUBLIC', 9006, 'ARTICLE', 'APPROVED', '{"title":"Nhật ký tách monolith thành service","coverImage":"${minioUrl}/post-media/posts/100245/cover.png","summary":"Ranh giới service nên theo bounded context của nghiệp vụ, không theo lớp kỹ thuật — tách riêng ''service database'' hay ''service UI'' là dấu hiệu sai hướng."}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100246, 'Kể lại lần thiết kế API phân trang. Trả kèm hasMore thay vì tổng số trang: COUNT(*) trên bảng lớn tốn kém và thường không cần thiết cho một danh sách cuộn vô hạn. Phân trang theo offset (LIMIT/OFFSET) chậm dần khi offset lớn vì database vẫn phải quét qua các dòng bị bỏ; phân trang theo cursor giữ tốc độ ổn định bất kể trang thứ mấy.', 'PUBLIC', 9456, 'ARTICLE', 'APPROVED', '{"title":"Kể lại lần thiết kế API phân trang","coverImage":null,"summary":"Trả kèm hasMore thay vì tổng số trang: COUNT(*) trên bảng lớn tốn kém và thường không cần thiết cho một danh sách cuộn vô hạn."}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100247, 'Tổng kết đợt xử lý idempotency cho webhook. Client gửi kèm Idempotency-Key duy nhất trên header; server lưu key đó cùng kết quả lần xử lý đầu, các lần gọi lại cùng key chỉ trả lại đúng kết quả cũ. Webhook luôn giao theo kiểu ''ít nhất một lần'' — chắc chắn có lúc nhận trùng sự kiện, nên mọi payload đứng đắn đều mang kèm một event id duy nhất để nhận diện.', 'PUBLIC', 9082, 'ARTICLE', 'APPROVED', '{"title":"Tổng kết đợt xử lý idempotency cho webhook","coverImage":null,"summary":"Client gửi kèm Idempotency-Key duy nhất trên header; server lưu key đó cùng kết quả lần xử lý đầu, các lần gọi lại cùng key chỉ trả lại đúng kết quả cũ."}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100248, 'Bài học sau khi chuẩn hoá log có traceId. Không có traceId, một sự cố tail latency chỉ hiện ra như ''p99 tăng'' trên dashboard — không nói được request nào chậm, đi qua service nào, chết ở bước nào. MDC (Mapped Diagnostic Context) của SLF4J gắn traceId vào mọi dòng log trong cùng luồng xử lý mà không cần truyền tay qua từng hàm.', 'PUBLIC', 9325, 'ARTICLE', 'APPROVED', '{"title":"Bài học sau khi chuẩn hoá log có traceId","coverImage":null,"summary":"Không có traceId, một sự cố tail latency chỉ hiện ra như ''p99 tăng'' trên dashboard — không nói được request nào chậm, đi qua service nào, chết ở bước nào."}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100249, 'Ghi chép về đo p99 thay vì trung bình. Khuếch đại đuôi (tail amplification) xảy ra khi một request chậm ở tầng dưới khiến các lượt retry ở tầng trên dồn lại, biến 1% request chậm thành sự cố toàn hệ thống. Độ trễ không phân phối chuẩn mà lệch đuôi dài: một số ít request rất chậm (GC pause, cold start, retry, tranh chấp khoá) đủ sức kéo dài đuôi mà không ảnh hưởng tới trung bình.', 'PUBLIC', 9229, 'ARTICLE', 'APPROVED', '{"title":"Ghi chép về đo p99 thay vì trung bình","coverImage":"${minioUrl}/post-media/posts/100249/cover.png","summary":"Khuếch đại đuôi (tail amplification) xảy ra khi một request chậm ở tầng dưới khiến các lượt retry ở tầng trên dồn lại, biến 1% request chậm thành sự cố toàn hệ thống."}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100250, 'Nhìn lại hành trình giảm thời gian build CI. Cache node_modules theo hash của lockfile đưa một bước cài đặt phụ thuộc từ 6-12 phút xuống còn 15-30 giây khi cache trúng. Tách một job chạy tuần tự trên 14 máy thành ba job song song từng đưa build time từ 24 phút xuống còn 8 phút, không đổi logic build.', 'PUBLIC', 9255, 'ARTICLE', 'APPROVED', '{"title":"Nhìn lại hành trình giảm thời gian build CI","coverImage":null,"summary":"Cache node_modules theo hash của lockfile đưa một bước cài đặt phụ thuộc từ 6-12 phút xuống còn 15-30 giây khi cache trúng."}'::jsonb, NULL, now() - INTERVAL '5 days', now() - INTERVAL '5 days'),
    (100251, 'Chuyện viết test không phụ thuộc thứ tự, từ đầu tới lúc ổn. Chạy test với thứ tự ngẫu nhiên mỗi lần là cách nhanh nhất lộ ra test nào đang ngầm phụ thuộc thứ tự chạy trước đó. Mỗi test nên tự dựng dữ liệu của mình rồi tự dọn sau khi chạy, thay vì tin vào thứ tự chạy trước đó để lại đúng trạng thái cần.', 'PUBLIC', 9319, 'ARTICLE', 'APPROVED', '{"title":"Chuyện viết test không phụ thuộc thứ tự, từ đầu tới lúc ổn","coverImage":null,"summary":"Chạy test với thứ tự ngẫu nhiên mỗi lần là cách nhanh nhất lộ ra test nào đang ngầm phụ thuộc thứ tự chạy trước đó."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100252, 'Những gì mình học được khi mock ít đi, dùng testcontainers. Chi phí thật của việc bảo trì mock là độ trôi (drift): schema hay logic nghiệp vụ đổi mà mock không đổi theo, lỗi lọt qua ngay chỗ lẽ ra test phải bắt được. Mock database không bắt được lỗi migration, connection pool hay timeout thật — những thứ chỉ hiện ra khi chạy trên một instance database thật.', 'PUBLIC', 9352, 'ARTICLE', 'APPROVED', '{"title":"Những gì mình học được khi mock ít đi, dùng testcontainers","coverImage":null,"summary":"Chi phí thật của việc bảo trì mock là độ trôi (drift): schema hay logic nghiệp vụ đổi mà mock không đổi theo, lỗi lọt qua ngay chỗ lẽ ra test phải bắt được."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100253, 'Nhật ký dựng design token dùng chung. Design token tách biến thiết kế (màu, khoảng cách, kiểu chữ) khỏi từng nền tảng, rồi biên dịch ra native code riêng cho iOS, Android và web từ đúng một nguồn. Airbnb xây một hệ ngôn ngữ thiết kế dùng chung thay vì ba hệ riêng cho ba nền tảng, đổi lại là một nguồn sự thật duy nhất cho mọi token.', 'PUBLIC', 9400, 'ARTICLE', 'APPROVED', '{"title":"Nhật ký dựng design token dùng chung","coverImage":"${minioUrl}/post-media/posts/100253/cover.png","summary":"Design token tách biến thiết kế (màu, khoảng cách, kiểu chữ) khỏi từng nền tảng, rồi biên dịch ra native code riêng cho iOS, Android và web từ đúng một nguồn."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100254, 'Kể lại lần giảm layout shift. Đặt trước kích thước (width/height hoặc aspect-ratio) cho ảnh và khối quảng cáo là cách rẻ nhất để trình duyệt chừa đúng chỗ trước khi nội dung tải xong. Một mức giảm CLS 0,1 tương ứng khoảng 1-2% tăng engagement trong một số nghiên cứu — người đọc không còn bị nội dung ''nhảy'' ngay lúc định bấm.', 'PUBLIC', 9394, 'ARTICLE', 'APPROVED', '{"title":"Kể lại lần giảm layout shift","coverImage":null,"summary":"Đặt trước kích thước (width/height hoặc aspect-ratio) cho ảnh và khối quảng cáo là cách rẻ nhất để trình duyệt chừa đúng chỗ trước khi nội dung tải xong."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100255, 'Tổng kết đợt làm form truy cập được bằng bàn phím. Thứ tự Tab phải theo đúng thứ tự đọc hợp lý trên giao diện, không theo thứ tự khai trong DOM nếu CSS đã sắp xếp lại vị trí hiển thị. WCAG 2.1.1 đòi mọi phần tử tương tác dùng được trọn vẹn chỉ bằng bàn phím: Tab/Shift+Tab di chuyển focus, Enter kích hoạt, phím mũi tên điều hướng trong dropdown và radio.', 'PUBLIC', 9081, 'ARTICLE', 'APPROVED', '{"title":"Tổng kết đợt làm form truy cập được bằng bàn phím","coverImage":null,"summary":"Thứ tự Tab phải theo đúng thứ tự đọc hợp lý trên giao diện, không theo thứ tự khai trong DOM nếu CSS đã sắp xếp lại vị trí hiển thị."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100256, 'Bài học sau khi chia bundle theo route. Code splitting theo route chỉ tải phần JavaScript cần cho trang đang xem, thay vì gộp toàn bộ ứng dụng vào một bundle duy nhất tải ngay từ lần đầu. Lazy import một component nặng (biểu đồ, trình soạn thảo rich text) chỉ khi người dùng thực sự mở tới nó, thay vì buộc ai cũng tải nó dù không bao giờ chạm tới.', 'PUBLIC', 9385, 'ARTICLE', 'APPROVED', '{"title":"Bài học sau khi chia bundle theo route","coverImage":null,"summary":"Code splitting theo route chỉ tải phần JavaScript cần cho trang đang xem, thay vì gộp toàn bộ ứng dụng vào một bundle duy nhất tải ngay từ lần đầu."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100257, 'Ghi chép về quản lý state không cần thư viện. useReducer hợp khi một state có từ bốn hành động trở lên hoặc các trường phụ thuộc lẫn nhau; tách state và dispatch thành hai context riêng để component chỉ gọi dispatch không bị render lại mỗi khi state đổi. useContext một mình chỉ cấp quyền truy cập toàn cục, không có cấu trúc; useReducer một mình có cấu trúc nhưng chỉ cục bộ — kết hợp cả hai mới đủ thay một thư viện quản lý state ở quy mô vừa.', 'PUBLIC', 9457, 'ARTICLE', 'APPROVED', '{"title":"Ghi chép về quản lý state không cần thư viện","coverImage":"${minioUrl}/post-media/posts/100257/cover.png","summary":"useReducer hợp khi một state có từ bốn hành động trở lên hoặc các trường phụ thuộc lẫn nhau; tách state và dispatch thành hai context riêng để component chỉ gọi dispatch không bị render lại mỗi khi state đổi."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100258, 'Nhìn lại hành trình đồng bộ dữ liệu khi mất mạng. PowerSync, Realm Sync và replication kiểu CouchDB là các nền tảng offline-first đang chạy production thật, dùng CRDT hoặc conflict resolution theo revision. CRDT cho phép nhiều thiết bị ghi độc lập rồi hợp nhất về cùng một kết quả mà không cần máy chủ trọng tài, miễn phép hợp là giao hoán và không phụ thuộc thứ tự.', 'PUBLIC', 9486, 'ARTICLE', 'APPROVED', '{"title":"Nhìn lại hành trình đồng bộ dữ liệu khi mất mạng","coverImage":null,"summary":"PowerSync, Realm Sync và replication kiểu CouchDB là các nền tảng offline-first đang chạy production thật, dùng CRDT hoặc conflict resolution theo revision."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100259, 'Chuyện giảm kích thước app, từ đầu tới lúc ổn. Android App Bundle giảm trung bình khoảng 35% dung lượng tải về vì chỉ đóng gói đúng phần tài nguyên khớp thiết bị người dùng, thay vì mọi biến thể màn hình/kiến trúc CPU. R8/ProGuard loại bỏ code không dùng tới từ các SDK bên thứ ba; một số dự án thực tế giảm được 60-70% kích thước APK chỉ bằng shrinking và minification, không đổi tính năng.', 'PUBLIC', 9072, 'ARTICLE', 'APPROVED', '{"title":"Chuyện giảm kích thước app, từ đầu tới lúc ổn","coverImage":null,"summary":"Android App Bundle giảm trung bình khoảng 35% dung lượng tải về vì chỉ đóng gói đúng phần tài nguyên khớp thiết bị người dùng, thay vì mọi biến thể màn hình/kiến trúc CPU."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100260, 'Những gì mình học được khi bảo mật token trên thiết bị. Chỉ một phần rất nhỏ ứng dụng xử lý dữ liệu nhạy cảm dùng đúng mức bảo vệ phần cứng mạnh nhất — phần lớn vẫn lưu token ở mức bảo vệ yếu hơn dù nền tảng đã hỗ trợ sẵn. Trên thiết bị đã jailbreak/root, mọi lớp bảo vệ của hệ thống keychain coi như mất tác dụng — không nên tin tuyệt đối vào lưu trữ phía client cho secret có giá trị cao.', 'PUBLIC', 9021, 'ARTICLE', 'APPROVED', '{"title":"Những gì mình học được khi bảo mật token trên thiết bị","coverImage":null,"summary":"Chỉ một phần rất nhỏ ứng dụng xử lý dữ liệu nhạy cảm dùng đúng mức bảo vệ phần cứng mạnh nhất — phần lớn vẫn lưu token ở mức bảo vệ yếu hơn dù nền tảng đã hỗ trợ sẵn."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100261, 'Nhật ký rà soát phụ thuộc bên thứ ba. Dependabot và các công cụ tương tự không chỉ báo lỗ hổng ở dependency trực tiếp mà còn dò tới tận dependency gián tiếp, tự tạo PR nâng phiên bản gốc để kéo theo bản vá. Sự cố Log4Shell (CVE-2021-44228) ảnh hưởng hàng triệu ứng dụng vì phần lớn không biết mình dùng Log4j — khoảng 60% dự án Java dùng nó như một dependency gián tiếp, chôn sâu trong cây phụ thuộc.', 'PUBLIC', 9072, 'ARTICLE', 'APPROVED', '{"title":"Nhật ký rà soát phụ thuộc bên thứ ba","coverImage":"${minioUrl}/post-media/posts/100261/cover.png","summary":"Dependabot và các công cụ tương tự không chỉ báo lỗ hổng ở dependency trực tiếp mà còn dò tới tận dependency gián tiếp, tự tạo PR nâng phiên bản gốc để kéo theo bản vá."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100262, 'Kể lại lần dựng pipeline triển khai xanh-lam. Hai môi trường production giống hệt nhau — một đang chạy, một đứng chờ. Bản mới lên môi trường chờ, kiểm xong thì load balancer chuyển hướng traffic sang đó. Rollback chỉ là trỏ lại load balancer về môi trường cũ, không phải deploy lại — đây là lý do rollback kiểu này gần như tức thì so với các chiến lược khác.', 'PUBLIC', 9228, 'ARTICLE', 'APPROVED', '{"title":"Kể lại lần dựng pipeline triển khai xanh-lam","coverImage":null,"summary":"Hai môi trường production giống hệt nhau — một đang chạy, một đứng chờ. Bản mới lên môi trường chờ, kiểm xong thì load balancer chuyển hướng traffic sang đó."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100263, 'Tổng kết đợt đặt resource limit cho pod. Đặt memory limit bằng đúng memory request là khuyến nghị chuẩn: bộ nhớ là tài nguyên không nén được, một khi đã cấp cho pod thì chỉ lấy lại được bằng cách giết pod. Pod ở nhóm Guaranteed (request bằng limit cho cả CPU lẫn RAM) bị evict sau cùng khi node thiếu tài nguyên; pod không khai request/limit bị evict đầu tiên.', 'PUBLIC', 9173, 'ARTICLE', 'APPROVED', '{"title":"Tổng kết đợt đặt resource limit cho pod","coverImage":null,"summary":"Đặt memory limit bằng đúng memory request là khuyến nghị chuẩn: bộ nhớ là tài nguyên không nén được, một khi đã cấp cho pod thì chỉ lấy lại được bằng cách giết pod."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100264, 'Bài học sau khi chuyển state Terraform lên remote. State cục bộ không có khoá: hai người chạy terraform apply cùng lúc có thể ghi đè state của nhau — backend từ xa giải đúng vấn đề này bằng khoá tập trung. Từ Terraform 1.10, backend S3 tự khoá state bằng use_lockfile = true, không còn bắt buộc phải dựng thêm bảng DynamoDB riêng cho việc khoá như trước.', 'PUBLIC', 9152, 'ARTICLE', 'APPROVED', '{"title":"Bài học sau khi chuyển state Terraform lên remote","coverImage":null,"summary":"State cục bộ không có khoá: hai người chạy terraform apply cùng lúc có thể ghi đè state của nhau — backend từ xa giải đúng vấn đề này bằng khoá tập trung."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100265, 'Ghi chép về giảm hoá đơn cloud. Nhiều đội đạt mức giảm 25-40% chi phí cloud trong 90 ngày đầu chỉ bằng rightsizing và dọn tài nguyên nhàn rỗi, chưa cần tái kiến trúc. Phần lớn khoản tiết kiệm của một chương trình FinOps có cấu trúc thường đến ngay trong tháng thứ hai, từ rightsizing và tắt tài nguyên không dùng.', 'PUBLIC', 9131, 'ARTICLE', 'APPROVED', '{"title":"Ghi chép về giảm hoá đơn cloud","coverImage":"${minioUrl}/post-media/posts/100265/cover.png","summary":"Nhiều đội đạt mức giảm 25-40% chi phí cloud trong 90 ngày đầu chỉ bằng rightsizing và dọn tài nguyên nhàn rỗi, chưa cần tái kiến trúc."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100266, 'Nhìn lại hành trình đưa mô hình từ notebook lên production. Data drift là khi phân phối thống kê của dữ liệu đầu vào đổi theo thời gian; concept drift là khi chính mối quan hệ giữa đầu vào và đầu ra đổi — hai loại trôi cần chiến lược phát hiện khác nhau. Drift ở tầng bề mặt (trung bình, phương sai) đôi khi không đổi trong khi phân phối thật đã lệch hẳn — chỉ theo dõi thống kê tổng quát dễ bỏ sót loại trôi này.', 'PUBLIC', 9465, 'ARTICLE', 'APPROVED', '{"title":"Nhìn lại hành trình đưa mô hình từ notebook lên production","coverImage":null,"summary":"Data drift là khi phân phối thống kê của dữ liệu đầu vào đổi theo thời gian; concept drift là khi chính mối quan hệ giữa đầu vào và đầu ra đổi — hai loại trôi cần chiến lược phát hiện khác nhau."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100267, 'Chuyện làm sạch dữ liệu đầu vào, từ đầu tới lúc ổn. Phần lớn thời gian của một dự án dữ liệu thực tế nằm ở làm sạch và chuẩn hoá, không nằm ở chọn thuật toán — quan sát này lặp lại ở gần như mọi khảo sát ngành khoa học dữ liệu. Giá trị thiếu và giá trị trùng lặp gần đúng (cùng một khách hàng viết hoa/viết thường khác nhau) là hai nguồn lỗi phổ biến nhất khi gộp dữ liệu từ nhiều hệ thống.', 'PUBLIC', 9395, 'ARTICLE', 'APPROVED', '{"title":"Chuyện làm sạch dữ liệu đầu vào, từ đầu tới lúc ổn","coverImage":null,"summary":"Phần lớn thời gian của một dự án dữ liệu thực tế nằm ở làm sạch và chuẩn hoá, không nằm ở chọn thuật toán — quan sát này lặp lại ở gần như mọi khảo sát ngành khoa học dữ liệu."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100268, 'Những gì mình học được khi chọn giữa batch và streaming. Batch xử lý dữ liệu theo lô định kỳ — đơn giản vận hành, độ trễ cao; streaming xử lý từng sự kiện gần như ngay lập tức — độ trễ thấp, đổi lại phức tạp hơn khi xử lý lỗi. Kiến trúc kết hợp cả hai (một đường streaming trả kết quả nhanh, một đường batch chạy lại định kỳ để sửa đúng) đánh đổi độ phức tạp vận hành lấy vừa nhanh vừa đúng.', 'PUBLIC', 9194, 'ARTICLE', 'APPROVED', '{"title":"Những gì mình học được khi chọn giữa batch và streaming","coverImage":null,"summary":"Batch xử lý dữ liệu theo lô định kỳ — đơn giản vận hành, độ trễ cao; streaming xử lý từng sự kiện gần như ngay lập tức — độ trễ thấp, đổi lại phức tạp hơn khi xử lý lỗi."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100269, 'Nhật ký đánh giá chất lượng embedding. NDCG@10 là chỉ số nên dùng chính cho retrieval: nó đo cả việc có tìm đúng tài liệu hay không lẫn tài liệu đó đứng ở vị trí nào trong kết quả trả về. Một mô hình embedding xếp hạng cao trên bảng MTEB tổng vẫn có thể thua một mô hình xếp hạng thấp hơn khi test trực tiếp trên đúng dữ liệu miền của mình.', 'PUBLIC', 9163, 'ARTICLE', 'APPROVED', '{"title":"Nhật ký đánh giá chất lượng embedding","coverImage":"${minioUrl}/post-media/posts/100269/cover.png","summary":"NDCG@10 là chỉ số nên dùng chính cho retrieval: nó đo cả việc có tìm đúng tài liệu hay không lẫn tài liệu đó đứng ở vị trí nào trong kết quả trả về."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100270, 'Kể lại lần viết prompt ổn định qua nhiều lần chạy. Gần một phần tư câu hỏi trong một khảo sát trên nhiều họ mô hình từng đổi hẳn kết quả chỉ vì đổi seed ngẫu nhiên, dù prompt và nhiệt độ giữ nguyên. Tỉ lệ bất ổn định từng đo được tăng từ khoảng 9,5% ở temperature 0,0 lên gần 20% ở temperature 1,0 trong một khảo sát trên nhiều mô hình — temperature thấp giảm rủi ro chứ không đảm bảo ổn định tuyệt đối.', 'PUBLIC', 9101, 'ARTICLE', 'APPROVED', '{"title":"Kể lại lần viết prompt ổn định qua nhiều lần chạy","coverImage":null,"summary":"Gần một phần tư câu hỏi trong một khảo sát trên nhiều họ mô hình từng đổi hẳn kết quả chỉ vì đổi seed ngẫu nhiên, dù prompt và nhiệt độ giữ nguyên."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100271, 'Tổng kết đợt phỏng vấn không hỏi thuật toán. Một quy trình phỏng vấn dựa trên bài tập sát việc thật (đọc mã có sẵn, sửa một lỗi cụ thể) được cho là dự đoán hiệu quả công việc tốt hơn câu hỏi thuật toán kinh điển. Câu hỏi kiểu đảo cây nhị phân đo được khả năng nhớ thuật toán, không đo được khả năng đọc hiểu một codebase lạ — kỹ năng chiếm phần lớn thời gian thực tế của một kỹ sư.', 'PUBLIC', 9458, 'ARTICLE', 'APPROVED', '{"title":"Tổng kết đợt phỏng vấn không hỏi thuật toán","coverImage":null,"summary":"Một quy trình phỏng vấn dựa trên bài tập sát việc thật (đọc mã có sẵn, sửa một lỗi cụ thể) được cho là dự đoán hiệu quả công việc tốt hơn câu hỏi thuật toán kinh điển."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100272, 'Bài học sau khi nhận review mà không tự ái. Review là để bắt lỗi trước khi code chạy trên production, không phải để đánh giá năng lực người viết — nhớ điều đó giúp cả hai phía bớt phòng thủ. Hỏi lại ''bạn nghĩ sao về cách này'' thay vì khẳng định ''cách này sai'' mở ra một cuộc thảo luận thay vì một phán quyết.', 'PUBLIC', 9407, 'ARTICLE', 'APPROVED', '{"title":"Bài học sau khi nhận review mà không tự ái","coverImage":null,"summary":"Review là để bắt lỗi trước khi code chạy trên production, không phải để đánh giá năng lực người viết — nhớ điều đó giúp cả hai phía bớt phòng thủ."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100273, 'Ghi chép về dẫn dắt một đội bốn người. Tin tưởng đội tự quyết ở việc nhỏ, chỉ can thiệp ở quyết định khó đảo ngược — can thiệp vào mọi thứ làm chậm cả đội và không ai học được gì. Với một đội bốn người, đồng bộ hằng ngày 15 phút là đủ — vấn đề thường không phải thiếu họp mà là họp sai người, sai lúc.', 'PUBLIC', 9021, 'ARTICLE', 'APPROVED', '{"title":"Ghi chép về dẫn dắt một đội bốn người","coverImage":"${minioUrl}/post-media/posts/100273/cover.png","summary":"Tin tưởng đội tự quyết ở việc nhỏ, chỉ can thiệp ở quyết định khó đảo ngược — can thiệp vào mọi thứ làm chậm cả đội và không ai học được gì."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100274, 'Nhìn lại hành trình viết tài liệu mà người ta chịu đọc. Tài liệu ngắn có ví dụ chạy được luôn được đọc nhiều hơn tài liệu dài giải thích đầy đủ lý thuyết — người đọc tài liệu kỹ thuật thường đang cố giải quyết một việc cụ thể. Đặt câu trả lời ở ngay đầu, giải thích ở dưới — hầu hết người đọc chỉ cần dòng đầu tiên, phần còn lại là cho ai cần đào sâu.', 'PUBLIC', 9194, 'ARTICLE', 'APPROVED', '{"title":"Nhìn lại hành trình viết tài liệu mà người ta chịu đọc","coverImage":null,"summary":"Tài liệu ngắn có ví dụ chạy được luôn được đọc nhiều hơn tài liệu dài giải thích đầy đủ lý thuyết — người đọc tài liệu kỹ thuật thường đang cố giải quyết một việc cụ thể."}'::jsonb, NULL, now() - INTERVAL '6 days', now() - INTERVAL '6 days'),
    (100275, 'Chuyện ước lượng công việc sát hơn, từ đầu tới lúc ổn. Phần việc hay bị bỏ sót khi ước lượng không phải code mà là review, test và xử lý case biên — cộng thêm một hệ số cho những phần này thường chính xác hơn cố đoán đúng ngay từ đầu. So sánh ước lượng cũ với thời gian thực tế đã làm, định kỳ, là cách duy nhất cải thiện độ chính xác ước lượng theo thời gian.', 'PUBLIC', 9417, 'ARTICLE', 'APPROVED', '{"title":"Chuyện ước lượng công việc sát hơn, từ đầu tới lúc ổn","coverImage":null,"summary":"Phần việc hay bị bỏ sót khi ước lượng không phải code mà là review, test và xử lý case biên — cộng thêm một hệ số cho những phần này thường chính xác hơn cố đoán đúng ngay từ đầu."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100276, 'Những gì mình học được khi tối ưu truy vấn N+1. Subselect fetching gom toàn bộ collection của một lượt cha vào đúng một câu truy vấn phụ duy nhất, thay vì một câu riêng cho mỗi cha. Bật @BatchSize (hay default_batch_fetch_size) gom các lượt gọi lazy thành một câu WHERE id IN (...), nên 1.000 bản ghi chỉ còn vài chục truy vấn thay vì một nghìn.', 'PUBLIC', 9061, 'ARTICLE', 'APPROVED', '{"title":"Những gì mình học được khi tối ưu truy vấn N+1","coverImage":null,"summary":"Subselect fetching gom toàn bộ collection của một lượt cha vào đúng một câu truy vấn phụ duy nhất, thay vì một câu riêng cho mỗi cha."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100277, 'Nhật ký chọn TTL cho cache. Rắc thêm 10-20% jitter ngẫu nhiên vào TTL để tránh hàng loạt key hết hạn cùng lúc — nguyên nhân phổ biến nhất của cache stampede. Một khoá mutex ngắn hạn cho đúng một request đi tái tạo cache khi miss, các request còn lại chờ hoặc nhận bản cũ, thay vì để tất cả cùng dội xuống database.', 'PUBLIC', 9001, 'ARTICLE', 'APPROVED', '{"title":"Nhật ký chọn TTL cho cache","coverImage":"${minioUrl}/post-media/posts/100277/cover.png","summary":"Rắc thêm 10-20% jitter ngẫu nhiên vào TTL để tránh hàng loạt key hết hạn cùng lúc — nguyên nhân phổ biến nhất của cache stampede."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100278, 'Kể lại lần đánh index đúng thứ tự cột. Cột dùng so sánh khoảng (>, <, BETWEEN) phải đặt sau cùng trong index tổ hợp — index không dùng được cho cột đứng sau một điều kiện khoảng. Một truy vấn lọc ba cột trên bảng triệu dòng từng đi từ Parallel Seq Scan 17ms xuống Index Only Scan 0,6ms sau khi thêm đúng index tổ hợp khớp thứ tự lọc.', 'PUBLIC', 9214, 'ARTICLE', 'APPROVED', '{"title":"Kể lại lần đánh index đúng thứ tự cột","coverImage":null,"summary":"Cột dùng so sánh khoảng (>, <, BETWEEN) phải đặt sau cùng trong index tổ hợp — index không dùng được cho cột đứng sau một điều kiện khoảng."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100279, 'Tổng kết đợt chuyển sang virtual threads. Sự cố Netflix tháng 7/2024 với virtual thread bắt nguồn từ một khối synchronized ghim virtual thread vào carrier thread, biến một đoạn mã tưởng vô hại thành điểm nghẽn toàn hệ thống. Virtual thread không loại bỏ nút thắt, nó dời nút thắt xuống tầng dưới: khi trần connection pool biến mất, hàng đợi truy vấn database trở thành điểm nghẽn kế tiếp.', 'PUBLIC', 9407, 'ARTICLE', 'APPROVED', '{"title":"Tổng kết đợt chuyển sang virtual threads","coverImage":null,"summary":"Sự cố Netflix tháng 7/2024 với virtual thread bắt nguồn từ một khối synchronized ghim virtual thread vào carrier thread, biến một đoạn mã tưởng vô hại thành điểm nghẽn toàn hệ thống."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100280, 'Bài học sau khi tách monolith thành service. Strangler fig: bọc route cũ sau một lớp proxy rồi chuyển từng phần sang service mới, hệ thống cũ vẫn chạy suốt quá trình chuyển thay vì viết lại toàn bộ cùng lúc. Ranh giới service nên theo bounded context của nghiệp vụ, không theo lớp kỹ thuật — tách riêng ''service database'' hay ''service UI'' là dấu hiệu sai hướng.', 'PUBLIC', 9377, 'ARTICLE', 'APPROVED', '{"title":"Bài học sau khi tách monolith thành service","coverImage":null,"summary":"Strangler fig: bọc route cũ sau một lớp proxy rồi chuyển từng phần sang service mới, hệ thống cũ vẫn chạy suốt quá trình chuyển thay vì viết lại toàn bộ cùng lúc."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100281, 'Ghi chép về thiết kế API phân trang. Cursor phải mã hoá đủ thông tin sắp xếp — không chỉ id — để tránh trùng hoặc bỏ sót dòng khi nhiều bản ghi có cùng giá trị sắp xếp. Trả kèm hasMore thay vì tổng số trang: COUNT(*) trên bảng lớn tốn kém và thường không cần thiết cho một danh sách cuộn vô hạn.', 'PUBLIC', 9435, 'ARTICLE', 'APPROVED', '{"title":"Ghi chép về thiết kế API phân trang","coverImage":"${minioUrl}/post-media/posts/100281/cover.png","summary":"Cursor phải mã hoá đủ thông tin sắp xếp — không chỉ id — để tránh trùng hoặc bỏ sót dòng khi nhiều bản ghi có cùng giá trị sắp xếp."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100282, 'Nhìn lại hành trình xử lý idempotency cho webhook. Cần nhất quán giao dịch thì lưu bản ghi idempotency ngay trong cùng transaction với thay đổi dữ liệu; chỉ cần tốc độ thì Redis với TTL tự dọn là lựa chọn phổ biến hơn. Client gửi kèm Idempotency-Key duy nhất trên header; server lưu key đó cùng kết quả lần xử lý đầu, các lần gọi lại cùng key chỉ trả lại đúng kết quả cũ.', 'PUBLIC', 9011, 'ARTICLE', 'APPROVED', '{"title":"Nhìn lại hành trình xử lý idempotency cho webhook","coverImage":null,"summary":"Cần nhất quán giao dịch thì lưu bản ghi idempotency ngay trong cùng transaction với thay đổi dữ liệu; chỉ cần tốc độ thì Redis với TTL tự dọn là lựa chọn phổ biến hơn."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100283, 'Chuyện chuẩn hoá log có traceId, từ đầu tới lúc ổn. Một traceId sinh ở tầng gateway rồi truyền xuyên suốt qua header HTTP và context của hàng đợi, nối được toàn bộ đường đi của một request qua nhiều service chỉ bằng một lượt tìm log. Không có traceId, một sự cố tail latency chỉ hiện ra như ''p99 tăng'' trên dashboard — không nói được request nào chậm, đi qua service nào, chết ở bước nào.', 'PUBLIC', 9356, 'ARTICLE', 'APPROVED', '{"title":"Chuyện chuẩn hoá log có traceId, từ đầu tới lúc ổn","coverImage":null,"summary":"Một traceId sinh ở tầng gateway rồi truyền xuyên suốt qua header HTTP và context của hàng đợi, nối được toàn bộ đường đi của một request qua nhiều service chỉ bằng một lượt tìm log."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100284, 'Những gì mình học được khi đo p99 thay vì trung bình. p50 200ms và p99 3 giây là chuyện bình thường trên cùng một hệ thống — con số trung bình không kể được câu chuyện đó. Khuếch đại đuôi (tail amplification) xảy ra khi một request chậm ở tầng dưới khiến các lượt retry ở tầng trên dồn lại, biến 1% request chậm thành sự cố toàn hệ thống.', 'PUBLIC', 9133, 'ARTICLE', 'APPROVED', '{"title":"Những gì mình học được khi đo p99 thay vì trung bình","coverImage":null,"summary":"p50 200ms và p99 3 giây là chuyện bình thường trên cùng một hệ thống — con số trung bình không kể được câu chuyện đó."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100285, 'Nhật ký giảm thời gian build CI. Thứ tự ưu tiên đúng: cache trước (không cần đổi kiến trúc, lợi ích lớn nhất), song song hoá sau (cần tái cấu trúc pipeline nhưng lợi ích cộng dồn). Cache node_modules theo hash của lockfile đưa một bước cài đặt phụ thuộc từ 6-12 phút xuống còn 15-30 giây khi cache trúng.', 'PUBLIC', 9010, 'ARTICLE', 'APPROVED', '{"title":"Nhật ký giảm thời gian build CI","coverImage":"${minioUrl}/post-media/posts/100285/cover.png","summary":"Thứ tự ưu tiên đúng: cache trước (không cần đổi kiến trúc, lợi ích lớn nhất), song song hoá sau (cần tái cấu trúc pipeline nhưng lợi ích cộng dồn)."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100286, 'Kể lại lần viết test không phụ thuộc thứ tự. Test phụ thuộc thứ tự thường bắt nguồn từ state tĩnh dùng chung (static field, singleton chưa reset) hoặc dữ liệu test A để lại mà test B vô tình đọc phải. Chạy test với thứ tự ngẫu nhiên mỗi lần là cách nhanh nhất lộ ra test nào đang ngầm phụ thuộc thứ tự chạy trước đó.', 'PUBLIC', 9406, 'ARTICLE', 'APPROVED', '{"title":"Kể lại lần viết test không phụ thuộc thứ tự","coverImage":null,"summary":"Test phụ thuộc thứ tự thường bắt nguồn từ state tĩnh dùng chung (static field, singleton chưa reset) hoặc dữ liệu test A để lại mà test B vô tình đọc phải."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100287, 'Tổng kết đợt mock ít đi, dùng testcontainers. Testcontainers dựng một container Postgres/Redis mới tinh cho mỗi lượt test rồi huỷ ngay sau đó, nên test không dính trạng thái để lại từ lượt chạy trước. Chi phí thật của việc bảo trì mock là độ trôi (drift): schema hay logic nghiệp vụ đổi mà mock không đổi theo, lỗi lọt qua ngay chỗ lẽ ra test phải bắt được.', 'PUBLIC', 9326, 'ARTICLE', 'APPROVED', '{"title":"Tổng kết đợt mock ít đi, dùng testcontainers","coverImage":null,"summary":"Testcontainers dựng một container Postgres/Redis mới tinh cho mỗi lượt test rồi huỷ ngay sau đó, nên test không dính trạng thái để lại từ lượt chạy trước."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100288, 'Bài học sau khi dựng design token dùng chung. Đổi một token màu ở đúng một chỗ và mọi nền tảng cập nhật theo, thay vì phải tìm-và-thay từng giá trị hex rải rác trong code. Design token tách biến thiết kế (màu, khoảng cách, kiểu chữ) khỏi từng nền tảng, rồi biên dịch ra native code riêng cho iOS, Android và web từ đúng một nguồn.', 'PUBLIC', 9179, 'ARTICLE', 'APPROVED', '{"title":"Bài học sau khi dựng design token dùng chung","coverImage":null,"summary":"Đổi một token màu ở đúng một chỗ và mọi nền tảng cập nhật theo, thay vì phải tìm-và-thay từng giá trị hex rải rác trong code."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100289, 'Ghi chép về giảm layout shift. Telegraph Media Group cải thiện CLS ở phân vị 75 từ 0,25 xuống 0,1, kéo tỉ lệ trang đạt chuẩn Core Web Vitals từ 57% lên 72%, theo case study với Google. Đặt trước kích thước (width/height hoặc aspect-ratio) cho ảnh và khối quảng cáo là cách rẻ nhất để trình duyệt chừa đúng chỗ trước khi nội dung tải xong.', 'PUBLIC', 9163, 'ARTICLE', 'APPROVED', '{"title":"Ghi chép về giảm layout shift","coverImage":"${minioUrl}/post-media/posts/100289/cover.png","summary":"Telegraph Media Group cải thiện CLS ở phân vị 75 từ 0,25 xuống 0,1, kéo tỉ lệ trang đạt chuẩn Core Web Vitals từ 57% lên 72%, theo case study với Google."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100290, 'Nhìn lại hành trình làm form truy cập được bằng bàn phím. Làm một menu thả xuống thật sự dùng được bằng bàn phím theo đúng WCAG 2.2 từng mất hàng chục lượt chỉnh sửa — phần khó nhất là đồng bộ đúng phần tử có focus với đúng phần tử trình đọc màn hình công bố. Thứ tự Tab phải theo đúng thứ tự đọc hợp lý trên giao diện, không theo thứ tự khai trong DOM nếu CSS đã sắp xếp lại vị trí hiển thị.', 'PUBLIC', 9170, 'ARTICLE', 'APPROVED', '{"title":"Nhìn lại hành trình làm form truy cập được bằng bàn phím","coverImage":null,"summary":"Làm một menu thả xuống thật sự dùng được bằng bàn phím theo đúng WCAG 2.2 từng mất hàng chục lượt chỉnh sửa — phần khó nhất là đồng bộ đúng phần tử có focus với đúng phần tử trình đọc màn hình công bố."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100291, 'Chuyện chia bundle theo route, từ đầu tới lúc ổn. Phân tích bundle bằng công cụ visualizer thường lộ ra một thư viện ngoài dự tính chiếm phần lớn dung lượng — kiểu import cả một thư viện ngày tháng chỉ để dùng một hàm format. Code splitting theo route chỉ tải phần JavaScript cần cho trang đang xem, thay vì gộp toàn bộ ứng dụng vào một bundle duy nhất tải ngay từ lần đầu.', 'PUBLIC', 9132, 'ARTICLE', 'APPROVED', '{"title":"Chuyện chia bundle theo route, từ đầu tới lúc ổn","coverImage":null,"summary":"Phân tích bundle bằng công cụ visualizer thường lộ ra một thư viện ngoài dự tính chiếm phần lớn dung lượng — kiểu import cả một thư viện ngày tháng chỉ để dùng một hàm format."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100292, 'Những gì mình học được khi quản lý state không cần thư viện. State của server (dữ liệu fetch), state URL và state UI cục bộ nên xử lý bằng cách khác nhau — không có một công cụ nào hợp cho mọi loại state. useReducer hợp khi một state có từ bốn hành động trở lên hoặc các trường phụ thuộc lẫn nhau; tách state và dispatch thành hai context riêng để component chỉ gọi dispatch không bị render lại mỗi khi state đổi.', 'PUBLIC', 9343, 'ARTICLE', 'APPROVED', '{"title":"Những gì mình học được khi quản lý state không cần thư viện","coverImage":null,"summary":"State của server (dữ liệu fetch), state URL và state UI cục bộ nên xử lý bằng cách khác nhau — không có một công cụ nào hợp cho mọi loại state."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100293, 'Nhật ký đồng bộ dữ liệu khi mất mạng. CRDT giải quyết xung đột cấu trúc dữ liệu, không giải quyết xung đột nghiệp vụ — hai người cùng sửa giá một sản phẩm thì hợp nhất kỹ thuật xong vẫn cần logic nghiệp vụ quyết định giá nào đúng. PowerSync, Realm Sync và replication kiểu CouchDB là các nền tảng offline-first đang chạy production thật, dùng CRDT hoặc conflict resolution theo revision.', 'PUBLIC', 9244, 'ARTICLE', 'APPROVED', '{"title":"Nhật ký đồng bộ dữ liệu khi mất mạng","coverImage":"${minioUrl}/post-media/posts/100293/cover.png","summary":"CRDT giải quyết xung đột cấu trúc dữ liệu, không giải quyết xung đột nghiệp vụ — hai người cùng sửa giá một sản phẩm thì hợp nhất kỹ thuật xong vẫn cần logic nghiệp vụ quyết định giá nào đúng."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100294, 'Kể lại lần giảm kích thước app. Phần lớn dung lượng dư thừa nằm ở tài nguyên (ảnh độ phân giải cao không cần thiết, font không dùng) nhiều hơn là ở chính code. Android App Bundle giảm trung bình khoảng 35% dung lượng tải về vì chỉ đóng gói đúng phần tài nguyên khớp thiết bị người dùng, thay vì mọi biến thể màn hình/kiến trúc CPU.', 'PUBLIC', 9089, 'ARTICLE', 'APPROVED', '{"title":"Kể lại lần giảm kích thước app","coverImage":null,"summary":"Phần lớn dung lượng dư thừa nằm ở tài nguyên (ảnh độ phân giải cao không cần thiết, font không dùng) nhiều hơn là ở chính code."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100295, 'Tổng kết đợt bảo mật token trên thiết bị. iOS Keychain và Android Keystore mã hoá secret bằng khoá sinh trong phần cứng bảo mật (Secure Enclave / TEE), nên kể cả thiết bị bị chiếm quyền cũng khó trích xuất trực tiếp khoá gốc. Chỉ một phần rất nhỏ ứng dụng xử lý dữ liệu nhạy cảm dùng đúng mức bảo vệ phần cứng mạnh nhất — phần lớn vẫn lưu token ở mức bảo vệ yếu hơn dù nền tảng đã hỗ trợ sẵn.', 'PUBLIC', 9473, 'ARTICLE', 'APPROVED', '{"title":"Tổng kết đợt bảo mật token trên thiết bị","coverImage":null,"summary":"iOS Keychain và Android Keystore mã hoá secret bằng khoá sinh trong phần cứng bảo mật (Secure Enclave / TEE), nên kể cả thiết bị bị chiếm quyền cũng khó trích xuất trực tiếp khoá gốc."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100296, 'Bài học sau khi rà soát phụ thuộc bên thứ ba. Một gói npm nhỏ với hàng triệu lượt tải mỗi tuần từng bị chiếm quyền để phát tán mã độc, cho thấy kể cả gói ít ai để ý cũng có thể là điểm vào của toàn bộ chuỗi cung ứng. Dependabot và các công cụ tương tự không chỉ báo lỗ hổng ở dependency trực tiếp mà còn dò tới tận dependency gián tiếp, tự tạo PR nâng phiên bản gốc để kéo theo bản vá.', 'PUBLIC', 9253, 'ARTICLE', 'APPROVED', '{"title":"Bài học sau khi rà soát phụ thuộc bên thứ ba","coverImage":null,"summary":"Một gói npm nhỏ với hàng triệu lượt tải mỗi tuần từng bị chiếm quyền để phát tán mã độc, cho thấy kể cả gói ít ai để ý cũng có thể là điểm vào của toàn bộ chuỗi cung ứng."}'::jsonb, NULL, now() - INTERVAL '7 days', now() - INTERVAL '7 days'),
    (100297, 'Ghi chép về dựng pipeline triển khai xanh-lam. Đổi lại tốc độ rollback, chi phí là gấp đôi hạ tầng trong lúc chuyển đổi vì cả hai môi trường đều phải chạy đồng thời. Hai môi trường production giống hệt nhau — một đang chạy, một đứng chờ. Bản mới lên môi trường chờ, kiểm xong thì load balancer chuyển hướng traffic sang đó.', 'PUBLIC', 9448, 'ARTICLE', 'APPROVED', '{"title":"Ghi chép về dựng pipeline triển khai xanh-lam","coverImage":"${minioUrl}/post-media/posts/100297/cover.png","summary":"Đổi lại tốc độ rollback, chi phí là gấp đôi hạ tầng trong lúc chuyển đổi vì cả hai môi trường đều phải chạy đồng thời."}'::jsonb, NULL, now() - INTERVAL '8 days', now() - INTERVAL '8 days'),
    (100298, 'Nhìn lại hành trình đặt resource limit cho pod. Exit code 137 trong kubectl describe pod gần như luôn là OOMKilled — kernel Linux giết tiến trình khi vượt giới hạn bộ nhớ đã khai. Đặt memory limit bằng đúng memory request là khuyến nghị chuẩn: bộ nhớ là tài nguyên không nén được, một khi đã cấp cho pod thì chỉ lấy lại được bằng cách giết pod.', 'PUBLIC', 9438, 'ARTICLE', 'APPROVED', '{"title":"Nhìn lại hành trình đặt resource limit cho pod","coverImage":null,"summary":"Exit code 137 trong kubectl describe pod gần như luôn là OOMKilled — kernel Linux giết tiến trình khi vượt giới hạn bộ nhớ đã khai."}'::jsonb, NULL, now() - INTERVAL '8 days', now() - INTERVAL '8 days'),
    (100299, 'Chuyện chuyển state Terraform lên remote, từ đầu tới lúc ổn. Di trú state không downtime: bật đồng thời use_lockfile và dynamodb_table trong một giai đoạn chuyển tiếp, đợi mọi máy lên Terraform 1.11 trở lên rồi mới bỏ dynamodb_table. State cục bộ không có khoá: hai người chạy terraform apply cùng lúc có thể ghi đè state của nhau — backend từ xa giải đúng vấn đề này bằng khoá tập trung.', 'PUBLIC', 9375, 'ARTICLE', 'APPROVED', '{"title":"Chuyện chuyển state Terraform lên remote, từ đầu tới lúc ổn","coverImage":null,"summary":"Di trú state không downtime: bật đồng thời use_lockfile và dynamodb_table trong một giai đoạn chuyển tiếp, đợi mọi máy lên Terraform 1.11 trở lên rồi mới bỏ dynamodb_table."}'::jsonb, NULL, now() - INTERVAL '8 days', now() - INTERVAL '8 days'),
    (100300, 'Những gì mình học được khi giảm hoá đơn cloud. Xoá dữ liệu test còn sót trên môi trường production-like và đặt lịch tắt máy dev ngoài giờ làm việc là hai khoản tiết kiệm rẻ nhất nhưng hay bị bỏ qua nhất. Nhiều đội đạt mức giảm 25-40% chi phí cloud trong 90 ngày đầu chỉ bằng rightsizing và dọn tài nguyên nhàn rỗi, chưa cần tái kiến trúc.', 'PUBLIC', 9316, 'ARTICLE', 'APPROVED', '{"title":"Những gì mình học được khi giảm hoá đơn cloud","coverImage":null,"summary":"Xoá dữ liệu test còn sót trên môi trường production-like và đặt lịch tắt máy dev ngoài giờ làm việc là hai khoản tiết kiệm rẻ nhất nhưng hay bị bỏ qua nhất."}'::jsonb, NULL, now() - INTERVAL '8 days', now() - INTERVAL '8 days'),
    (100301, 'Nhật ký đưa mô hình từ notebook lên production. Công cụ kiểm dữ liệu tối ưu cho notebook thường thêm độ trễ không chấp nhận được khi ép chạy trong một pipeline real-time — công cụ hợp cho notebook chưa chắc hợp cho production. Data drift là khi phân phối thống kê của dữ liệu đầu vào đổi theo thời gian; concept drift là khi chính mối quan hệ giữa đầu vào và đầu ra đổi — hai loại trôi cần chiến lược phát hiện khác nhau.', 'PUBLIC', 9170, 'ARTICLE', 'APPROVED', '{"title":"Nhật ký đưa mô hình từ notebook lên production","coverImage":"${minioUrl}/post-media/posts/100301/cover.png","summary":"Công cụ kiểm dữ liệu tối ưu cho notebook thường thêm độ trễ không chấp nhận được khi ép chạy trong một pipeline real-time — công cụ hợp cho notebook chưa chắc hợp cho production."}'::jsonb, NULL, now() - INTERVAL '8 days', now() - INTERVAL '8 days'),
    (100302, 'Kể lại lần làm sạch dữ liệu đầu vào. Kiểm tra tính hợp lệ nên chạy ngay ở điểm nạp dữ liệu, không phải đợi tới lúc mô hình huấn luyện xong mới phát hiện dữ liệu bẩn. Phần lớn thời gian của một dự án dữ liệu thực tế nằm ở làm sạch và chuẩn hoá, không nằm ở chọn thuật toán — quan sát này lặp lại ở gần như mọi khảo sát ngành khoa học dữ liệu.', 'PUBLIC', 9041, 'ARTICLE', 'APPROVED', '{"title":"Kể lại lần làm sạch dữ liệu đầu vào","coverImage":null,"summary":"Kiểm tra tính hợp lệ nên chạy ngay ở điểm nạp dữ liệu, không phải đợi tới lúc mô hình huấn luyện xong mới phát hiện dữ liệu bẩn."}'::jsonb, NULL, now() - INTERVAL '8 days', now() - INTERVAL '8 days'),
    (100303, 'Tổng kết đợt chọn giữa batch và streaming. Câu hỏi cần trả lời trước khi chọn không phải ''công nghệ nào mạnh hơn'' mà là ''nghiệp vụ có thực sự cần kết quả trong vài giây, hay vài giờ là đủ'' — phần lớn báo cáo nội bộ không cần streaming. Batch xử lý dữ liệu theo lô định kỳ — đơn giản vận hành, độ trễ cao; streaming xử lý từng sự kiện gần như ngay lập tức — độ trễ thấp, đổi lại phức tạp hơn khi xử lý lỗi.', 'PUBLIC', 9142, 'ARTICLE', 'APPROVED', '{"title":"Tổng kết đợt chọn giữa batch và streaming","coverImage":null,"summary":"Câu hỏi cần trả lời trước khi chọn không phải ''công nghệ nào mạnh hơn'' mà là ''nghiệp vụ có thực sự cần kết quả trong vài giây, hay vài giờ là đủ'' — phần lớn báo cáo nội bộ không cần streaming."}'::jsonb, NULL, now() - INTERVAL '8 days', now() - INTERVAL '8 days'),
    (100304, 'Bài học sau khi đánh giá chất lượng embedding. MTEB đo tám loại tác vụ trên hàng chục bộ dữ liệu và hơn trăm ngôn ngữ, nhưng cho RAG chỉ tác vụ retrieval là quan trọng — điểm MTEB tổng có thể đánh lừa nếu mô hình mạnh ở phân loại nhưng yếu ở tìm kiếm. NDCG@10 là chỉ số nên dùng chính cho retrieval: nó đo cả việc có tìm đúng tài liệu hay không lẫn tài liệu đó đứng ở vị trí nào trong kết quả trả về.', 'PUBLIC', 9354, 'ARTICLE', 'APPROVED', '{"title":"Bài học sau khi đánh giá chất lượng embedding","coverImage":null,"summary":"MTEB đo tám loại tác vụ trên hàng chục bộ dữ liệu và hơn trăm ngôn ngữ, nhưng cho RAG chỉ tác vụ retrieval là quan trọng — điểm MTEB tổng có thể đánh lừa nếu mô hình mạnh ở phân loại nhưng yếu ở tìm kiếm."}'::jsonb, NULL, now() - INTERVAL '8 days', now() - INTERVAL '8 days'),
    (100305, 'Ghi chép về viết prompt ổn định qua nhiều lần chạy. Ngay cả ở temperature 0 với cùng seed và cùng prompt, một số mô hình vẫn cho câu trả lời khác nhau giữa các lần chạy — ''xác định'' trên lý thuyết không luôn đúng trên thực tế triển khai. Gần một phần tư câu hỏi trong một khảo sát trên nhiều họ mô hình từng đổi hẳn kết quả chỉ vì đổi seed ngẫu nhiên, dù prompt và nhiệt độ giữ nguyên.', 'PUBLIC', 9289, 'ARTICLE', 'APPROVED', '{"title":"Ghi chép về viết prompt ổn định qua nhiều lần chạy","coverImage":"${minioUrl}/post-media/posts/100305/cover.png","summary":"Ngay cả ở temperature 0 với cùng seed và cùng prompt, một số mô hình vẫn cho câu trả lời khác nhau giữa các lần chạy — ''xác định'' trên lý thuyết không luôn đúng trên thực tế triển khai."}'::jsonb, NULL, now() - INTERVAL '8 days', now() - INTERVAL '8 days'),
    (100306, 'Nhìn lại hành trình phỏng vấn không hỏi thuật toán. Cho ứng viên xem một đoạn mã thật (ẩn danh) và hỏi họ sẽ đổi gì, vì sao — câu trả lời lộ ra cách nghĩ về đánh đổi nhiều hơn một bài toán chuẩn hoá sẵn. Một quy trình phỏng vấn dựa trên bài tập sát việc thật (đọc mã có sẵn, sửa một lỗi cụ thể) được cho là dự đoán hiệu quả công việc tốt hơn câu hỏi thuật toán kinh điển.', 'PUBLIC', 9011, 'ARTICLE', 'APPROVED', '{"title":"Nhìn lại hành trình phỏng vấn không hỏi thuật toán","coverImage":null,"summary":"Cho ứng viên xem một đoạn mã thật (ẩn danh) và hỏi họ sẽ đổi gì, vì sao — câu trả lời lộ ra cách nghĩ về đánh đổi nhiều hơn một bài toán chuẩn hoá sẵn."}'::jsonb, NULL, now() - INTERVAL '8 days', now() - INTERVAL '8 days'),
    (100307, 'Chuyện nhận review mà không tự ái, từ đầu tới lúc ổn. Tách người khỏi đoạn mã: một comment review nói về ''đoạn code này'' chứ không phải ''bạn đã làm sai'' giữ được cuộc trao đổi ở mức kỹ thuật thay vì cá nhân. Review là để bắt lỗi trước khi code chạy trên production, không phải để đánh giá năng lực người viết — nhớ điều đó giúp cả hai phía bớt phòng thủ.', 'PUBLIC', 9072, 'ARTICLE', 'APPROVED', '{"title":"Chuyện nhận review mà không tự ái, từ đầu tới lúc ổn","coverImage":null,"summary":"Tách người khỏi đoạn mã: một comment review nói về ''đoạn code này'' chứ không phải ''bạn đã làm sai'' giữ được cuộc trao đổi ở mức kỹ thuật thay vì cá nhân."}'::jsonb, NULL, now() - INTERVAL '8 days', now() - INTERVAL '8 days'),
    (100308, 'Những gì mình học được khi dẫn dắt một đội bốn người. Việc khó nhất của người dẫn dắt nhóm nhỏ không phải phân công việc mà là quyết định việc nào KHÔNG làm — phạm vi hẹp nhưng rõ luôn thắng phạm vi rộng nhưng mơ hồ. Tin tưởng đội tự quyết ở việc nhỏ, chỉ can thiệp ở quyết định khó đảo ngược — can thiệp vào mọi thứ làm chậm cả đội và không ai học được gì.', 'PUBLIC', 9316, 'ARTICLE', 'APPROVED', '{"title":"Những gì mình học được khi dẫn dắt một đội bốn người","coverImage":null,"summary":"Việc khó nhất của người dẫn dắt nhóm nhỏ không phải phân công việc mà là quyết định việc nào KHÔNG làm — phạm vi hẹp nhưng rõ luôn thắng phạm vi rộng nhưng mơ hồ."}'::jsonb, NULL, now() - INTERVAL '8 days', now() - INTERVAL '8 days'),
    (100309, 'Nhật ký viết tài liệu mà người ta chịu đọc. Tài liệu lỗi thời còn tệ hơn không có tài liệu vì nó khiến người đọc tin nhầm — gắn ngày cập nhật cuối giúp người đọc tự đánh giá độ tin cậy. Tài liệu ngắn có ví dụ chạy được luôn được đọc nhiều hơn tài liệu dài giải thích đầy đủ lý thuyết — người đọc tài liệu kỹ thuật thường đang cố giải quyết một việc cụ thể.', 'PUBLIC', 9448, 'ARTICLE', 'APPROVED', '{"title":"Nhật ký viết tài liệu mà người ta chịu đọc","coverImage":"${minioUrl}/post-media/posts/100309/cover.png","summary":"Tài liệu lỗi thời còn tệ hơn không có tài liệu vì nó khiến người đọc tin nhầm — gắn ngày cập nhật cuối giúp người đọc tự đánh giá độ tin cậy."}'::jsonb, NULL, now() - INTERVAL '8 days', now() - INTERVAL '8 days'),
    (100310, 'Kể lại lần ước lượng công việc sát hơn. Ước lượng theo khoảng thành thật hơn một con số duy nhất — con số duy nhất tạo cảm giác chắc chắn giả trong khi thực tế luôn có phương sai. Phần việc hay bị bỏ sót khi ước lượng không phải code mà là review, test và xử lý case biên — cộng thêm một hệ số cho những phần này thường chính xác hơn cố đoán đúng ngay từ đầu.', 'PUBLIC', 9001, 'ARTICLE', 'APPROVED', '{"title":"Kể lại lần ước lượng công việc sát hơn","coverImage":null,"summary":"Ước lượng theo khoảng thành thật hơn một con số duy nhất — con số duy nhất tạo cảm giác chắc chắn giả trong khi thực tế luôn có phương sai."}'::jsonb, NULL, now() - INTERVAL '8 days', now() - INTERVAL '8 days'),
    (100311, 'Tổng kết đợt tối ưu truy vấn N+1. JOIN FETCH giải đúng một quan hệ trong một câu truy vấn, nhưng đổi FetchType sang EAGER để né N+1 chỉ khiến nó nặng hơn — Hibernate vẫn phát sinh truy vấn phụ cho từng dòng. Subselect fetching gom toàn bộ collection của một lượt cha vào đúng một câu truy vấn phụ duy nhất, thay vì một câu riêng cho mỗi cha.', 'PUBLIC', 9122, 'ARTICLE', 'APPROVED', '{"title":"Tổng kết đợt tối ưu truy vấn N+1","coverImage":null,"summary":"JOIN FETCH giải đúng một quan hệ trong một câu truy vấn, nhưng đổi FetchType sang EAGER để né N+1 chỉ khiến nó nặng hơn — Hibernate vẫn phát sinh truy vấn phụ cho từng dòng."}'::jsonb, NULL, now() - INTERVAL '8 days', now() - INTERVAL '8 days'),
    (100312, 'Bài học sau khi chọn TTL cho cache. Stale-while-revalidate trả ngay giá trị đã hết hạn cho người dùng trong lúc một tiến trình nền âm thầm làm mới, nên không request nào phải chờ origin. Rắc thêm 10-20% jitter ngẫu nhiên vào TTL để tránh hàng loạt key hết hạn cùng lúc — nguyên nhân phổ biến nhất của cache stampede.', 'PUBLIC', 9143, 'ARTICLE', 'APPROVED', '{"title":"Bài học sau khi chọn TTL cho cache","coverImage":null,"summary":"Stale-while-revalidate trả ngay giá trị đã hết hạn cho người dùng trong lúc một tiến trình nền âm thầm làm mới, nên không request nào phải chờ origin."}'::jsonb, NULL, now() - INTERVAL '8 days', now() - INTERVAL '8 days'),
    (100313, 'Ghi chép về đánh index đúng thứ tự cột. Quy tắc leftmost prefix: một index tổ hợp chỉ dùng được cho truy vấn lọc đúng các cột nằm ở đầu index, theo đúng thứ tự khai. Cột dùng so sánh khoảng (>, <, BETWEEN) phải đặt sau cùng trong index tổ hợp — index không dùng được cho cột đứng sau một điều kiện khoảng.', 'PUBLIC', 9387, 'ARTICLE', 'APPROVED', '{"title":"Ghi chép về đánh index đúng thứ tự cột","coverImage":"${minioUrl}/post-media/posts/100313/cover.png","summary":"Quy tắc leftmost prefix: một index tổ hợp chỉ dùng được cho truy vấn lọc đúng các cột nằm ở đầu index, theo đúng thứ tự khai."}'::jsonb, NULL, now() - INTERVAL '8 days', now() - INTERVAL '8 days'),
    (100314, 'Nhìn lại hành trình chuyển sang virtual threads. ThreadLocal dùng sai với virtual thread gây rò rỉ bộ nhớ âm thầm — virtual thread không được gộp lại (pool) như platform thread nên state cũ không bao giờ được dọn. Sự cố Netflix tháng 7/2024 với virtual thread bắt nguồn từ một khối synchronized ghim virtual thread vào carrier thread, biến một đoạn mã tưởng vô hại thành điểm nghẽn toàn hệ thống.', 'PUBLIC', 9100, 'ARTICLE', 'APPROVED', '{"title":"Nhìn lại hành trình chuyển sang virtual threads","coverImage":null,"summary":"ThreadLocal dùng sai với virtual thread gây rò rỉ bộ nhớ âm thầm — virtual thread không được gộp lại (pool) như platform thread nên state cũ không bao giờ được dọn."}'::jsonb, NULL, now() - INTERVAL '8 days', now() - INTERVAL '8 days'),
    (100315, 'Chuyện tách monolith thành service, từ đầu tới lúc ổn. Chi phí ẩn lớn nhất không nằm ở hạ tầng mà ở giao tiếp giữa các service: một transaction từng gọn trong một câu SQL giờ cần saga hoặc outbox pattern để giữ nhất quán. Strangler fig: bọc route cũ sau một lớp proxy rồi chuyển từng phần sang service mới, hệ thống cũ vẫn chạy suốt quá trình chuyển thay vì viết lại toàn bộ cùng lúc.', 'PUBLIC', 9242, 'ARTICLE', 'APPROVED', '{"title":"Chuyện tách monolith thành service, từ đầu tới lúc ổn","coverImage":null,"summary":"Chi phí ẩn lớn nhất không nằm ở hạ tầng mà ở giao tiếp giữa các service: một transaction từng gọn trong một câu SQL giờ cần saga hoặc outbox pattern để giữ nhất quán."}'::jsonb, NULL, now() - INTERVAL '8 days', now() - INTERVAL '8 days'),
    (100316, 'Những gì mình học được khi thiết kế API phân trang. Phân trang theo offset (LIMIT/OFFSET) chậm dần khi offset lớn vì database vẫn phải quét qua các dòng bị bỏ; phân trang theo cursor giữ tốc độ ổn định bất kể trang thứ mấy. Cursor phải mã hoá đủ thông tin sắp xếp — không chỉ id — để tránh trùng hoặc bỏ sót dòng khi nhiều bản ghi có cùng giá trị sắp xếp.', 'PUBLIC', 9255, 'ARTICLE', 'APPROVED', '{"title":"Những gì mình học được khi thiết kế API phân trang","coverImage":null,"summary":"Phân trang theo offset (LIMIT/OFFSET) chậm dần khi offset lớn vì database vẫn phải quét qua các dòng bị bỏ; phân trang theo cursor giữ tốc độ ổn định bất kể trang thứ mấy."}'::jsonb, NULL, now() - INTERVAL '8 days', now() - INTERVAL '8 days'),
    (100317, 'Nhật ký xử lý idempotency cho webhook. Webhook luôn giao theo kiểu ''ít nhất một lần'' — chắc chắn có lúc nhận trùng sự kiện, nên mọi payload đứng đắn đều mang kèm một event id duy nhất để nhận diện. Cần nhất quán giao dịch thì lưu bản ghi idempotency ngay trong cùng transaction với thay đổi dữ liệu; chỉ cần tốc độ thì Redis với TTL tự dọn là lựa chọn phổ biến hơn.', 'PUBLIC', 9255, 'ARTICLE', 'APPROVED', '{"title":"Nhật ký xử lý idempotency cho webhook","coverImage":"${minioUrl}/post-media/posts/100317/cover.png","summary":"Webhook luôn giao theo kiểu ''ít nhất một lần'' — chắc chắn có lúc nhận trùng sự kiện, nên mọi payload đứng đắn đều mang kèm một event id duy nhất để nhận diện."}'::jsonb, NULL, now() - INTERVAL '9 days', now() - INTERVAL '9 days'),
    (100318, 'Kể lại lần chuẩn hoá log có traceId. MDC (Mapped Diagnostic Context) của SLF4J gắn traceId vào mọi dòng log trong cùng luồng xử lý mà không cần truyền tay qua từng hàm. Một traceId sinh ở tầng gateway rồi truyền xuyên suốt qua header HTTP và context của hàng đợi, nối được toàn bộ đường đi của một request qua nhiều service chỉ bằng một lượt tìm log.', 'PUBLIC', 9183, 'ARTICLE', 'APPROVED', '{"title":"Kể lại lần chuẩn hoá log có traceId","coverImage":null,"summary":"MDC (Mapped Diagnostic Context) của SLF4J gắn traceId vào mọi dòng log trong cùng luồng xử lý mà không cần truyền tay qua từng hàm."}'::jsonb, NULL, now() - INTERVAL '9 days', now() - INTERVAL '9 days'),
    (100319, 'Tổng kết đợt đo p99 thay vì trung bình. Độ trễ không phân phối chuẩn mà lệch đuôi dài: một số ít request rất chậm (GC pause, cold start, retry, tranh chấp khoá) đủ sức kéo dài đuôi mà không ảnh hưởng tới trung bình. p50 200ms và p99 3 giây là chuyện bình thường trên cùng một hệ thống — con số trung bình không kể được câu chuyện đó.', 'PUBLIC', 9486, 'ARTICLE', 'APPROVED', '{"title":"Tổng kết đợt đo p99 thay vì trung bình","coverImage":null,"summary":"Độ trễ không phân phối chuẩn mà lệch đuôi dài: một số ít request rất chậm (GC pause, cold start, retry, tranh chấp khoá) đủ sức kéo dài đuôi mà không ảnh hưởng tới trung bình."}'::jsonb, NULL, now() - INTERVAL '9 days', now() - INTERVAL '9 days'),
    (100320, 'Bài học sau khi giảm thời gian build CI. Tách một job chạy tuần tự trên 14 máy thành ba job song song từng đưa build time từ 24 phút xuống còn 8 phút, không đổi logic build. Thứ tự ưu tiên đúng: cache trước (không cần đổi kiến trúc, lợi ích lớn nhất), song song hoá sau (cần tái cấu trúc pipeline nhưng lợi ích cộng dồn).', 'PUBLIC', 9179, 'ARTICLE', 'APPROVED', '{"title":"Bài học sau khi giảm thời gian build CI","coverImage":null,"summary":"Tách một job chạy tuần tự trên 14 máy thành ba job song song từng đưa build time từ 24 phút xuống còn 8 phút, không đổi logic build."}'::jsonb, NULL, now() - INTERVAL '9 days', now() - INTERVAL '9 days'),
    (100321, 'Ghi chép về viết test không phụ thuộc thứ tự. Mỗi test nên tự dựng dữ liệu của mình rồi tự dọn sau khi chạy, thay vì tin vào thứ tự chạy trước đó để lại đúng trạng thái cần. Test phụ thuộc thứ tự thường bắt nguồn từ state tĩnh dùng chung (static field, singleton chưa reset) hoặc dữ liệu test A để lại mà test B vô tình đọc phải.', 'PUBLIC', 9448, 'ARTICLE', 'APPROVED', '{"title":"Ghi chép về viết test không phụ thuộc thứ tự","coverImage":"${minioUrl}/post-media/posts/100321/cover.png","summary":"Mỗi test nên tự dựng dữ liệu của mình rồi tự dọn sau khi chạy, thay vì tin vào thứ tự chạy trước đó để lại đúng trạng thái cần."}'::jsonb, NULL, now() - INTERVAL '9 days', now() - INTERVAL '9 days'),
    (100322, 'Nhìn lại hành trình mock ít đi, dùng testcontainers. Mock database không bắt được lỗi migration, connection pool hay timeout thật — những thứ chỉ hiện ra khi chạy trên một instance database thật. Testcontainers dựng một container Postgres/Redis mới tinh cho mỗi lượt test rồi huỷ ngay sau đó, nên test không dính trạng thái để lại từ lượt chạy trước.', 'PUBLIC', 9279, 'ARTICLE', 'APPROVED', '{"title":"Nhìn lại hành trình mock ít đi, dùng testcontainers","coverImage":null,"summary":"Mock database không bắt được lỗi migration, connection pool hay timeout thật — những thứ chỉ hiện ra khi chạy trên một instance database thật."}'::jsonb, NULL, now() - INTERVAL '9 days', now() - INTERVAL '9 days'),
    (100323, 'Chuyện dựng design token dùng chung, từ đầu tới lúc ổn. Airbnb xây một hệ ngôn ngữ thiết kế dùng chung thay vì ba hệ riêng cho ba nền tảng, đổi lại là một nguồn sự thật duy nhất cho mọi token. Đổi một token màu ở đúng một chỗ và mọi nền tảng cập nhật theo, thay vì phải tìm-và-thay từng giá trị hex rải rác trong code.', 'PUBLIC', 9071, 'ARTICLE', 'APPROVED', '{"title":"Chuyện dựng design token dùng chung, từ đầu tới lúc ổn","coverImage":null,"summary":"Airbnb xây một hệ ngôn ngữ thiết kế dùng chung thay vì ba hệ riêng cho ba nền tảng, đổi lại là một nguồn sự thật duy nhất cho mọi token."}'::jsonb, NULL, now() - INTERVAL '9 days', now() - INTERVAL '9 days'),
    (100324, 'Những gì mình học được khi giảm layout shift. Một mức giảm CLS 0,1 tương ứng khoảng 1-2% tăng engagement trong một số nghiên cứu — người đọc không còn bị nội dung ''nhảy'' ngay lúc định bấm. Telegraph Media Group cải thiện CLS ở phân vị 75 từ 0,25 xuống 0,1, kéo tỉ lệ trang đạt chuẩn Core Web Vitals từ 57% lên 72%, theo case study với Google.', 'PUBLIC', 9192, 'ARTICLE', 'APPROVED', '{"title":"Những gì mình học được khi giảm layout shift","coverImage":null,"summary":"Một mức giảm CLS 0,1 tương ứng khoảng 1-2% tăng engagement trong một số nghiên cứu — người đọc không còn bị nội dung ''nhảy'' ngay lúc định bấm."}'::jsonb, NULL, now() - INTERVAL '9 days', now() - INTERVAL '9 days'),
    (100325, 'Nhật ký làm form truy cập được bằng bàn phím. WCAG 2.1.1 đòi mọi phần tử tương tác dùng được trọn vẹn chỉ bằng bàn phím: Tab/Shift+Tab di chuyển focus, Enter kích hoạt, phím mũi tên điều hướng trong dropdown và radio. Làm một menu thả xuống thật sự dùng được bằng bàn phím theo đúng WCAG 2.2 từng mất hàng chục lượt chỉnh sửa — phần khó nhất là đồng bộ đúng phần tử có focus với đúng phần tử trình đọc màn hình công bố.', 'PUBLIC', 9291, 'ARTICLE', 'APPROVED', '{"title":"Nhật ký làm form truy cập được bằng bàn phím","coverImage":"${minioUrl}/post-media/posts/100325/cover.png","summary":"WCAG 2.1.1 đòi mọi phần tử tương tác dùng được trọn vẹn chỉ bằng bàn phím: Tab/Shift+Tab di chuyển focus, Enter kích hoạt, phím mũi tên điều hướng trong dropdown và radio."}'::jsonb, NULL, now() - INTERVAL '9 days', now() - INTERVAL '9 days'),
    (100326, 'Kể lại lần chia bundle theo route. Lazy import một component nặng (biểu đồ, trình soạn thảo rich text) chỉ khi người dùng thực sự mở tới nó, thay vì buộc ai cũng tải nó dù không bao giờ chạm tới. Phân tích bundle bằng công cụ visualizer thường lộ ra một thư viện ngoài dự tính chiếm phần lớn dung lượng — kiểu import cả một thư viện ngày tháng chỉ để dùng một hàm format.', 'PUBLIC', 9244, 'ARTICLE', 'APPROVED', '{"title":"Kể lại lần chia bundle theo route","coverImage":null,"summary":"Lazy import một component nặng (biểu đồ, trình soạn thảo rich text) chỉ khi người dùng thực sự mở tới nó, thay vì buộc ai cũng tải nó dù không bao giờ chạm tới."}'::jsonb, NULL, now() - INTERVAL '9 days', now() - INTERVAL '9 days'),
    (100327, 'Tổng kết đợt quản lý state không cần thư viện. useContext một mình chỉ cấp quyền truy cập toàn cục, không có cấu trúc; useReducer một mình có cấu trúc nhưng chỉ cục bộ — kết hợp cả hai mới đủ thay một thư viện quản lý state ở quy mô vừa. State của server (dữ liệu fetch), state URL và state UI cục bộ nên xử lý bằng cách khác nhau — không có một công cụ nào hợp cho mọi loại state.', 'PUBLIC', 9127, 'ARTICLE', 'APPROVED', '{"title":"Tổng kết đợt quản lý state không cần thư viện","coverImage":null,"summary":"useContext một mình chỉ cấp quyền truy cập toàn cục, không có cấu trúc; useReducer một mình có cấu trúc nhưng chỉ cục bộ — kết hợp cả hai mới đủ thay một thư viện quản lý state ở quy mô vừa."}'::jsonb, NULL, now() - INTERVAL '9 days', now() - INTERVAL '9 days'),
    (100328, 'Bài học sau khi đồng bộ dữ liệu khi mất mạng. CRDT cho phép nhiều thiết bị ghi độc lập rồi hợp nhất về cùng một kết quả mà không cần máy chủ trọng tài, miễn phép hợp là giao hoán và không phụ thuộc thứ tự. CRDT giải quyết xung đột cấu trúc dữ liệu, không giải quyết xung đột nghiệp vụ — hai người cùng sửa giá một sản phẩm thì hợp nhất kỹ thuật xong vẫn cần logic nghiệp vụ quyết định giá nào đúng.', 'PUBLIC', 9254, 'ARTICLE', 'APPROVED', '{"title":"Bài học sau khi đồng bộ dữ liệu khi mất mạng","coverImage":null,"summary":"CRDT cho phép nhiều thiết bị ghi độc lập rồi hợp nhất về cùng một kết quả mà không cần máy chủ trọng tài, miễn phép hợp là giao hoán và không phụ thuộc thứ tự."}'::jsonb, NULL, now() - INTERVAL '9 days', now() - INTERVAL '9 days'),
    (100329, 'Ghi chép về giảm kích thước app. R8/ProGuard loại bỏ code không dùng tới từ các SDK bên thứ ba; một số dự án thực tế giảm được 60-70% kích thước APK chỉ bằng shrinking và minification, không đổi tính năng. Phần lớn dung lượng dư thừa nằm ở tài nguyên (ảnh độ phân giải cao không cần thiết, font không dùng) nhiều hơn là ở chính code.', 'PUBLIC', 9132, 'ARTICLE', 'APPROVED', '{"title":"Ghi chép về giảm kích thước app","coverImage":"${minioUrl}/post-media/posts/100329/cover.png","summary":"R8/ProGuard loại bỏ code không dùng tới từ các SDK bên thứ ba; một số dự án thực tế giảm được 60-70% kích thước APK chỉ bằng shrinking và minification, không đổi tính năng."}'::jsonb, NULL, now() - INTERVAL '9 days', now() - INTERVAL '9 days'),
    (100330, 'Nhìn lại hành trình bảo mật token trên thiết bị. Trên thiết bị đã jailbreak/root, mọi lớp bảo vệ của hệ thống keychain coi như mất tác dụng — không nên tin tuyệt đối vào lưu trữ phía client cho secret có giá trị cao. iOS Keychain và Android Keystore mã hoá secret bằng khoá sinh trong phần cứng bảo mật (Secure Enclave / TEE), nên kể cả thiết bị bị chiếm quyền cũng khó trích xuất trực tiếp khoá gốc.', 'PUBLIC', 9477, 'ARTICLE', 'APPROVED', '{"title":"Nhìn lại hành trình bảo mật token trên thiết bị","coverImage":null,"summary":"Trên thiết bị đã jailbreak/root, mọi lớp bảo vệ của hệ thống keychain coi như mất tác dụng — không nên tin tuyệt đối vào lưu trữ phía client cho secret có giá trị cao."}'::jsonb, NULL, now() - INTERVAL '9 days', now() - INTERVAL '9 days'),
    (100331, 'Chuyện rà soát phụ thuộc bên thứ ba, từ đầu tới lúc ổn. Sự cố Log4Shell (CVE-2021-44228) ảnh hưởng hàng triệu ứng dụng vì phần lớn không biết mình dùng Log4j — khoảng 60% dự án Java dùng nó như một dependency gián tiếp, chôn sâu trong cây phụ thuộc. Một gói npm nhỏ với hàng triệu lượt tải mỗi tuần từng bị chiếm quyền để phát tán mã độc, cho thấy kể cả gói ít ai để ý cũng có thể là điểm vào của toàn bộ chuỗi cung ứng.', 'PUBLIC', 9326, 'ARTICLE', 'APPROVED', '{"title":"Chuyện rà soát phụ thuộc bên thứ ba, từ đầu tới lúc ổn","coverImage":null,"summary":"Sự cố Log4Shell (CVE-2021-44228) ảnh hưởng hàng triệu ứng dụng vì phần lớn không biết mình dùng Log4j — khoảng 60% dự án Java dùng nó như một dependency gián tiếp, chôn sâu trong cây phụ thuộc."}'::jsonb, NULL, now() - INTERVAL '9 days', now() - INTERVAL '9 days'),
    (100332, 'Những gì mình học được khi dựng pipeline triển khai xanh-lam. Rollback chỉ là trỏ lại load balancer về môi trường cũ, không phải deploy lại — đây là lý do rollback kiểu này gần như tức thì so với các chiến lược khác. Đổi lại tốc độ rollback, chi phí là gấp đôi hạ tầng trong lúc chuyển đổi vì cả hai môi trường đều phải chạy đồng thời.', 'PUBLIC', 9438, 'ARTICLE', 'APPROVED', '{"title":"Những gì mình học được khi dựng pipeline triển khai xanh-lam","coverImage":null,"summary":"Rollback chỉ là trỏ lại load balancer về môi trường cũ, không phải deploy lại — đây là lý do rollback kiểu này gần như tức thì so với các chiến lược khác."}'::jsonb, NULL, now() - INTERVAL '9 days', now() - INTERVAL '9 days'),
    (100333, 'Nhật ký đặt resource limit cho pod. Pod ở nhóm Guaranteed (request bằng limit cho cả CPU lẫn RAM) bị evict sau cùng khi node thiếu tài nguyên; pod không khai request/limit bị evict đầu tiên. Exit code 137 trong kubectl describe pod gần như luôn là OOMKilled — kernel Linux giết tiến trình khi vượt giới hạn bộ nhớ đã khai.', 'PUBLIC', 9141, 'ARTICLE', 'APPROVED', '{"title":"Nhật ký đặt resource limit cho pod","coverImage":"${minioUrl}/post-media/posts/100333/cover.png","summary":"Pod ở nhóm Guaranteed (request bằng limit cho cả CPU lẫn RAM) bị evict sau cùng khi node thiếu tài nguyên; pod không khai request/limit bị evict đầu tiên."}'::jsonb, NULL, now() - INTERVAL '9 days', now() - INTERVAL '9 days'),
    (100334, 'Kể lại lần chuyển state Terraform lên remote. Từ Terraform 1.10, backend S3 tự khoá state bằng use_lockfile = true, không còn bắt buộc phải dựng thêm bảng DynamoDB riêng cho việc khoá như trước. Di trú state không downtime: bật đồng thời use_lockfile và dynamodb_table trong một giai đoạn chuyển tiếp, đợi mọi máy lên Terraform 1.11 trở lên rồi mới bỏ dynamodb_table.', 'PUBLIC', 9474, 'ARTICLE', 'APPROVED', '{"title":"Kể lại lần chuyển state Terraform lên remote","coverImage":null,"summary":"Từ Terraform 1.10, backend S3 tự khoá state bằng use_lockfile = true, không còn bắt buộc phải dựng thêm bảng DynamoDB riêng cho việc khoá như trước."}'::jsonb, NULL, now() - INTERVAL '9 days', now() - INTERVAL '9 days'),
    (100335, 'Tổng kết đợt giảm hoá đơn cloud. Phần lớn khoản tiết kiệm của một chương trình FinOps có cấu trúc thường đến ngay trong tháng thứ hai, từ rightsizing và tắt tài nguyên không dùng. Xoá dữ liệu test còn sót trên môi trường production-like và đặt lịch tắt máy dev ngoài giờ làm việc là hai khoản tiết kiệm rẻ nhất nhưng hay bị bỏ qua nhất.', 'PUBLIC', 9356, 'ARTICLE', 'APPROVED', '{"title":"Tổng kết đợt giảm hoá đơn cloud","coverImage":null,"summary":"Phần lớn khoản tiết kiệm của một chương trình FinOps có cấu trúc thường đến ngay trong tháng thứ hai, từ rightsizing và tắt tài nguyên không dùng."}'::jsonb, NULL, now() - INTERVAL '9 days', now() - INTERVAL '9 days'),
    (100336, 'Bài học sau khi đưa mô hình từ notebook lên production. Drift ở tầng bề mặt (trung bình, phương sai) đôi khi không đổi trong khi phân phối thật đã lệch hẳn — chỉ theo dõi thống kê tổng quát dễ bỏ sót loại trôi này. Công cụ kiểm dữ liệu tối ưu cho notebook thường thêm độ trễ không chấp nhận được khi ép chạy trong một pipeline real-time — công cụ hợp cho notebook chưa chắc hợp cho production.', 'PUBLIC', 9255, 'ARTICLE', 'APPROVED', '{"title":"Bài học sau khi đưa mô hình từ notebook lên production","coverImage":null,"summary":"Drift ở tầng bề mặt (trung bình, phương sai) đôi khi không đổi trong khi phân phối thật đã lệch hẳn — chỉ theo dõi thống kê tổng quát dễ bỏ sót loại trôi này."}'::jsonb, NULL, now() - INTERVAL '9 days', now() - INTERVAL '9 days'),
    (100337, 'Ghi chép về làm sạch dữ liệu đầu vào. Giá trị thiếu và giá trị trùng lặp gần đúng (cùng một khách hàng viết hoa/viết thường khác nhau) là hai nguồn lỗi phổ biến nhất khi gộp dữ liệu từ nhiều hệ thống. Kiểm tra tính hợp lệ nên chạy ngay ở điểm nạp dữ liệu, không phải đợi tới lúc mô hình huấn luyện xong mới phát hiện dữ liệu bẩn.', 'PUBLIC', 9387, 'ARTICLE', 'APPROVED', '{"title":"Ghi chép về làm sạch dữ liệu đầu vào","coverImage":"${minioUrl}/post-media/posts/100337/cover.png","summary":"Giá trị thiếu và giá trị trùng lặp gần đúng (cùng một khách hàng viết hoa/viết thường khác nhau) là hai nguồn lỗi phổ biến nhất khi gộp dữ liệu từ nhiều hệ thống."}'::jsonb, NULL, now() - INTERVAL '10 days', now() - INTERVAL '10 days'),
    (100338, 'Nhìn lại hành trình chọn giữa batch và streaming. Kiến trúc kết hợp cả hai (một đường streaming trả kết quả nhanh, một đường batch chạy lại định kỳ để sửa đúng) đánh đổi độ phức tạp vận hành lấy vừa nhanh vừa đúng. Câu hỏi cần trả lời trước khi chọn không phải ''công nghệ nào mạnh hơn'' mà là ''nghiệp vụ có thực sự cần kết quả trong vài giây, hay vài giờ là đủ'' — phần lớn báo cáo nội bộ không cần streaming.', 'PUBLIC', 9027, 'ARTICLE', 'APPROVED', '{"title":"Nhìn lại hành trình chọn giữa batch và streaming","coverImage":null,"summary":"Kiến trúc kết hợp cả hai (một đường streaming trả kết quả nhanh, một đường batch chạy lại định kỳ để sửa đúng) đánh đổi độ phức tạp vận hành lấy vừa nhanh vừa đúng."}'::jsonb, NULL, now() - INTERVAL '10 days', now() - INTERVAL '10 days'),
    (100339, 'Chuyện đánh giá chất lượng embedding, từ đầu tới lúc ổn. Một mô hình embedding xếp hạng cao trên bảng MTEB tổng vẫn có thể thua một mô hình xếp hạng thấp hơn khi test trực tiếp trên đúng dữ liệu miền của mình. MTEB đo tám loại tác vụ trên hàng chục bộ dữ liệu và hơn trăm ngôn ngữ, nhưng cho RAG chỉ tác vụ retrieval là quan trọng — điểm MTEB tổng có thể đánh lừa nếu mô hình mạnh ở phân loại nhưng yếu ở tìm kiếm.', 'PUBLIC', 9010, 'ARTICLE', 'APPROVED', '{"title":"Chuyện đánh giá chất lượng embedding, từ đầu tới lúc ổn","coverImage":null,"summary":"Một mô hình embedding xếp hạng cao trên bảng MTEB tổng vẫn có thể thua một mô hình xếp hạng thấp hơn khi test trực tiếp trên đúng dữ liệu miền của mình."}'::jsonb, NULL, now() - INTERVAL '10 days', now() - INTERVAL '10 days'),
    (100340, 'Những gì mình học được khi viết prompt ổn định qua nhiều lần chạy. Tỉ lệ bất ổn định từng đo được tăng từ khoảng 9,5% ở temperature 0,0 lên gần 20% ở temperature 1,0 trong một khảo sát trên nhiều mô hình — temperature thấp giảm rủi ro chứ không đảm bảo ổn định tuyệt đối. Ngay cả ở temperature 0 với cùng seed và cùng prompt, một số mô hình vẫn cho câu trả lời khác nhau giữa các lần chạy — ''xác định'' trên lý thuyết không luôn đúng trên thực tế triển khai.', 'PUBLIC', 9247, 'ARTICLE', 'APPROVED', '{"title":"Những gì mình học được khi viết prompt ổn định qua nhiều lần chạy","coverImage":null,"summary":"Tỉ lệ bất ổn định từng đo được tăng từ khoảng 9,5% ở temperature 0,0 lên gần 20% ở temperature 1,0 trong một khảo sát trên nhiều mô hình — temperature thấp giảm rủi ro chứ không đảm bảo ổn định tuyệt đối."}'::jsonb, NULL, now() - INTERVAL '10 days', now() - INTERVAL '10 days'),
    (100341, 'Nhật ký phỏng vấn không hỏi thuật toán. Câu hỏi kiểu đảo cây nhị phân đo được khả năng nhớ thuật toán, không đo được khả năng đọc hiểu một codebase lạ — kỹ năng chiếm phần lớn thời gian thực tế của một kỹ sư. Cho ứng viên xem một đoạn mã thật (ẩn danh) và hỏi họ sẽ đổi gì, vì sao — câu trả lời lộ ra cách nghĩ về đánh đổi nhiều hơn một bài toán chuẩn hoá sẵn.', 'PUBLIC', 9468, 'ARTICLE', 'APPROVED', '{"title":"Nhật ký phỏng vấn không hỏi thuật toán","coverImage":"${minioUrl}/post-media/posts/100341/cover.png","summary":"Câu hỏi kiểu đảo cây nhị phân đo được khả năng nhớ thuật toán, không đo được khả năng đọc hiểu một codebase lạ — kỹ năng chiếm phần lớn thời gian thực tế của một kỹ sư."}'::jsonb, NULL, now() - INTERVAL '10 days', now() - INTERVAL '10 days'),
    (100342, 'Kể lại lần nhận review mà không tự ái. Hỏi lại ''bạn nghĩ sao về cách này'' thay vì khẳng định ''cách này sai'' mở ra một cuộc thảo luận thay vì một phán quyết. Tách người khỏi đoạn mã: một comment review nói về ''đoạn code này'' chứ không phải ''bạn đã làm sai'' giữ được cuộc trao đổi ở mức kỹ thuật thay vì cá nhân.', 'PUBLIC', 9346, 'ARTICLE', 'APPROVED', '{"title":"Kể lại lần nhận review mà không tự ái","coverImage":null,"summary":"Hỏi lại ''bạn nghĩ sao về cách này'' thay vì khẳng định ''cách này sai'' mở ra một cuộc thảo luận thay vì một phán quyết."}'::jsonb, NULL, now() - INTERVAL '10 days', now() - INTERVAL '10 days'),
    (100343, 'Tổng kết đợt dẫn dắt một đội bốn người. Với một đội bốn người, đồng bộ hằng ngày 15 phút là đủ — vấn đề thường không phải thiếu họp mà là họp sai người, sai lúc. Việc khó nhất của người dẫn dắt nhóm nhỏ không phải phân công việc mà là quyết định việc nào KHÔNG làm — phạm vi hẹp nhưng rõ luôn thắng phạm vi rộng nhưng mơ hồ.', 'PUBLIC', 9151, 'ARTICLE', 'APPROVED', '{"title":"Tổng kết đợt dẫn dắt một đội bốn người","coverImage":null,"summary":"Với một đội bốn người, đồng bộ hằng ngày 15 phút là đủ — vấn đề thường không phải thiếu họp mà là họp sai người, sai lúc."}'::jsonb, NULL, now() - INTERVAL '10 days', now() - INTERVAL '10 days'),
    (100344, 'Bài học sau khi viết tài liệu mà người ta chịu đọc. Đặt câu trả lời ở ngay đầu, giải thích ở dưới — hầu hết người đọc chỉ cần dòng đầu tiên, phần còn lại là cho ai cần đào sâu. Tài liệu lỗi thời còn tệ hơn không có tài liệu vì nó khiến người đọc tin nhầm — gắn ngày cập nhật cuối giúp người đọc tự đánh giá độ tin cậy.', 'PUBLIC', 9010, 'ARTICLE', 'APPROVED', '{"title":"Bài học sau khi viết tài liệu mà người ta chịu đọc","coverImage":null,"summary":"Đặt câu trả lời ở ngay đầu, giải thích ở dưới — hầu hết người đọc chỉ cần dòng đầu tiên, phần còn lại là cho ai cần đào sâu."}'::jsonb, NULL, now() - INTERVAL '10 days', now() - INTERVAL '10 days'),
    (100345, 'Ghi chép về ước lượng công việc sát hơn. So sánh ước lượng cũ với thời gian thực tế đã làm, định kỳ, là cách duy nhất cải thiện độ chính xác ước lượng theo thời gian. Ước lượng theo khoảng thành thật hơn một con số duy nhất — con số duy nhất tạo cảm giác chắc chắn giả trong khi thực tế luôn có phương sai.', 'PUBLIC', 9426, 'ARTICLE', 'APPROVED', '{"title":"Ghi chép về ước lượng công việc sát hơn","coverImage":"${minioUrl}/post-media/posts/100345/cover.png","summary":"So sánh ước lượng cũ với thời gian thực tế đã làm, định kỳ, là cách duy nhất cải thiện độ chính xác ước lượng theo thời gian."}'::jsonb, NULL, now() - INTERVAL '10 days', now() - INTERVAL '10 days'),
    (100346, 'Nhìn lại hành trình tối ưu truy vấn N+1. Bật @BatchSize (hay default_batch_fetch_size) gom các lượt gọi lazy thành một câu WHERE id IN (...), nên 1.000 bản ghi chỉ còn vài chục truy vấn thay vì một nghìn. JOIN FETCH giải đúng một quan hệ trong một câu truy vấn, nhưng đổi FetchType sang EAGER để né N+1 chỉ khiến nó nặng hơn — Hibernate vẫn phát sinh truy vấn phụ cho từng dòng.', 'PUBLIC', 9466, 'ARTICLE', 'APPROVED', '{"title":"Nhìn lại hành trình tối ưu truy vấn N+1","coverImage":null,"summary":"Bật @BatchSize (hay default_batch_fetch_size) gom các lượt gọi lazy thành một câu WHERE id IN (...), nên 1.000 bản ghi chỉ còn vài chục truy vấn thay vì một nghìn."}'::jsonb, NULL, now() - INTERVAL '10 days', now() - INTERVAL '10 days'),
    (100347, 'Chuyện chọn TTL cho cache, từ đầu tới lúc ổn. Một khoá mutex ngắn hạn cho đúng một request đi tái tạo cache khi miss, các request còn lại chờ hoặc nhận bản cũ, thay vì để tất cả cùng dội xuống database. Stale-while-revalidate trả ngay giá trị đã hết hạn cho người dùng trong lúc một tiến trình nền âm thầm làm mới, nên không request nào phải chờ origin.', 'PUBLIC', 9001, 'ARTICLE', 'APPROVED', '{"title":"Chuyện chọn TTL cho cache, từ đầu tới lúc ổn","coverImage":null,"summary":"Một khoá mutex ngắn hạn cho đúng một request đi tái tạo cache khi miss, các request còn lại chờ hoặc nhận bản cũ, thay vì để tất cả cùng dội xuống database."}'::jsonb, NULL, now() - INTERVAL '10 days', now() - INTERVAL '10 days'),
    (100348, 'Những gì mình học được khi đánh index đúng thứ tự cột. Một truy vấn lọc ba cột trên bảng triệu dòng từng đi từ Parallel Seq Scan 17ms xuống Index Only Scan 0,6ms sau khi thêm đúng index tổ hợp khớp thứ tự lọc. Quy tắc leftmost prefix: một index tổ hợp chỉ dùng được cho truy vấn lọc đúng các cột nằm ở đầu index, theo đúng thứ tự khai.', 'PUBLIC', 9163, 'ARTICLE', 'APPROVED', '{"title":"Những gì mình học được khi đánh index đúng thứ tự cột","coverImage":null,"summary":"Một truy vấn lọc ba cột trên bảng triệu dòng từng đi từ Parallel Seq Scan 17ms xuống Index Only Scan 0,6ms sau khi thêm đúng index tổ hợp khớp thứ tự lọc."}'::jsonb, NULL, now() - INTERVAL '10 days', now() - INTERVAL '10 days'),
    (100349, 'Nhật ký chuyển sang virtual threads. Virtual thread không loại bỏ nút thắt, nó dời nút thắt xuống tầng dưới: khi trần connection pool biến mất, hàng đợi truy vấn database trở thành điểm nghẽn kế tiếp. ThreadLocal dùng sai với virtual thread gây rò rỉ bộ nhớ âm thầm — virtual thread không được gộp lại (pool) như platform thread nên state cũ không bao giờ được dọn.', 'PUBLIC', 9404, 'ARTICLE', 'APPROVED', '{"title":"Nhật ký chuyển sang virtual threads","coverImage":"${minioUrl}/post-media/posts/100349/cover.png","summary":"Virtual thread không loại bỏ nút thắt, nó dời nút thắt xuống tầng dưới: khi trần connection pool biến mất, hàng đợi truy vấn database trở thành điểm nghẽn kế tiếp."}'::jsonb, NULL, now() - INTERVAL '10 days', now() - INTERVAL '10 days'),
    (100350, 'Kể lại lần tách monolith thành service. Ranh giới service nên theo bounded context của nghiệp vụ, không theo lớp kỹ thuật — tách riêng ''service database'' hay ''service UI'' là dấu hiệu sai hướng. Chi phí ẩn lớn nhất không nằm ở hạ tầng mà ở giao tiếp giữa các service: một transaction từng gọn trong một câu SQL giờ cần saga hoặc outbox pattern để giữ nhất quán.', 'PUBLIC', 9254, 'ARTICLE', 'APPROVED', '{"title":"Kể lại lần tách monolith thành service","coverImage":null,"summary":"Ranh giới service nên theo bounded context của nghiệp vụ, không theo lớp kỹ thuật — tách riêng ''service database'' hay ''service UI'' là dấu hiệu sai hướng."}'::jsonb, NULL, now() - INTERVAL '10 days', now() - INTERVAL '10 days'),
    (100351, 'Tổng kết đợt thiết kế API phân trang. Trả kèm hasMore thay vì tổng số trang: COUNT(*) trên bảng lớn tốn kém và thường không cần thiết cho một danh sách cuộn vô hạn. Phân trang theo offset (LIMIT/OFFSET) chậm dần khi offset lớn vì database vẫn phải quét qua các dòng bị bỏ; phân trang theo cursor giữ tốc độ ổn định bất kể trang thứ mấy.', 'PUBLIC', 9072, 'ARTICLE', 'APPROVED', '{"title":"Tổng kết đợt thiết kế API phân trang","coverImage":null,"summary":"Trả kèm hasMore thay vì tổng số trang: COUNT(*) trên bảng lớn tốn kém và thường không cần thiết cho một danh sách cuộn vô hạn."}'::jsonb, NULL, now() - INTERVAL '10 days', now() - INTERVAL '10 days'),
    (100352, 'Bài học sau khi xử lý idempotency cho webhook. Client gửi kèm Idempotency-Key duy nhất trên header; server lưu key đó cùng kết quả lần xử lý đầu, các lần gọi lại cùng key chỉ trả lại đúng kết quả cũ. Webhook luôn giao theo kiểu ''ít nhất một lần'' — chắc chắn có lúc nhận trùng sự kiện, nên mọi payload đứng đắn đều mang kèm một event id duy nhất để nhận diện.', 'PUBLIC', 9316, 'ARTICLE', 'APPROVED', '{"title":"Bài học sau khi xử lý idempotency cho webhook","coverImage":null,"summary":"Client gửi kèm Idempotency-Key duy nhất trên header; server lưu key đó cùng kết quả lần xử lý đầu, các lần gọi lại cùng key chỉ trả lại đúng kết quả cũ."}'::jsonb, NULL, now() - INTERVAL '10 days', now() - INTERVAL '10 days'),
    (100353, 'Ghi chép về chuẩn hoá log có traceId. Không có traceId, một sự cố tail latency chỉ hiện ra như ''p99 tăng'' trên dashboard — không nói được request nào chậm, đi qua service nào, chết ở bước nào. MDC (Mapped Diagnostic Context) của SLF4J gắn traceId vào mọi dòng log trong cùng luồng xử lý mà không cần truyền tay qua từng hàm.', 'PUBLIC', 9364, 'ARTICLE', 'APPROVED', '{"title":"Ghi chép về chuẩn hoá log có traceId","coverImage":"${minioUrl}/post-media/posts/100353/cover.png","summary":"Không có traceId, một sự cố tail latency chỉ hiện ra như ''p99 tăng'' trên dashboard — không nói được request nào chậm, đi qua service nào, chết ở bước nào."}'::jsonb, NULL, now() - INTERVAL '10 days', now() - INTERVAL '10 days'),
    (100354, 'Nhìn lại hành trình đo p99 thay vì trung bình. Khuếch đại đuôi (tail amplification) xảy ra khi một request chậm ở tầng dưới khiến các lượt retry ở tầng trên dồn lại, biến 1% request chậm thành sự cố toàn hệ thống. Độ trễ không phân phối chuẩn mà lệch đuôi dài: một số ít request rất chậm (GC pause, cold start, retry, tranh chấp khoá) đủ sức kéo dài đuôi mà không ảnh hưởng tới trung bình.', 'PUBLIC', 9284, 'ARTICLE', 'APPROVED', '{"title":"Nhìn lại hành trình đo p99 thay vì trung bình","coverImage":null,"summary":"Khuếch đại đuôi (tail amplification) xảy ra khi một request chậm ở tầng dưới khiến các lượt retry ở tầng trên dồn lại, biến 1% request chậm thành sự cố toàn hệ thống."}'::jsonb, NULL, now() - INTERVAL '10 days', now() - INTERVAL '10 days'),
    (100355, 'Chuyện giảm thời gian build CI, từ đầu tới lúc ổn. Cache node_modules theo hash của lockfile đưa một bước cài đặt phụ thuộc từ 6-12 phút xuống còn 15-30 giây khi cache trúng. Tách một job chạy tuần tự trên 14 máy thành ba job song song từng đưa build time từ 24 phút xuống còn 8 phút, không đổi logic build.', 'PUBLIC', 9011, 'ARTICLE', 'APPROVED', '{"title":"Chuyện giảm thời gian build CI, từ đầu tới lúc ổn","coverImage":null,"summary":"Cache node_modules theo hash của lockfile đưa một bước cài đặt phụ thuộc từ 6-12 phút xuống còn 15-30 giây khi cache trúng."}'::jsonb, NULL, now() - INTERVAL '11 days', now() - INTERVAL '11 days'),
    (100356, 'Những gì mình học được khi viết test không phụ thuộc thứ tự. Chạy test với thứ tự ngẫu nhiên mỗi lần là cách nhanh nhất lộ ra test nào đang ngầm phụ thuộc thứ tự chạy trước đó. Mỗi test nên tự dựng dữ liệu của mình rồi tự dọn sau khi chạy, thay vì tin vào thứ tự chạy trước đó để lại đúng trạng thái cần.', 'PUBLIC', 9447, 'ARTICLE', 'APPROVED', '{"title":"Những gì mình học được khi viết test không phụ thuộc thứ tự","coverImage":null,"summary":"Chạy test với thứ tự ngẫu nhiên mỗi lần là cách nhanh nhất lộ ra test nào đang ngầm phụ thuộc thứ tự chạy trước đó."}'::jsonb, NULL, now() - INTERVAL '11 days', now() - INTERVAL '11 days'),
    (100357, 'Nhật ký mock ít đi, dùng testcontainers. Chi phí thật của việc bảo trì mock là độ trôi (drift): schema hay logic nghiệp vụ đổi mà mock không đổi theo, lỗi lọt qua ngay chỗ lẽ ra test phải bắt được. Mock database không bắt được lỗi migration, connection pool hay timeout thật — những thứ chỉ hiện ra khi chạy trên một instance database thật.', 'PUBLIC', 9437, 'ARTICLE', 'APPROVED', '{"title":"Nhật ký mock ít đi, dùng testcontainers","coverImage":"${minioUrl}/post-media/posts/100357/cover.png","summary":"Chi phí thật của việc bảo trì mock là độ trôi (drift): schema hay logic nghiệp vụ đổi mà mock không đổi theo, lỗi lọt qua ngay chỗ lẽ ra test phải bắt được."}'::jsonb, NULL, now() - INTERVAL '11 days', now() - INTERVAL '11 days'),
    (100358, 'Kể lại lần dựng design token dùng chung. Design token tách biến thiết kế (màu, khoảng cách, kiểu chữ) khỏi từng nền tảng, rồi biên dịch ra native code riêng cho iOS, Android và web từ đúng một nguồn. Airbnb xây một hệ ngôn ngữ thiết kế dùng chung thay vì ba hệ riêng cho ba nền tảng, đổi lại là một nguồn sự thật duy nhất cho mọi token.', 'PUBLIC', 9151, 'ARTICLE', 'APPROVED', '{"title":"Kể lại lần dựng design token dùng chung","coverImage":null,"summary":"Design token tách biến thiết kế (màu, khoảng cách, kiểu chữ) khỏi từng nền tảng, rồi biên dịch ra native code riêng cho iOS, Android và web từ đúng một nguồn."}'::jsonb, NULL, now() - INTERVAL '11 days', now() - INTERVAL '11 days'),
    (100359, 'Tổng kết đợt giảm layout shift. Đặt trước kích thước (width/height hoặc aspect-ratio) cho ảnh và khối quảng cáo là cách rẻ nhất để trình duyệt chừa đúng chỗ trước khi nội dung tải xong. Một mức giảm CLS 0,1 tương ứng khoảng 1-2% tăng engagement trong một số nghiên cứu — người đọc không còn bị nội dung ''nhảy'' ngay lúc định bấm.', 'PUBLIC', 9041, 'ARTICLE', 'APPROVED', '{"title":"Tổng kết đợt giảm layout shift","coverImage":null,"summary":"Đặt trước kích thước (width/height hoặc aspect-ratio) cho ảnh và khối quảng cáo là cách rẻ nhất để trình duyệt chừa đúng chỗ trước khi nội dung tải xong."}'::jsonb, NULL, now() - INTERVAL '11 days', now() - INTERVAL '11 days'),
    (100360, 'Bài học sau khi làm form truy cập được bằng bàn phím. Thứ tự Tab phải theo đúng thứ tự đọc hợp lý trên giao diện, không theo thứ tự khai trong DOM nếu CSS đã sắp xếp lại vị trí hiển thị. WCAG 2.1.1 đòi mọi phần tử tương tác dùng được trọn vẹn chỉ bằng bàn phím: Tab/Shift+Tab di chuyển focus, Enter kích hoạt, phím mũi tên điều hướng trong dropdown và radio.', 'PUBLIC', 9324, 'ARTICLE', 'APPROVED', '{"title":"Bài học sau khi làm form truy cập được bằng bàn phím","coverImage":null,"summary":"Thứ tự Tab phải theo đúng thứ tự đọc hợp lý trên giao diện, không theo thứ tự khai trong DOM nếu CSS đã sắp xếp lại vị trí hiển thị."}'::jsonb, NULL, now() - INTERVAL '11 days', now() - INTERVAL '11 days');
INSERT INTO socialapp.t_posts
    (id, content, visibility, author_id, post_type, moderation_status, qna_details, images, created_at, updated_at) VALUES
    (100361, 'Có ai từng làm tối ưu truy vấn N+1 chưa? Đã thử theo hướng: bật @BatchSize (hay default_batch_fetch_size) gom các lượt gọi lazy thành một câu WHERE id IN (...), nên 1.000 bản ghi chỉ còn vài chục truy vấn thay vì một nghìn. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9326, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '11 days', now() - INTERVAL '11 days'),
    (100362, 'Nhờ mọi người tư vấn chuyện chọn TTL cho cache. Đã thử theo hướng: rắc thêm 10-20% jitter ngẫu nhiên vào TTL để tránh hàng loạt key hết hạn cùng lúc — nguyên nhân phổ biến nhất của cache stampede. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9305, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '11 days', now() - INTERVAL '11 days'),
    (100363, 'Đang bí phần đánh index đúng thứ tự cột, ai gặp rồi cho xin hướng. Đã thử theo hướng: quy tắc leftmost prefix: một index tổ hợp chỉ dùng được cho truy vấn lọc đúng các cột nằm ở đầu index, theo đúng thứ tự khai. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9478, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '11 days', now() - INTERVAL '11 days'),
    (100364, 'Hỏi nhỏ: chuyển sang virtual threads nên bắt đầu từ đâu? Đã thử theo hướng: virtual thread không loại bỏ nút thắt, nó dời nút thắt xuống tầng dưới: khi trần connection pool biến mất, hàng đợi truy vấn database trở thành điểm nghẽn kế tiếp. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9295, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '11 days', now() - INTERVAL '11 days'),
    (100365, 'Team mình đang vướng tách monolith thành service. Đã thử theo hướng: strangler fig: bọc route cũ sau một lớp proxy rồi chuyển từng phần sang service mới, hệ thống cũ vẫn chạy suốt quá trình chuyển thay vì viết lại toàn bộ cùng lúc. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9112, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '11 days', now() - INTERVAL '11 days'),
    (100366, 'Cần lời khuyên về thiết kế API phân trang. Đã thử theo hướng: phân trang theo offset (LIMIT/OFFSET) chậm dần khi offset lớn vì database vẫn phải quét qua các dòng bị bỏ; phân trang theo cursor giữ tốc độ ổn định bất kể trang thứ mấy. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9191, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '11 days', now() - INTERVAL '11 days'),
    (100367, 'Mình loay hoay mãi với xử lý idempotency cho webhook. Đã thử theo hướng: client gửi kèm Idempotency-Key duy nhất trên header; server lưu key đó cùng kết quả lần xử lý đầu, các lần gọi lại cùng key chỉ trả lại đúng kết quả cũ. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9254, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '11 days', now() - INTERVAL '11 days'),
    (100368, 'Ai rành chuẩn hoá log có traceId không ạ? Đã thử theo hướng: một traceId sinh ở tầng gateway rồi truyền xuyên suốt qua header HTTP và context của hàng đợi, nối được toàn bộ đường đi của một request qua nhiều service chỉ bằng một lượt tìm log. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9050, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '11 days', now() - INTERVAL '11 days'),
    (100369, 'Có ai từng làm đo p99 thay vì trung bình chưa? Đã thử theo hướng: độ trễ không phân phối chuẩn mà lệch đuôi dài: một số ít request rất chậm (GC pause, cold start, retry, tranh chấp khoá) đủ sức kéo dài đuôi mà không ảnh hưởng tới trung bình. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9242, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '11 days', now() - INTERVAL '11 days'),
    (100370, 'Nhờ mọi người tư vấn chuyện giảm thời gian build CI. Đã thử theo hướng: cache node_modules theo hash của lockfile đưa một bước cài đặt phụ thuộc từ 6-12 phút xuống còn 15-30 giây khi cache trúng. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9254, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '11 days', now() - INTERVAL '11 days'),
    (100371, 'Đang bí phần viết test không phụ thuộc thứ tự, ai gặp rồi cho xin hướng. Đã thử theo hướng: test phụ thuộc thứ tự thường bắt nguồn từ state tĩnh dùng chung (static field, singleton chưa reset) hoặc dữ liệu test A để lại mà test B vô tình đọc phải. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9071, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '11 days', now() - INTERVAL '11 days'),
    (100372, 'Hỏi nhỏ: mock ít đi, dùng testcontainers nên bắt đầu từ đâu? Đã thử theo hướng: mock database không bắt được lỗi migration, connection pool hay timeout thật — những thứ chỉ hiện ra khi chạy trên một instance database thật. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9191, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '12 days', now() - INTERVAL '12 days'),
    (100373, 'Team mình đang vướng dựng design token dùng chung. Đã thử theo hướng: design token tách biến thiết kế (màu, khoảng cách, kiểu chữ) khỏi từng nền tảng, rồi biên dịch ra native code riêng cho iOS, Android và web từ đúng một nguồn. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9149, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '12 days', now() - INTERVAL '12 days'),
    (100374, 'Cần lời khuyên về giảm layout shift. Đã thử theo hướng: telegraph Media Group cải thiện CLS ở phân vị 75 từ 0,25 xuống 0,1, kéo tỉ lệ trang đạt chuẩn Core Web Vitals từ 57% lên 72%, theo case study với Google. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9201, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '12 days', now() - INTERVAL '12 days'),
    (100375, 'Mình loay hoay mãi với làm form truy cập được bằng bàn phím. Đã thử theo hướng: wCAG 2.1.1 đòi mọi phần tử tương tác dùng được trọn vẹn chỉ bằng bàn phím: Tab/Shift+Tab di chuyển focus, Enter kích hoạt, phím mũi tên điều hướng trong dropdown và radio. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9180, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '12 days', now() - INTERVAL '12 days'),
    (100376, 'Ai rành chia bundle theo route không ạ? Đã thử theo hướng: code splitting theo route chỉ tải phần JavaScript cần cho trang đang xem, thay vì gộp toàn bộ ứng dụng vào một bundle duy nhất tải ngay từ lần đầu. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9160, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '12 days', now() - INTERVAL '12 days'),
    (100377, 'Có ai từng làm quản lý state không cần thư viện chưa? Đã thử theo hướng: state của server (dữ liệu fetch), state URL và state UI cục bộ nên xử lý bằng cách khác nhau — không có một công cụ nào hợp cho mọi loại state. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9345, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '12 days', now() - INTERVAL '12 days'),
    (100378, 'Nhờ mọi người tư vấn chuyện đồng bộ dữ liệu khi mất mạng. Đã thử theo hướng: cRDT cho phép nhiều thiết bị ghi độc lập rồi hợp nhất về cùng một kết quả mà không cần máy chủ trọng tài, miễn phép hợp là giao hoán và không phụ thuộc thứ tự. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9199, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '12 days', now() - INTERVAL '12 days'),
    (100379, 'Đang bí phần giảm kích thước app, ai gặp rồi cho xin hướng. Đã thử theo hướng: android App Bundle giảm trung bình khoảng 35% dung lượng tải về vì chỉ đóng gói đúng phần tài nguyên khớp thiết bị người dùng, thay vì mọi biến thể màn hình/kiến trúc CPU. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9448, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '12 days', now() - INTERVAL '12 days'),
    (100380, 'Hỏi nhỏ: bảo mật token trên thiết bị nên bắt đầu từ đâu? Đã thử theo hướng: iOS Keychain và Android Keystore mã hoá secret bằng khoá sinh trong phần cứng bảo mật (Secure Enclave / TEE), nên kể cả thiết bị bị chiếm quyền cũng khó trích xuất trực tiếp khoá gốc. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9194, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '12 days', now() - INTERVAL '12 days'),
    (100381, 'Team mình đang vướng rà soát phụ thuộc bên thứ ba. Đã thử theo hướng: sự cố Log4Shell (CVE-2021-44228) ảnh hưởng hàng triệu ứng dụng vì phần lớn không biết mình dùng Log4j — khoảng 60% dự án Java dùng nó như một dependency gián tiếp, chôn sâu trong cây phụ thuộc. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9099, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '12 days', now() - INTERVAL '12 days'),
    (100382, 'Cần lời khuyên về dựng pipeline triển khai xanh-lam. Đã thử theo hướng: hai môi trường production giống hệt nhau — một đang chạy, một đứng chờ. Bản mới lên môi trường chờ, kiểm xong thì load balancer chuyển hướng traffic sang đó. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9051, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '12 days', now() - INTERVAL '12 days'),
    (100383, 'Mình loay hoay mãi với đặt resource limit cho pod. Đã thử theo hướng: exit code 137 trong kubectl describe pod gần như luôn là OOMKilled — kernel Linux giết tiến trình khi vượt giới hạn bộ nhớ đã khai. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9438, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '12 days', now() - INTERVAL '12 days'),
    (100384, 'Ai rành chuyển state Terraform lên remote không ạ? Đã thử theo hướng: từ Terraform 1.10, backend S3 tự khoá state bằng use_lockfile = true, không còn bắt buộc phải dựng thêm bảng DynamoDB riêng cho việc khoá như trước. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9072, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '12 days', now() - INTERVAL '12 days'),
    (100385, 'Có ai từng làm giảm hoá đơn cloud chưa? Đã thử theo hướng: nhiều đội đạt mức giảm 25-40% chi phí cloud trong 90 ngày đầu chỉ bằng rightsizing và dọn tài nguyên nhàn rỗi, chưa cần tái kiến trúc. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9001, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '12 days', now() - INTERVAL '12 days'),
    (100386, 'Nhờ mọi người tư vấn chuyện đưa mô hình từ notebook lên production. Đã thử theo hướng: công cụ kiểm dữ liệu tối ưu cho notebook thường thêm độ trễ không chấp nhận được khi ép chạy trong một pipeline real-time — công cụ hợp cho notebook chưa chắc hợp cho production. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9010, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '12 days', now() - INTERVAL '12 days'),
    (100387, 'Đang bí phần làm sạch dữ liệu đầu vào, ai gặp rồi cho xin hướng. Đã thử theo hướng: giá trị thiếu và giá trị trùng lặp gần đúng (cùng một khách hàng viết hoa/viết thường khác nhau) là hai nguồn lỗi phổ biến nhất khi gộp dữ liệu từ nhiều hệ thống. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9356, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '12 days', now() - INTERVAL '12 days'),
    (100388, 'Hỏi nhỏ: chọn giữa batch và streaming nên bắt đầu từ đâu? Đã thử theo hướng: batch xử lý dữ liệu theo lô định kỳ — đơn giản vận hành, độ trễ cao; streaming xử lý từng sự kiện gần như ngay lập tức — độ trễ thấp, đổi lại phức tạp hơn khi xử lý lỗi. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9051, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '12 days', now() - INTERVAL '12 days'),
    (100389, 'Team mình đang vướng đánh giá chất lượng embedding. Đã thử theo hướng: mTEB đo tám loại tác vụ trên hàng chục bộ dữ liệu và hơn trăm ngôn ngữ, nhưng cho RAG chỉ tác vụ retrieval là quan trọng — điểm MTEB tổng có thể đánh lừa nếu mô hình mạnh ở phân loại nhưng yếu ở tìm kiếm. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9143, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '13 days', now() - INTERVAL '13 days'),
    (100390, 'Cần lời khuyên về viết prompt ổn định qua nhiều lần chạy. Đã thử theo hướng: tỉ lệ bất ổn định từng đo được tăng từ khoảng 9,5% ở temperature 0,0 lên gần 20% ở temperature 1,0 trong một khảo sát trên nhiều mô hình — temperature thấp giảm rủi ro chứ không đảm bảo ổn định tuyệt đối. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9021, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '13 days', now() - INTERVAL '13 days'),
    (100391, 'Mình loay hoay mãi với phỏng vấn không hỏi thuật toán. Đã thử theo hướng: một quy trình phỏng vấn dựa trên bài tập sát việc thật (đọc mã có sẵn, sửa một lỗi cụ thể) được cho là dự đoán hiệu quả công việc tốt hơn câu hỏi thuật toán kinh điển. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9029, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '13 days', now() - INTERVAL '13 days'),
    (100392, 'Ai rành nhận review mà không tự ái không ạ? Đã thử theo hướng: tách người khỏi đoạn mã: một comment review nói về ''đoạn code này'' chứ không phải ''bạn đã làm sai'' giữ được cuộc trao đổi ở mức kỹ thuật thay vì cá nhân. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9200, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '13 days', now() - INTERVAL '13 days'),
    (100393, 'Có ai từng làm dẫn dắt một đội bốn người chưa? Đã thử theo hướng: với một đội bốn người, đồng bộ hằng ngày 15 phút là đủ — vấn đề thường không phải thiếu họp mà là họp sai người, sai lúc. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9369, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '13 days', now() - INTERVAL '13 days'),
    (100394, 'Nhờ mọi người tư vấn chuyện viết tài liệu mà người ta chịu đọc. Đã thử theo hướng: tài liệu ngắn có ví dụ chạy được luôn được đọc nhiều hơn tài liệu dài giải thích đầy đủ lý thuyết — người đọc tài liệu kỹ thuật thường đang cố giải quyết một việc cụ thể. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9260, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '13 days', now() - INTERVAL '13 days'),
    (100395, 'Đang bí phần ước lượng công việc sát hơn, ai gặp rồi cho xin hướng. Đã thử theo hướng: ước lượng theo khoảng thành thật hơn một con số duy nhất — con số duy nhất tạo cảm giác chắc chắn giả trong khi thực tế luôn có phương sai. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9017, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '13 days', now() - INTERVAL '13 days'),
    (100396, 'Hỏi nhỏ: tối ưu truy vấn N+1 nên bắt đầu từ đâu? Đã thử theo hướng: jOIN FETCH giải đúng một quan hệ trong một câu truy vấn, nhưng đổi FetchType sang EAGER để né N+1 chỉ khiến nó nặng hơn — Hibernate vẫn phát sinh truy vấn phụ cho từng dòng. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9161, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '13 days', now() - INTERVAL '13 days'),
    (100397, 'Team mình đang vướng chọn TTL cho cache. Đã thử theo hướng: một khoá mutex ngắn hạn cho đúng một request đi tái tạo cache khi miss, các request còn lại chờ hoặc nhận bản cũ, thay vì để tất cả cùng dội xuống database. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9243, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '13 days', now() - INTERVAL '13 days'),
    (100398, 'Cần lời khuyên về đánh index đúng thứ tự cột. Đã thử theo hướng: cột dùng so sánh khoảng (>, <, BETWEEN) phải đặt sau cùng trong index tổ hợp — index không dùng được cho cột đứng sau một điều kiện khoảng. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9438, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '13 days', now() - INTERVAL '13 days'),
    (100399, 'Mình loay hoay mãi với chuyển sang virtual threads. Đã thử theo hướng: threadLocal dùng sai với virtual thread gây rò rỉ bộ nhớ âm thầm — virtual thread không được gộp lại (pool) như platform thread nên state cũ không bao giờ được dọn. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9254, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '13 days', now() - INTERVAL '13 days'),
    (100400, 'Ai rành tách monolith thành service không ạ? Đã thử theo hướng: ranh giới service nên theo bounded context của nghiệp vụ, không theo lớp kỹ thuật — tách riêng ''service database'' hay ''service UI'' là dấu hiệu sai hướng. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9213, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '13 days', now() - INTERVAL '13 days'),
    (100401, 'Có ai từng làm thiết kế API phân trang chưa? Đã thử theo hướng: cursor phải mã hoá đủ thông tin sắp xếp — không chỉ id — để tránh trùng hoặc bỏ sót dòng khi nhiều bản ghi có cùng giá trị sắp xếp. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9255, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '13 days', now() - INTERVAL '13 days'),
    (100402, 'Nhờ mọi người tư vấn chuyện xử lý idempotency cho webhook. Đã thử theo hướng: webhook luôn giao theo kiểu ''ít nhất một lần'' — chắc chắn có lúc nhận trùng sự kiện, nên mọi payload đứng đắn đều mang kèm một event id duy nhất để nhận diện. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9305, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '13 days', now() - INTERVAL '13 days'),
    (100403, 'Đang bí phần chuẩn hoá log có traceId, ai gặp rồi cho xin hướng. Đã thử theo hướng: không có traceId, một sự cố tail latency chỉ hiện ra như ''p99 tăng'' trên dashboard — không nói được request nào chậm, đi qua service nào, chết ở bước nào. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9329, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '13 days', now() - INTERVAL '13 days'),
    (100404, 'Hỏi nhỏ: đo p99 thay vì trung bình nên bắt đầu từ đâu? Đã thử theo hướng: p50 200ms và p99 3 giây là chuyện bình thường trên cùng một hệ thống — con số trung bình không kể được câu chuyện đó. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9031, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '14 days', now() - INTERVAL '14 days'),
    (100405, 'Team mình đang vướng giảm thời gian build CI. Đã thử theo hướng: tách một job chạy tuần tự trên 14 máy thành ba job song song từng đưa build time từ 24 phút xuống còn 8 phút, không đổi logic build. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9244, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '14 days', now() - INTERVAL '14 days'),
    (100406, 'Cần lời khuyên về viết test không phụ thuộc thứ tự. Đã thử theo hướng: chạy test với thứ tự ngẫu nhiên mỗi lần là cách nhanh nhất lộ ra test nào đang ngầm phụ thuộc thứ tự chạy trước đó. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9030, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '14 days', now() - INTERVAL '14 days'),
    (100407, 'Mình loay hoay mãi với mock ít đi, dùng testcontainers. Đã thử theo hướng: testcontainers dựng một container Postgres/Redis mới tinh cho mỗi lượt test rồi huỷ ngay sau đó, nên test không dính trạng thái để lại từ lượt chạy trước. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9346, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '14 days', now() - INTERVAL '14 days'),
    (100408, 'Ai rành dựng design token dùng chung không ạ? Đã thử theo hướng: airbnb xây một hệ ngôn ngữ thiết kế dùng chung thay vì ba hệ riêng cho ba nền tảng, đổi lại là một nguồn sự thật duy nhất cho mọi token. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9386, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '14 days', now() - INTERVAL '14 days'),
    (100409, 'Có ai từng làm giảm layout shift chưa? Đã thử theo hướng: đặt trước kích thước (width/height hoặc aspect-ratio) cho ảnh và khối quảng cáo là cách rẻ nhất để trình duyệt chừa đúng chỗ trước khi nội dung tải xong. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9026, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '14 days', now() - INTERVAL '14 days'),
    (100410, 'Nhờ mọi người tư vấn chuyện làm form truy cập được bằng bàn phím. Đã thử theo hướng: làm một menu thả xuống thật sự dùng được bằng bàn phím theo đúng WCAG 2.2 từng mất hàng chục lượt chỉnh sửa — phần khó nhất là đồng bộ đúng phần tử có focus với đúng phần tử trình đọc màn hình công bố. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9111, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '14 days', now() - INTERVAL '14 days'),
    (100411, 'Đang bí phần chia bundle theo route, ai gặp rồi cho xin hướng. Đã thử theo hướng: lazy import một component nặng (biểu đồ, trình soạn thảo rich text) chỉ khi người dùng thực sự mở tới nó, thay vì buộc ai cũng tải nó dù không bao giờ chạm tới. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9088, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '14 days', now() - INTERVAL '14 days'),
    (100412, 'Hỏi nhỏ: quản lý state không cần thư viện nên bắt đầu từ đâu? Đã thử theo hướng: useReducer hợp khi một state có từ bốn hành động trở lên hoặc các trường phụ thuộc lẫn nhau; tách state và dispatch thành hai context riêng để component chỉ gọi dispatch không bị render lại mỗi khi state đổi. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9356, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '14 days', now() - INTERVAL '14 days'),
    (100413, 'Team mình đang vướng đồng bộ dữ liệu khi mất mạng. Đã thử theo hướng: cRDT giải quyết xung đột cấu trúc dữ liệu, không giải quyết xung đột nghiệp vụ — hai người cùng sửa giá một sản phẩm thì hợp nhất kỹ thuật xong vẫn cần logic nghiệp vụ quyết định giá nào đúng. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9265, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '14 days', now() - INTERVAL '14 days'),
    (100414, 'Cần lời khuyên về giảm kích thước app. Đã thử theo hướng: r8/ProGuard loại bỏ code không dùng tới từ các SDK bên thứ ba; một số dự án thực tế giảm được 60-70% kích thước APK chỉ bằng shrinking và minification, không đổi tính năng. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9387, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '14 days', now() - INTERVAL '14 days'),
    (100415, 'Mình loay hoay mãi với bảo mật token trên thiết bị. Đã thử theo hướng: chỉ một phần rất nhỏ ứng dụng xử lý dữ liệu nhạy cảm dùng đúng mức bảo vệ phần cứng mạnh nhất — phần lớn vẫn lưu token ở mức bảo vệ yếu hơn dù nền tảng đã hỗ trợ sẵn. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9436, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '14 days', now() - INTERVAL '14 days'),
    (100416, 'Ai rành rà soát phụ thuộc bên thứ ba không ạ? Đã thử theo hướng: một gói npm nhỏ với hàng triệu lượt tải mỗi tuần từng bị chiếm quyền để phát tán mã độc, cho thấy kể cả gói ít ai để ý cũng có thể là điểm vào của toàn bộ chuỗi cung ứng. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9050, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '14 days', now() - INTERVAL '14 days'),
    (100417, 'Có ai từng làm dựng pipeline triển khai xanh-lam chưa? Đã thử theo hướng: rollback chỉ là trỏ lại load balancer về môi trường cũ, không phải deploy lại — đây là lý do rollback kiểu này gần như tức thì so với các chiến lược khác. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9478, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '14 days', now() - INTERVAL '14 days'),
    (100418, 'Nhờ mọi người tư vấn chuyện đặt resource limit cho pod. Đã thử theo hướng: đặt memory limit bằng đúng memory request là khuyến nghị chuẩn: bộ nhớ là tài nguyên không nén được, một khi đã cấp cho pod thì chỉ lấy lại được bằng cách giết pod. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9203, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '14 days', now() - INTERVAL '14 days'),
    (100419, 'Đang bí phần chuyển state Terraform lên remote, ai gặp rồi cho xin hướng. Đã thử theo hướng: di trú state không downtime: bật đồng thời use_lockfile và dynamodb_table trong một giai đoạn chuyển tiếp, đợi mọi máy lên Terraform 1.11 trở lên rồi mới bỏ dynamodb_table. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9253, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '15 days', now() - INTERVAL '15 days'),
    (100420, 'Hỏi nhỏ: giảm hoá đơn cloud nên bắt đầu từ đâu? Đã thử theo hướng: phần lớn khoản tiết kiệm của một chương trình FinOps có cấu trúc thường đến ngay trong tháng thứ hai, từ rightsizing và tắt tài nguyên không dùng. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9001, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '15 days', now() - INTERVAL '15 days'),
    (100421, 'Team mình đang vướng đưa mô hình từ notebook lên production. Đã thử theo hướng: data drift là khi phân phối thống kê của dữ liệu đầu vào đổi theo thời gian; concept drift là khi chính mối quan hệ giữa đầu vào và đầu ra đổi — hai loại trôi cần chiến lược phát hiện khác nhau. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9446, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '15 days', now() - INTERVAL '15 days'),
    (100422, 'Cần lời khuyên về làm sạch dữ liệu đầu vào. Đã thử theo hướng: kiểm tra tính hợp lệ nên chạy ngay ở điểm nạp dữ liệu, không phải đợi tới lúc mô hình huấn luyện xong mới phát hiện dữ liệu bẩn. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9407, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '15 days', now() - INTERVAL '15 days'),
    (100423, 'Mình loay hoay mãi với chọn giữa batch và streaming. Đã thử theo hướng: kiến trúc kết hợp cả hai (một đường streaming trả kết quả nhanh, một đường batch chạy lại định kỳ để sửa đúng) đánh đổi độ phức tạp vận hành lấy vừa nhanh vừa đúng. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9199, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '15 days', now() - INTERVAL '15 days'),
    (100424, 'Ai rành đánh giá chất lượng embedding không ạ? Đã thử theo hướng: nDCG@10 là chỉ số nên dùng chính cho retrieval: nó đo cả việc có tìm đúng tài liệu hay không lẫn tài liệu đó đứng ở vị trí nào trong kết quả trả về. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9336, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '15 days', now() - INTERVAL '15 days'),
    (100425, 'Có ai từng làm viết prompt ổn định qua nhiều lần chạy chưa? Đã thử theo hướng: ngay cả ở temperature 0 với cùng seed và cùng prompt, một số mô hình vẫn cho câu trả lời khác nhau giữa các lần chạy — ''xác định'' trên lý thuyết không luôn đúng trên thực tế triển khai. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9092, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '15 days', now() - INTERVAL '15 days'),
    (100426, 'Nhờ mọi người tư vấn chuyện phỏng vấn không hỏi thuật toán. Đã thử theo hướng: câu hỏi kiểu đảo cây nhị phân đo được khả năng nhớ thuật toán, không đo được khả năng đọc hiểu một codebase lạ — kỹ năng chiếm phần lớn thời gian thực tế của một kỹ sư. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9102, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '15 days', now() - INTERVAL '15 days'),
    (100427, 'Đang bí phần nhận review mà không tự ái, ai gặp rồi cho xin hướng. Đã thử theo hướng: review là để bắt lỗi trước khi code chạy trên production, không phải để đánh giá năng lực người viết — nhớ điều đó giúp cả hai phía bớt phòng thủ. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9315, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '15 days', now() - INTERVAL '15 days'),
    (100428, 'Hỏi nhỏ: dẫn dắt một đội bốn người nên bắt đầu từ đâu? Đã thử theo hướng: việc khó nhất của người dẫn dắt nhóm nhỏ không phải phân công việc mà là quyết định việc nào KHÔNG làm — phạm vi hẹp nhưng rõ luôn thắng phạm vi rộng nhưng mơ hồ. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9153, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '15 days', now() - INTERVAL '15 days'),
    (100429, 'Team mình đang vướng viết tài liệu mà người ta chịu đọc. Đã thử theo hướng: đặt câu trả lời ở ngay đầu, giải thích ở dưới — hầu hết người đọc chỉ cần dòng đầu tiên, phần còn lại là cho ai cần đào sâu. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9001, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '15 days', now() - INTERVAL '15 days'),
    (100430, 'Cần lời khuyên về ước lượng công việc sát hơn. Đã thử theo hướng: phần việc hay bị bỏ sót khi ước lượng không phải code mà là review, test và xử lý case biên — cộng thêm một hệ số cho những phần này thường chính xác hơn cố đoán đúng ngay từ đầu. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9010, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '15 days', now() - INTERVAL '15 days'),
    (100431, 'Mình loay hoay mãi với tối ưu truy vấn N+1. Đã thử theo hướng: subselect fetching gom toàn bộ collection của một lượt cha vào đúng một câu truy vấn phụ duy nhất, thay vì một câu riêng cho mỗi cha. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9326, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '15 days', now() - INTERVAL '15 days'),
    (100432, 'Ai rành chọn TTL cho cache không ạ? Đã thử theo hướng: stale-while-revalidate trả ngay giá trị đã hết hạn cho người dùng trong lúc một tiến trình nền âm thầm làm mới, nên không request nào phải chờ origin. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9192, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '15 days', now() - INTERVAL '15 days'),
    (100433, 'Có ai từng làm đánh index đúng thứ tự cột chưa? Đã thử theo hướng: một truy vấn lọc ba cột trên bảng triệu dòng từng đi từ Parallel Seq Scan 17ms xuống Index Only Scan 0,6ms sau khi thêm đúng index tổ hợp khớp thứ tự lọc. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9406, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '15 days', now() - INTERVAL '15 days'),
    (100434, 'Nhờ mọi người tư vấn chuyện chuyển sang virtual threads. Đã thử theo hướng: sự cố Netflix tháng 7/2024 với virtual thread bắt nguồn từ một khối synchronized ghim virtual thread vào carrier thread, biến một đoạn mã tưởng vô hại thành điểm nghẽn toàn hệ thống. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9417, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '16 days', now() - INTERVAL '16 days'),
    (100435, 'Đang bí phần tách monolith thành service, ai gặp rồi cho xin hướng. Đã thử theo hướng: chi phí ẩn lớn nhất không nằm ở hạ tầng mà ở giao tiếp giữa các service: một transaction từng gọn trong một câu SQL giờ cần saga hoặc outbox pattern để giữ nhất quán. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9207, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '16 days', now() - INTERVAL '16 days'),
    (100436, 'Hỏi nhỏ: thiết kế API phân trang nên bắt đầu từ đâu? Đã thử theo hướng: trả kèm hasMore thay vì tổng số trang: COUNT(*) trên bảng lớn tốn kém và thường không cần thiết cho một danh sách cuộn vô hạn. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9376, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '16 days', now() - INTERVAL '16 days'),
    (100437, 'Team mình đang vướng xử lý idempotency cho webhook. Đã thử theo hướng: cần nhất quán giao dịch thì lưu bản ghi idempotency ngay trong cùng transaction với thay đổi dữ liệu; chỉ cần tốc độ thì Redis với TTL tự dọn là lựa chọn phổ biến hơn. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9377, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '16 days', now() - INTERVAL '16 days'),
    (100438, 'Cần lời khuyên về chuẩn hoá log có traceId. Đã thử theo hướng: mDC (Mapped Diagnostic Context) của SLF4J gắn traceId vào mọi dòng log trong cùng luồng xử lý mà không cần truyền tay qua từng hàm. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9082, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '16 days', now() - INTERVAL '16 days'),
    (100439, 'Mình loay hoay mãi với đo p99 thay vì trung bình. Đã thử theo hướng: khuếch đại đuôi (tail amplification) xảy ra khi một request chậm ở tầng dưới khiến các lượt retry ở tầng trên dồn lại, biến 1% request chậm thành sự cố toàn hệ thống. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9295, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '16 days', now() - INTERVAL '16 days'),
    (100440, 'Ai rành giảm thời gian build CI không ạ? Đã thử theo hướng: thứ tự ưu tiên đúng: cache trước (không cần đổi kiến trúc, lợi ích lớn nhất), song song hoá sau (cần tái cấu trúc pipeline nhưng lợi ích cộng dồn). Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9181, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '16 days', now() - INTERVAL '16 days'),
    (100441, 'Có ai từng làm viết test không phụ thuộc thứ tự chưa? Đã thử theo hướng: mỗi test nên tự dựng dữ liệu của mình rồi tự dọn sau khi chạy, thay vì tin vào thứ tự chạy trước đó để lại đúng trạng thái cần. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9255, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '16 days', now() - INTERVAL '16 days'),
    (100442, 'Nhờ mọi người tư vấn chuyện mock ít đi, dùng testcontainers. Đã thử theo hướng: chi phí thật của việc bảo trì mock là độ trôi (drift): schema hay logic nghiệp vụ đổi mà mock không đổi theo, lỗi lọt qua ngay chỗ lẽ ra test phải bắt được. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9451, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '16 days', now() - INTERVAL '16 days'),
    (100443, 'Đang bí phần dựng design token dùng chung, ai gặp rồi cho xin hướng. Đã thử theo hướng: đổi một token màu ở đúng một chỗ và mọi nền tảng cập nhật theo, thay vì phải tìm-và-thay từng giá trị hex rải rác trong code. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9397, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '16 days', now() - INTERVAL '16 days'),
    (100444, 'Hỏi nhỏ: giảm layout shift nên bắt đầu từ đâu? Đã thử theo hướng: một mức giảm CLS 0,1 tương ứng khoảng 1-2% tăng engagement trong một số nghiên cứu — người đọc không còn bị nội dung ''nhảy'' ngay lúc định bấm. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9001, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '16 days', now() - INTERVAL '16 days'),
    (100445, 'Team mình đang vướng làm form truy cập được bằng bàn phím. Đã thử theo hướng: thứ tự Tab phải theo đúng thứ tự đọc hợp lý trên giao diện, không theo thứ tự khai trong DOM nếu CSS đã sắp xếp lại vị trí hiển thị. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9438, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '16 days', now() - INTERVAL '16 days'),
    (100446, 'Cần lời khuyên về chia bundle theo route. Đã thử theo hướng: phân tích bundle bằng công cụ visualizer thường lộ ra một thư viện ngoài dự tính chiếm phần lớn dung lượng — kiểu import cả một thư viện ngày tháng chỉ để dùng một hàm format. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9498, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '16 days', now() - INTERVAL '16 days'),
    (100447, 'Mình loay hoay mãi với quản lý state không cần thư viện. Đã thử theo hướng: useContext một mình chỉ cấp quyền truy cập toàn cục, không có cấu trúc; useReducer một mình có cấu trúc nhưng chỉ cục bộ — kết hợp cả hai mới đủ thay một thư viện quản lý state ở quy mô vừa. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9354, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '16 days', now() - INTERVAL '16 days'),
    (100448, 'Ai rành đồng bộ dữ liệu khi mất mạng không ạ? Đã thử theo hướng: powerSync, Realm Sync và replication kiểu CouchDB là các nền tảng offline-first đang chạy production thật, dùng CRDT hoặc conflict resolution theo revision. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9365, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '16 days', now() - INTERVAL '16 days'),
    (100449, 'Có ai từng làm giảm kích thước app chưa? Đã thử theo hướng: phần lớn dung lượng dư thừa nằm ở tài nguyên (ảnh độ phân giải cao không cần thiết, font không dùng) nhiều hơn là ở chính code. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9133, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '17 days', now() - INTERVAL '17 days'),
    (100450, 'Nhờ mọi người tư vấn chuyện bảo mật token trên thiết bị. Đã thử theo hướng: trên thiết bị đã jailbreak/root, mọi lớp bảo vệ của hệ thống keychain coi như mất tác dụng — không nên tin tuyệt đối vào lưu trữ phía client cho secret có giá trị cao. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9198, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '17 days', now() - INTERVAL '17 days'),
    (100451, 'Đang bí phần rà soát phụ thuộc bên thứ ba, ai gặp rồi cho xin hướng. Đã thử theo hướng: dependabot và các công cụ tương tự không chỉ báo lỗ hổng ở dependency trực tiếp mà còn dò tới tận dependency gián tiếp, tự tạo PR nâng phiên bản gốc để kéo theo bản vá. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9377, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '17 days', now() - INTERVAL '17 days'),
    (100452, 'Hỏi nhỏ: dựng pipeline triển khai xanh-lam nên bắt đầu từ đâu? Đã thử theo hướng: đổi lại tốc độ rollback, chi phí là gấp đôi hạ tầng trong lúc chuyển đổi vì cả hai môi trường đều phải chạy đồng thời. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9041, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '17 days', now() - INTERVAL '17 days'),
    (100453, 'Team mình đang vướng đặt resource limit cho pod. Đã thử theo hướng: pod ở nhóm Guaranteed (request bằng limit cho cả CPU lẫn RAM) bị evict sau cùng khi node thiếu tài nguyên; pod không khai request/limit bị evict đầu tiên. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9377, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '17 days', now() - INTERVAL '17 days'),
    (100454, 'Cần lời khuyên về chuyển state Terraform lên remote. Đã thử theo hướng: state cục bộ không có khoá: hai người chạy terraform apply cùng lúc có thể ghi đè state của nhau — backend từ xa giải đúng vấn đề này bằng khoá tập trung. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9374, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '17 days', now() - INTERVAL '17 days'),
    (100455, 'Mình loay hoay mãi với giảm hoá đơn cloud. Đã thử theo hướng: xoá dữ liệu test còn sót trên môi trường production-like và đặt lịch tắt máy dev ngoài giờ làm việc là hai khoản tiết kiệm rẻ nhất nhưng hay bị bỏ qua nhất. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9477, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '17 days', now() - INTERVAL '17 days'),
    (100456, 'Ai rành đưa mô hình từ notebook lên production không ạ? Đã thử theo hướng: drift ở tầng bề mặt (trung bình, phương sai) đôi khi không đổi trong khi phân phối thật đã lệch hẳn — chỉ theo dõi thống kê tổng quát dễ bỏ sót loại trôi này. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9070, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '17 days', now() - INTERVAL '17 days'),
    (100457, 'Có ai từng làm làm sạch dữ liệu đầu vào chưa? Đã thử theo hướng: phần lớn thời gian của một dự án dữ liệu thực tế nằm ở làm sạch và chuẩn hoá, không nằm ở chọn thuật toán — quan sát này lặp lại ở gần như mọi khảo sát ngành khoa học dữ liệu. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9377, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '17 days', now() - INTERVAL '17 days'),
    (100458, 'Nhờ mọi người tư vấn chuyện chọn giữa batch và streaming. Đã thử theo hướng: câu hỏi cần trả lời trước khi chọn không phải ''công nghệ nào mạnh hơn'' mà là ''nghiệp vụ có thực sự cần kết quả trong vài giây, hay vài giờ là đủ'' — phần lớn báo cáo nội bộ không cần streaming. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9031, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '17 days', now() - INTERVAL '17 days'),
    (100459, 'Đang bí phần đánh giá chất lượng embedding, ai gặp rồi cho xin hướng. Đã thử theo hướng: một mô hình embedding xếp hạng cao trên bảng MTEB tổng vẫn có thể thua một mô hình xếp hạng thấp hơn khi test trực tiếp trên đúng dữ liệu miền của mình. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9406, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '17 days', now() - INTERVAL '17 days'),
    (100460, 'Hỏi nhỏ: viết prompt ổn định qua nhiều lần chạy nên bắt đầu từ đâu? Đã thử theo hướng: gần một phần tư câu hỏi trong một khảo sát trên nhiều họ mô hình từng đổi hẳn kết quả chỉ vì đổi seed ngẫu nhiên, dù prompt và nhiệt độ giữ nguyên. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9255, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '17 days', now() - INTERVAL '17 days'),
    (100461, 'Team mình đang vướng phỏng vấn không hỏi thuật toán. Đã thử theo hướng: cho ứng viên xem một đoạn mã thật (ẩn danh) và hỏi họ sẽ đổi gì, vì sao — câu trả lời lộ ra cách nghĩ về đánh đổi nhiều hơn một bài toán chuẩn hoá sẵn. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9086, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '17 days', now() - INTERVAL '17 days'),
    (100462, 'Cần lời khuyên về nhận review mà không tự ái. Đã thử theo hướng: hỏi lại ''bạn nghĩ sao về cách này'' thay vì khẳng định ''cách này sai'' mở ra một cuộc thảo luận thay vì một phán quyết. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9001, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '18 days', now() - INTERVAL '18 days'),
    (100463, 'Mình loay hoay mãi với dẫn dắt một đội bốn người. Đã thử theo hướng: tin tưởng đội tự quyết ở việc nhỏ, chỉ can thiệp ở quyết định khó đảo ngược — can thiệp vào mọi thứ làm chậm cả đội và không ai học được gì. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9194, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '18 days', now() - INTERVAL '18 days'),
    (100464, 'Ai rành viết tài liệu mà người ta chịu đọc không ạ? Đã thử theo hướng: tài liệu lỗi thời còn tệ hơn không có tài liệu vì nó khiến người đọc tin nhầm — gắn ngày cập nhật cuối giúp người đọc tự đánh giá độ tin cậy. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9137, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '18 days', now() - INTERVAL '18 days'),
    (100465, 'Có ai từng làm ước lượng công việc sát hơn chưa? Đã thử theo hướng: so sánh ước lượng cũ với thời gian thực tế đã làm, định kỳ, là cách duy nhất cải thiện độ chính xác ước lượng theo thời gian. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9173, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '18 days', now() - INTERVAL '18 days'),
    (100466, 'Nhờ mọi người tư vấn chuyện tối ưu truy vấn N+1. Đã thử theo hướng: bật @BatchSize (hay default_batch_fetch_size) gom các lượt gọi lazy thành một câu WHERE id IN (...), nên 1.000 bản ghi chỉ còn vài chục truy vấn thay vì một nghìn. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9282, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '18 days', now() - INTERVAL '18 days'),
    (100467, 'Đang bí phần chọn TTL cho cache, ai gặp rồi cho xin hướng. Đã thử theo hướng: rắc thêm 10-20% jitter ngẫu nhiên vào TTL để tránh hàng loạt key hết hạn cùng lúc — nguyên nhân phổ biến nhất của cache stampede. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9468, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '18 days', now() - INTERVAL '18 days'),
    (100468, 'Hỏi nhỏ: đánh index đúng thứ tự cột nên bắt đầu từ đâu? Đã thử theo hướng: quy tắc leftmost prefix: một index tổ hợp chỉ dùng được cho truy vấn lọc đúng các cột nằm ở đầu index, theo đúng thứ tự khai. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9222, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '18 days', now() - INTERVAL '18 days'),
    (100469, 'Team mình đang vướng chuyển sang virtual threads. Đã thử theo hướng: virtual thread không loại bỏ nút thắt, nó dời nút thắt xuống tầng dưới: khi trần connection pool biến mất, hàng đợi truy vấn database trở thành điểm nghẽn kế tiếp. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9316, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '18 days', now() - INTERVAL '18 days'),
    (100470, 'Cần lời khuyên về tách monolith thành service. Đã thử theo hướng: strangler fig: bọc route cũ sau một lớp proxy rồi chuyển từng phần sang service mới, hệ thống cũ vẫn chạy suốt quá trình chuyển thay vì viết lại toàn bộ cùng lúc. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9377, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '18 days', now() - INTERVAL '18 days'),
    (100471, 'Mình loay hoay mãi với thiết kế API phân trang. Đã thử theo hướng: phân trang theo offset (LIMIT/OFFSET) chậm dần khi offset lớn vì database vẫn phải quét qua các dòng bị bỏ; phân trang theo cursor giữ tốc độ ổn định bất kể trang thứ mấy. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9040, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '18 days', now() - INTERVAL '18 days'),
    (100472, 'Ai rành xử lý idempotency cho webhook không ạ? Đã thử theo hướng: client gửi kèm Idempotency-Key duy nhất trên header; server lưu key đó cùng kết quả lần xử lý đầu, các lần gọi lại cùng key chỉ trả lại đúng kết quả cũ. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9319, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '18 days', now() - INTERVAL '18 days'),
    (100473, 'Có ai từng làm chuẩn hoá log có traceId chưa? Đã thử theo hướng: một traceId sinh ở tầng gateway rồi truyền xuyên suốt qua header HTTP và context của hàng đợi, nối được toàn bộ đường đi của một request qua nhiều service chỉ bằng một lượt tìm log. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9467, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '18 days', now() - INTERVAL '18 days'),
    (100474, 'Nhờ mọi người tư vấn chuyện đo p99 thay vì trung bình. Đã thử theo hướng: độ trễ không phân phối chuẩn mà lệch đuôi dài: một số ít request rất chậm (GC pause, cold start, retry, tranh chấp khoá) đủ sức kéo dài đuôi mà không ảnh hưởng tới trung bình. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9387, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '18 days', now() - INTERVAL '18 days'),
    (100475, 'Đang bí phần giảm thời gian build CI, ai gặp rồi cho xin hướng. Đã thử theo hướng: cache node_modules theo hash của lockfile đưa một bước cài đặt phụ thuộc từ 6-12 phút xuống còn 15-30 giây khi cache trúng. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9377, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '19 days', now() - INTERVAL '19 days'),
    (100476, 'Hỏi nhỏ: viết test không phụ thuộc thứ tự nên bắt đầu từ đâu? Đã thử theo hướng: test phụ thuộc thứ tự thường bắt nguồn từ state tĩnh dùng chung (static field, singleton chưa reset) hoặc dữ liệu test A để lại mà test B vô tình đọc phải. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9387, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '19 days', now() - INTERVAL '19 days'),
    (100477, 'Team mình đang vướng mock ít đi, dùng testcontainers. Đã thử theo hướng: mock database không bắt được lỗi migration, connection pool hay timeout thật — những thứ chỉ hiện ra khi chạy trên một instance database thật. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9477, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '19 days', now() - INTERVAL '19 days'),
    (100478, 'Cần lời khuyên về dựng design token dùng chung. Đã thử theo hướng: design token tách biến thiết kế (màu, khoảng cách, kiểu chữ) khỏi từng nền tảng, rồi biên dịch ra native code riêng cho iOS, Android và web từ đúng một nguồn. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9122, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '19 days', now() - INTERVAL '19 days'),
    (100479, 'Mình loay hoay mãi với giảm layout shift. Đã thử theo hướng: telegraph Media Group cải thiện CLS ở phân vị 75 từ 0,25 xuống 0,1, kéo tỉ lệ trang đạt chuẩn Core Web Vitals từ 57% lên 72%, theo case study với Google. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9008, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '19 days', now() - INTERVAL '19 days'),
    (100480, 'Ai rành làm form truy cập được bằng bàn phím không ạ? Đã thử theo hướng: wCAG 2.1.1 đòi mọi phần tử tương tác dùng được trọn vẹn chỉ bằng bàn phím: Tab/Shift+Tab di chuyển focus, Enter kích hoạt, phím mũi tên điều hướng trong dropdown và radio. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9377, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '19 days', now() - INTERVAL '19 days'),
    (100481, 'Có ai từng làm chia bundle theo route chưa? Đã thử theo hướng: code splitting theo route chỉ tải phần JavaScript cần cho trang đang xem, thay vì gộp toàn bộ ứng dụng vào một bundle duy nhất tải ngay từ lần đầu. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9001, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '19 days', now() - INTERVAL '19 days'),
    (100482, 'Nhờ mọi người tư vấn chuyện quản lý state không cần thư viện. Đã thử theo hướng: state của server (dữ liệu fetch), state URL và state UI cục bộ nên xử lý bằng cách khác nhau — không có một công cụ nào hợp cho mọi loại state. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9255, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '19 days', now() - INTERVAL '19 days'),
    (100483, 'Đang bí phần đồng bộ dữ liệu khi mất mạng, ai gặp rồi cho xin hướng. Đã thử theo hướng: cRDT cho phép nhiều thiết bị ghi độc lập rồi hợp nhất về cùng một kết quả mà không cần máy chủ trọng tài, miễn phép hợp là giao hoán và không phụ thuộc thứ tự. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9255, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '19 days', now() - INTERVAL '19 days'),
    (100484, 'Hỏi nhỏ: giảm kích thước app nên bắt đầu từ đâu? Đã thử theo hướng: android App Bundle giảm trung bình khoảng 35% dung lượng tải về vì chỉ đóng gói đúng phần tài nguyên khớp thiết bị người dùng, thay vì mọi biến thể màn hình/kiến trúc CPU. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9417, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '19 days', now() - INTERVAL '19 days'),
    (100485, 'Team mình đang vướng bảo mật token trên thiết bị. Đã thử theo hướng: iOS Keychain và Android Keystore mã hoá secret bằng khoá sinh trong phần cứng bảo mật (Secure Enclave / TEE), nên kể cả thiết bị bị chiếm quyền cũng khó trích xuất trực tiếp khoá gốc. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9207, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '19 days', now() - INTERVAL '19 days'),
    (100486, 'Cần lời khuyên về rà soát phụ thuộc bên thứ ba. Đã thử theo hướng: sự cố Log4Shell (CVE-2021-44228) ảnh hưởng hàng triệu ứng dụng vì phần lớn không biết mình dùng Log4j — khoảng 60% dự án Java dùng nó như một dependency gián tiếp, chôn sâu trong cây phụ thuộc. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9275, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '19 days', now() - INTERVAL '19 days'),
    (100487, 'Mình loay hoay mãi với dựng pipeline triển khai xanh-lam. Đã thử theo hướng: hai môi trường production giống hệt nhau — một đang chạy, một đứng chờ. Bản mới lên môi trường chờ, kiểm xong thì load balancer chuyển hướng traffic sang đó. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9224, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '19 days', now() - INTERVAL '19 days'),
    (100488, 'Ai rành đặt resource limit cho pod không ạ? Đã thử theo hướng: exit code 137 trong kubectl describe pod gần như luôn là OOMKilled — kernel Linux giết tiến trình khi vượt giới hạn bộ nhớ đã khai. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9176, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '19 days', now() - INTERVAL '19 days'),
    (100489, 'Có ai từng làm chuyển state Terraform lên remote chưa? Đã thử theo hướng: từ Terraform 1.10, backend S3 tự khoá state bằng use_lockfile = true, không còn bắt buộc phải dựng thêm bảng DynamoDB riêng cho việc khoá như trước. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9336, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '20 days', now() - INTERVAL '20 days'),
    (100490, 'Nhờ mọi người tư vấn chuyện giảm hoá đơn cloud. Đã thử theo hướng: nhiều đội đạt mức giảm 25-40% chi phí cloud trong 90 ngày đầu chỉ bằng rightsizing và dọn tài nguyên nhàn rỗi, chưa cần tái kiến trúc. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9474, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '20 days', now() - INTERVAL '20 days'),
    (100491, 'Đang bí phần đưa mô hình từ notebook lên production, ai gặp rồi cho xin hướng. Đã thử theo hướng: công cụ kiểm dữ liệu tối ưu cho notebook thường thêm độ trễ không chấp nhận được khi ép chạy trong một pipeline real-time — công cụ hợp cho notebook chưa chắc hợp cho production. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9438, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '20 days', now() - INTERVAL '20 days'),
    (100492, 'Hỏi nhỏ: làm sạch dữ liệu đầu vào nên bắt đầu từ đâu? Đã thử theo hướng: giá trị thiếu và giá trị trùng lặp gần đúng (cùng một khách hàng viết hoa/viết thường khác nhau) là hai nguồn lỗi phổ biến nhất khi gộp dữ liệu từ nhiều hệ thống. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9001, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '20 days', now() - INTERVAL '20 days'),
    (100493, 'Team mình đang vướng chọn giữa batch và streaming. Đã thử theo hướng: batch xử lý dữ liệu theo lô định kỳ — đơn giản vận hành, độ trễ cao; streaming xử lý từng sự kiện gần như ngay lập tức — độ trễ thấp, đổi lại phức tạp hơn khi xử lý lỗi. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9203, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '20 days', now() - INTERVAL '20 days'),
    (100494, 'Cần lời khuyên về đánh giá chất lượng embedding. Đã thử theo hướng: mTEB đo tám loại tác vụ trên hàng chục bộ dữ liệu và hơn trăm ngôn ngữ, nhưng cho RAG chỉ tác vụ retrieval là quan trọng — điểm MTEB tổng có thể đánh lừa nếu mô hình mạnh ở phân loại nhưng yếu ở tìm kiếm. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9021, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '20 days', now() - INTERVAL '20 days'),
    (100495, 'Mình loay hoay mãi với viết prompt ổn định qua nhiều lần chạy. Đã thử theo hướng: tỉ lệ bất ổn định từng đo được tăng từ khoảng 9,5% ở temperature 0,0 lên gần 20% ở temperature 1,0 trong một khảo sát trên nhiều mô hình — temperature thấp giảm rủi ro chứ không đảm bảo ổn định tuyệt đối. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9201, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '20 days', now() - INTERVAL '20 days'),
    (100496, 'Ai rành phỏng vấn không hỏi thuật toán không ạ? Đã thử theo hướng: một quy trình phỏng vấn dựa trên bài tập sát việc thật (đọc mã có sẵn, sửa một lỗi cụ thể) được cho là dự đoán hiệu quả công việc tốt hơn câu hỏi thuật toán kinh điển. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9364, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '20 days', now() - INTERVAL '20 days'),
    (100497, 'Có ai từng làm nhận review mà không tự ái chưa? Đã thử theo hướng: tách người khỏi đoạn mã: một comment review nói về ''đoạn code này'' chứ không phải ''bạn đã làm sai'' giữ được cuộc trao đổi ở mức kỹ thuật thay vì cá nhân. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9356, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '20 days', now() - INTERVAL '20 days'),
    (100498, 'Nhờ mọi người tư vấn chuyện dẫn dắt một đội bốn người. Đã thử theo hướng: với một đội bốn người, đồng bộ hằng ngày 15 phút là đủ — vấn đề thường không phải thiếu họp mà là họp sai người, sai lúc. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9001, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '20 days', now() - INTERVAL '20 days'),
    (100499, 'Đang bí phần viết tài liệu mà người ta chịu đọc, ai gặp rồi cho xin hướng. Đã thử theo hướng: tài liệu ngắn có ví dụ chạy được luôn được đọc nhiều hơn tài liệu dài giải thích đầy đủ lý thuyết — người đọc tài liệu kỹ thuật thường đang cố giải quyết một việc cụ thể. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9326, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '20 days', now() - INTERVAL '20 days'),
    (100500, 'Hỏi nhỏ: ước lượng công việc sát hơn nên bắt đầu từ đâu? Đã thử theo hướng: ước lượng theo khoảng thành thật hơn một con số duy nhất — con số duy nhất tạo cảm giác chắc chắn giả trong khi thực tế luôn có phương sai. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9394, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '20 days', now() - INTERVAL '20 days'),
    (100501, 'Team mình đang vướng tối ưu truy vấn N+1. Đã thử theo hướng: jOIN FETCH giải đúng một quan hệ trong một câu truy vấn, nhưng đổi FetchType sang EAGER để né N+1 chỉ khiến nó nặng hơn — Hibernate vẫn phát sinh truy vấn phụ cho từng dòng. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9458, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '20 days', now() - INTERVAL '20 days'),
    (100502, 'Cần lời khuyên về chọn TTL cho cache. Đã thử theo hướng: một khoá mutex ngắn hạn cho đúng một request đi tái tạo cache khi miss, các request còn lại chờ hoặc nhận bản cũ, thay vì để tất cả cùng dội xuống database. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9316, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '21 days', now() - INTERVAL '21 days'),
    (100503, 'Mình loay hoay mãi với đánh index đúng thứ tự cột. Đã thử theo hướng: cột dùng so sánh khoảng (>, <, BETWEEN) phải đặt sau cùng trong index tổ hợp — index không dùng được cho cột đứng sau một điều kiện khoảng. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9274, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '21 days', now() - INTERVAL '21 days'),
    (100504, 'Ai rành chuyển sang virtual threads không ạ? Đã thử theo hướng: threadLocal dùng sai với virtual thread gây rò rỉ bộ nhớ âm thầm — virtual thread không được gộp lại (pool) như platform thread nên state cũ không bao giờ được dọn. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9146, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '21 days', now() - INTERVAL '21 days'),
    (100505, 'Có ai từng làm tách monolith thành service chưa? Đã thử theo hướng: ranh giới service nên theo bounded context của nghiệp vụ, không theo lớp kỹ thuật — tách riêng ''service database'' hay ''service UI'' là dấu hiệu sai hướng. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9434, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '21 days', now() - INTERVAL '21 days'),
    (100506, 'Nhờ mọi người tư vấn chuyện thiết kế API phân trang. Đã thử theo hướng: cursor phải mã hoá đủ thông tin sắp xếp — không chỉ id — để tránh trùng hoặc bỏ sót dòng khi nhiều bản ghi có cùng giá trị sắp xếp. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9212, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '21 days', now() - INTERVAL '21 days'),
    (100507, 'Đang bí phần xử lý idempotency cho webhook, ai gặp rồi cho xin hướng. Đã thử theo hướng: webhook luôn giao theo kiểu ''ít nhất một lần'' — chắc chắn có lúc nhận trùng sự kiện, nên mọi payload đứng đắn đều mang kèm một event id duy nhất để nhận diện. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9476, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '21 days', now() - INTERVAL '21 days'),
    (100508, 'Hỏi nhỏ: chuẩn hoá log có traceId nên bắt đầu từ đâu? Đã thử theo hướng: không có traceId, một sự cố tail latency chỉ hiện ra như ''p99 tăng'' trên dashboard — không nói được request nào chậm, đi qua service nào, chết ở bước nào. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9305, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '21 days', now() - INTERVAL '21 days'),
    (100509, 'Team mình đang vướng đo p99 thay vì trung bình. Đã thử theo hướng: p50 200ms và p99 3 giây là chuyện bình thường trên cùng một hệ thống — con số trung bình không kể được câu chuyện đó. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9404, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '21 days', now() - INTERVAL '21 days'),
    (100510, 'Cần lời khuyên về giảm thời gian build CI. Đã thử theo hướng: tách một job chạy tuần tự trên 14 máy thành ba job song song từng đưa build time từ 24 phút xuống còn 8 phút, không đổi logic build. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9004, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '21 days', now() - INTERVAL '21 days'),
    (100511, 'Mình loay hoay mãi với viết test không phụ thuộc thứ tự. Đã thử theo hướng: chạy test với thứ tự ngẫu nhiên mỗi lần là cách nhanh nhất lộ ra test nào đang ngầm phụ thuộc thứ tự chạy trước đó. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9194, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '21 days', now() - INTERVAL '21 days'),
    (100512, 'Ai rành mock ít đi, dùng testcontainers không ạ? Đã thử theo hướng: testcontainers dựng một container Postgres/Redis mới tinh cho mỗi lượt test rồi huỷ ngay sau đó, nên test không dính trạng thái để lại từ lượt chạy trước. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9163, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '21 days', now() - INTERVAL '21 days'),
    (100513, 'Có ai từng làm dựng design token dùng chung chưa? Đã thử theo hướng: airbnb xây một hệ ngôn ngữ thiết kế dùng chung thay vì ba hệ riêng cho ba nền tảng, đổi lại là một nguồn sự thật duy nhất cho mọi token. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9193, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '21 days', now() - INTERVAL '21 days'),
    (100514, 'Nhờ mọi người tư vấn chuyện giảm layout shift. Đã thử theo hướng: đặt trước kích thước (width/height hoặc aspect-ratio) cho ảnh và khối quảng cáo là cách rẻ nhất để trình duyệt chừa đúng chỗ trước khi nội dung tải xong. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9001, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '22 days', now() - INTERVAL '22 days'),
    (100515, 'Đang bí phần làm form truy cập được bằng bàn phím, ai gặp rồi cho xin hướng. Đã thử theo hướng: làm một menu thả xuống thật sự dùng được bằng bàn phím theo đúng WCAG 2.2 từng mất hàng chục lượt chỉnh sửa — phần khó nhất là đồng bộ đúng phần tử có focus với đúng phần tử trình đọc màn hình công bố. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9071, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '22 days', now() - INTERVAL '22 days'),
    (100516, 'Hỏi nhỏ: chia bundle theo route nên bắt đầu từ đâu? Đã thử theo hướng: lazy import một component nặng (biểu đồ, trình soạn thảo rich text) chỉ khi người dùng thực sự mở tới nó, thay vì buộc ai cũng tải nó dù không bao giờ chạm tới. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9120, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '22 days', now() - INTERVAL '22 days'),
    (100517, 'Team mình đang vướng quản lý state không cần thư viện. Đã thử theo hướng: useReducer hợp khi một state có từ bốn hành động trở lên hoặc các trường phụ thuộc lẫn nhau; tách state và dispatch thành hai context riêng để component chỉ gọi dispatch không bị render lại mỗi khi state đổi. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9234, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '22 days', now() - INTERVAL '22 days'),
    (100518, 'Cần lời khuyên về đồng bộ dữ liệu khi mất mạng. Đã thử theo hướng: cRDT giải quyết xung đột cấu trúc dữ liệu, không giải quyết xung đột nghiệp vụ — hai người cùng sửa giá một sản phẩm thì hợp nhất kỹ thuật xong vẫn cần logic nghiệp vụ quyết định giá nào đúng. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9072, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '22 days', now() - INTERVAL '22 days'),
    (100519, 'Mình loay hoay mãi với giảm kích thước app. Đã thử theo hướng: r8/ProGuard loại bỏ code không dùng tới từ các SDK bên thứ ba; một số dự án thực tế giảm được 60-70% kích thước APK chỉ bằng shrinking và minification, không đổi tính năng. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9417, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '22 days', now() - INTERVAL '22 days'),
    (100520, 'Ai rành bảo mật token trên thiết bị không ạ? Đã thử theo hướng: chỉ một phần rất nhỏ ứng dụng xử lý dữ liệu nhạy cảm dùng đúng mức bảo vệ phần cứng mạnh nhất — phần lớn vẫn lưu token ở mức bảo vệ yếu hơn dù nền tảng đã hỗ trợ sẵn. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9438, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '22 days', now() - INTERVAL '22 days'),
    (100521, 'Có ai từng làm rà soát phụ thuộc bên thứ ba chưa? Đã thử theo hướng: một gói npm nhỏ với hàng triệu lượt tải mỗi tuần từng bị chiếm quyền để phát tán mã độc, cho thấy kể cả gói ít ai để ý cũng có thể là điểm vào của toàn bộ chuỗi cung ứng. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9151, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '22 days', now() - INTERVAL '22 days'),
    (100522, 'Nhờ mọi người tư vấn chuyện dựng pipeline triển khai xanh-lam. Đã thử theo hướng: rollback chỉ là trỏ lại load balancer về môi trường cũ, không phải deploy lại — đây là lý do rollback kiểu này gần như tức thì so với các chiến lược khác. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9386, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '22 days', now() - INTERVAL '22 days'),
    (100523, 'Đang bí phần đặt resource limit cho pod, ai gặp rồi cho xin hướng. Đã thử theo hướng: đặt memory limit bằng đúng memory request là khuyến nghị chuẩn: bộ nhớ là tài nguyên không nén được, một khi đã cấp cho pod thì chỉ lấy lại được bằng cách giết pod. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9030, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '22 days', now() - INTERVAL '22 days'),
    (100524, 'Hỏi nhỏ: chuyển state Terraform lên remote nên bắt đầu từ đâu? Đã thử theo hướng: di trú state không downtime: bật đồng thời use_lockfile và dynamodb_table trong một giai đoạn chuyển tiếp, đợi mọi máy lên Terraform 1.11 trở lên rồi mới bỏ dynamodb_table. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9001, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '22 days', now() - INTERVAL '22 days'),
    (100525, 'Team mình đang vướng giảm hoá đơn cloud. Đã thử theo hướng: phần lớn khoản tiết kiệm của một chương trình FinOps có cấu trúc thường đến ngay trong tháng thứ hai, từ rightsizing và tắt tài nguyên không dùng. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9163, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '22 days', now() - INTERVAL '22 days'),
    (100526, 'Cần lời khuyên về đưa mô hình từ notebook lên production. Đã thử theo hướng: data drift là khi phân phối thống kê của dữ liệu đầu vào đổi theo thời gian; concept drift là khi chính mối quan hệ giữa đầu vào và đầu ra đổi — hai loại trôi cần chiến lược phát hiện khác nhau. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9001, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '23 days', now() - INTERVAL '23 days'),
    (100527, 'Mình loay hoay mãi với làm sạch dữ liệu đầu vào. Đã thử theo hướng: kiểm tra tính hợp lệ nên chạy ngay ở điểm nạp dữ liệu, không phải đợi tới lúc mô hình huấn luyện xong mới phát hiện dữ liệu bẩn. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9234, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '23 days', now() - INTERVAL '23 days'),
    (100528, 'Ai rành chọn giữa batch và streaming không ạ? Đã thử theo hướng: kiến trúc kết hợp cả hai (một đường streaming trả kết quả nhanh, một đường batch chạy lại định kỳ để sửa đúng) đánh đổi độ phức tạp vận hành lấy vừa nhanh vừa đúng. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9151, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '23 days', now() - INTERVAL '23 days'),
    (100529, 'Có ai từng làm đánh giá chất lượng embedding chưa? Đã thử theo hướng: nDCG@10 là chỉ số nên dùng chính cho retrieval: nó đo cả việc có tìm đúng tài liệu hay không lẫn tài liệu đó đứng ở vị trí nào trong kết quả trả về. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9070, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '23 days', now() - INTERVAL '23 days'),
    (100530, 'Nhờ mọi người tư vấn chuyện viết prompt ổn định qua nhiều lần chạy. Đã thử theo hướng: ngay cả ở temperature 0 với cùng seed và cùng prompt, một số mô hình vẫn cho câu trả lời khác nhau giữa các lần chạy — ''xác định'' trên lý thuyết không luôn đúng trên thực tế triển khai. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9188, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '23 days', now() - INTERVAL '23 days'),
    (100531, 'Đang bí phần phỏng vấn không hỏi thuật toán, ai gặp rồi cho xin hướng. Đã thử theo hướng: câu hỏi kiểu đảo cây nhị phân đo được khả năng nhớ thuật toán, không đo được khả năng đọc hiểu một codebase lạ — kỹ năng chiếm phần lớn thời gian thực tế của một kỹ sư. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9122, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '23 days', now() - INTERVAL '23 days'),
    (100532, 'Hỏi nhỏ: nhận review mà không tự ái nên bắt đầu từ đâu? Đã thử theo hướng: review là để bắt lỗi trước khi code chạy trên production, không phải để đánh giá năng lực người viết — nhớ điều đó giúp cả hai phía bớt phòng thủ. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9204, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '23 days', now() - INTERVAL '23 days'),
    (100533, 'Team mình đang vướng dẫn dắt một đội bốn người. Đã thử theo hướng: việc khó nhất của người dẫn dắt nhóm nhỏ không phải phân công việc mà là quyết định việc nào KHÔNG làm — phạm vi hẹp nhưng rõ luôn thắng phạm vi rộng nhưng mơ hồ. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9133, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '23 days', now() - INTERVAL '23 days'),
    (100534, 'Cần lời khuyên về viết tài liệu mà người ta chịu đọc. Đã thử theo hướng: đặt câu trả lời ở ngay đầu, giải thích ở dưới — hầu hết người đọc chỉ cần dòng đầu tiên, phần còn lại là cho ai cần đào sâu. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9316, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '23 days', now() - INTERVAL '23 days'),
    (100535, 'Mình loay hoay mãi với ước lượng công việc sát hơn. Đã thử theo hướng: phần việc hay bị bỏ sót khi ước lượng không phải code mà là review, test và xử lý case biên — cộng thêm một hệ số cho những phần này thường chính xác hơn cố đoán đúng ngay từ đầu. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9040, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '23 days', now() - INTERVAL '23 days'),
    (100536, 'Ai rành tối ưu truy vấn N+1 không ạ? Đã thử theo hướng: subselect fetching gom toàn bộ collection của một lượt cha vào đúng một câu truy vấn phụ duy nhất, thay vì một câu riêng cho mỗi cha. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9438, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '23 days', now() - INTERVAL '23 days'),
    (100537, 'Có ai từng làm chọn TTL cho cache chưa? Đã thử theo hướng: stale-while-revalidate trả ngay giá trị đã hết hạn cho người dùng trong lúc một tiến trình nền âm thầm làm mới, nên không request nào phải chờ origin. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9001, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '23 days', now() - INTERVAL '23 days'),
    (100538, 'Nhờ mọi người tư vấn chuyện đánh index đúng thứ tự cột. Đã thử theo hướng: một truy vấn lọc ba cột trên bảng triệu dòng từng đi từ Parallel Seq Scan 17ms xuống Index Only Scan 0,6ms sau khi thêm đúng index tổ hợp khớp thứ tự lọc. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9438, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '24 days', now() - INTERVAL '24 days'),
    (100539, 'Đang bí phần chuyển sang virtual threads, ai gặp rồi cho xin hướng. Đã thử theo hướng: sự cố Netflix tháng 7/2024 với virtual thread bắt nguồn từ một khối synchronized ghim virtual thread vào carrier thread, biến một đoạn mã tưởng vô hại thành điểm nghẽn toàn hệ thống. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9234, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '24 days', now() - INTERVAL '24 days'),
    (100540, 'Hỏi nhỏ: tách monolith thành service nên bắt đầu từ đâu? Đã thử theo hướng: chi phí ẩn lớn nhất không nằm ở hạ tầng mà ở giao tiếp giữa các service: một transaction từng gọn trong một câu SQL giờ cần saga hoặc outbox pattern để giữ nhất quán. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9356, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '24 days', now() - INTERVAL '24 days'),
    (100541, 'Team mình đang vướng thiết kế API phân trang. Đã thử theo hướng: trả kèm hasMore thay vì tổng số trang: COUNT(*) trên bảng lớn tốn kém và thường không cần thiết cho một danh sách cuộn vô hạn. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9132, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '24 days', now() - INTERVAL '24 days'),
    (100542, 'Cần lời khuyên về xử lý idempotency cho webhook. Đã thử theo hướng: cần nhất quán giao dịch thì lưu bản ghi idempotency ngay trong cùng transaction với thay đổi dữ liệu; chỉ cần tốc độ thì Redis với TTL tự dọn là lựa chọn phổ biến hơn. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9011, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '24 days', now() - INTERVAL '24 days'),
    (100543, 'Mình loay hoay mãi với chuẩn hoá log có traceId. Đã thử theo hướng: mDC (Mapped Diagnostic Context) của SLF4J gắn traceId vào mọi dòng log trong cùng luồng xử lý mà không cần truyền tay qua từng hàm. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9466, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '24 days', now() - INTERVAL '24 days'),
    (100544, 'Ai rành đo p99 thay vì trung bình không ạ? Đã thử theo hướng: khuếch đại đuôi (tail amplification) xảy ra khi một request chậm ở tầng dưới khiến các lượt retry ở tầng trên dồn lại, biến 1% request chậm thành sự cố toàn hệ thống. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9011, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '24 days', now() - INTERVAL '24 days'),
    (100545, 'Có ai từng làm giảm thời gian build CI chưa? Đã thử theo hướng: thứ tự ưu tiên đúng: cache trước (không cần đổi kiến trúc, lợi ích lớn nhất), song song hoá sau (cần tái cấu trúc pipeline nhưng lợi ích cộng dồn). Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9019, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '24 days', now() - INTERVAL '24 days'),
    (100546, 'Nhờ mọi người tư vấn chuyện viết test không phụ thuộc thứ tự. Đã thử theo hướng: mỗi test nên tự dựng dữ liệu của mình rồi tự dọn sau khi chạy, thay vì tin vào thứ tự chạy trước đó để lại đúng trạng thái cần. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9189, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '24 days', now() - INTERVAL '24 days'),
    (100547, 'Đang bí phần mock ít đi, dùng testcontainers, ai gặp rồi cho xin hướng. Đã thử theo hướng: chi phí thật của việc bảo trì mock là độ trôi (drift): schema hay logic nghiệp vụ đổi mà mock không đổi theo, lỗi lọt qua ngay chỗ lẽ ra test phải bắt được. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9072, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '24 days', now() - INTERVAL '24 days'),
    (100548, 'Hỏi nhỏ: dựng design token dùng chung nên bắt đầu từ đâu? Đã thử theo hướng: đổi một token màu ở đúng một chỗ và mọi nền tảng cập nhật theo, thay vì phải tìm-và-thay từng giá trị hex rải rác trong code. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9141, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '24 days', now() - INTERVAL '24 days'),
    (100549, 'Team mình đang vướng giảm layout shift. Đã thử theo hướng: một mức giảm CLS 0,1 tương ứng khoảng 1-2% tăng engagement trong một số nghiên cứu — người đọc không còn bị nội dung ''nhảy'' ngay lúc định bấm. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9122, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '25 days', now() - INTERVAL '25 days'),
    (100550, 'Cần lời khuyên về làm form truy cập được bằng bàn phím. Đã thử theo hướng: thứ tự Tab phải theo đúng thứ tự đọc hợp lý trên giao diện, không theo thứ tự khai trong DOM nếu CSS đã sắp xếp lại vị trí hiển thị. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9315, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '25 days', now() - INTERVAL '25 days'),
    (100551, 'Mình loay hoay mãi với chia bundle theo route. Đã thử theo hướng: phân tích bundle bằng công cụ visualizer thường lộ ra một thư viện ngoài dự tính chiếm phần lớn dung lượng — kiểu import cả một thư viện ngày tháng chỉ để dùng một hàm format. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9264, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '25 days', now() - INTERVAL '25 days'),
    (100552, 'Ai rành quản lý state không cần thư viện không ạ? Đã thử theo hướng: useContext một mình chỉ cấp quyền truy cập toàn cục, không có cấu trúc; useReducer một mình có cấu trúc nhưng chỉ cục bộ — kết hợp cả hai mới đủ thay một thư viện quản lý state ở quy mô vừa. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9374, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '25 days', now() - INTERVAL '25 days'),
    (100553, 'Có ai từng làm đồng bộ dữ liệu khi mất mạng chưa? Đã thử theo hướng: powerSync, Realm Sync và replication kiểu CouchDB là các nền tảng offline-first đang chạy production thật, dùng CRDT hoặc conflict resolution theo revision. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9255, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '25 days', now() - INTERVAL '25 days'),
    (100554, 'Nhờ mọi người tư vấn chuyện giảm kích thước app. Đã thử theo hướng: phần lớn dung lượng dư thừa nằm ở tài nguyên (ảnh độ phân giải cao không cần thiết, font không dùng) nhiều hơn là ở chính code. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9026, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '25 days', now() - INTERVAL '25 days'),
    (100555, 'Đang bí phần bảo mật token trên thiết bị, ai gặp rồi cho xin hướng. Đã thử theo hướng: trên thiết bị đã jailbreak/root, mọi lớp bảo vệ của hệ thống keychain coi như mất tác dụng — không nên tin tuyệt đối vào lưu trữ phía client cho secret có giá trị cao. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9438, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '25 days', now() - INTERVAL '25 days'),
    (100556, 'Hỏi nhỏ: rà soát phụ thuộc bên thứ ba nên bắt đầu từ đâu? Đã thử theo hướng: dependabot và các công cụ tương tự không chỉ báo lỗ hổng ở dependency trực tiếp mà còn dò tới tận dependency gián tiếp, tự tạo PR nâng phiên bản gốc để kéo theo bản vá. Mình mắc ở bước thứ hai và chưa tìm ra hướng nào chạy được.', 'PUBLIC', 9294, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":0,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '25 days', now() - INTERVAL '25 days'),
    (100557, 'Team mình đang vướng dựng pipeline triển khai xanh-lam. Đã thử theo hướng: đổi lại tốc độ rollback, chi phí là gấp đôi hạ tầng trong lúc chuyển đổi vì cả hai môi trường đều phải chạy đồng thời. Thử vài cách trên mạng nhưng đều không hợp với hệ đang chạy.', 'PUBLIC', 9194, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":25,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '25 days', now() - INTERVAL '25 days'),
    (100558, 'Cần lời khuyên về đặt resource limit cho pod. Đã thử theo hướng: pod ở nhóm Guaranteed (request bằng limit cho cả CPU lẫn RAM) bị evict sau cùng khi node thiếu tài nguyên; pod không khai request/limit bị evict đầu tiên. Chưa rõ nên sửa ở tầng ứng dụng hay tầng hạ tầng.', 'PUBLIC', 9304, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":50,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '25 days', now() - INTERVAL '25 days'),
    (100559, 'Mình loay hoay mãi với chuyển state Terraform lên remote. Đã thử theo hướng: state cục bộ không có khoá: hai người chạy terraform apply cùng lúc có thể ghi đè state của nhau — backend từ xa giải đúng vấn đề này bằng khoá tập trung. Chạy ổn trên máy mình nhưng lên staging thì hỏng.', 'PUBLIC', 9402, 'QNA', 'APPROVED', '{"isResolved":true,"bountyPoints":75,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '25 days', now() - INTERVAL '25 days'),
    (100560, 'Ai rành giảm hoá đơn cloud không ạ? Đã thử theo hướng: xoá dữ liệu test còn sót trên môi trường production-like và đặt lịch tắt máy dev ngoài giờ làm việc là hai khoản tiết kiệm rẻ nhất nhưng hay bị bỏ qua nhất. Sếp hỏi ước lượng mà mình chưa dám chốt.', 'PUBLIC', 9387, 'QNA', 'APPROVED', '{"isResolved":false,"bountyPoints":100,"acceptedAnswerId":null}'::jsonb, NULL, now() - INTERVAL '25 days', now() - INTERVAL '25 days');
