    (id, content, visibility, author_id, post_type, moderation_status, poll_details, images, created_at, updated_at) VALUES
    (100561, 'Khảo sát nhanh, mong mọi người bấm giúp. Dự án của bạn đang dùng gì để quản lý migration?', 'PUBLIC', 9387, 'POLL', 'APPROVED', '{"question":"Dự án của bạn đang dùng gì để quản lý migration?","options":[{"id":1,"text":"Flyway","votesCount":53},{"id":2,"text":"Liquibase","votesCount":15},{"id":3,"text":"Tự viết script","votesCount":11},{"id":4,"text":"Không dùng gì cả","votesCount":59}],"allowMultipleVotes":true,"endDate":"2026-08-26T23:59:59+07:00"}'::jsonb, NULL, now() - INTERVAL '76 days', now() - INTERVAL '76 days'),
    (100562, 'Tiện thể hỏi cả nhà một câu. Bạn chạy test tích hợp bằng gì?', 'PUBLIC', 9376, 'POLL', 'APPROVED', '{"question":"Bạn chạy test tích hợp bằng gì?","options":[{"id":1,"text":"Testcontainers","votesCount":16},{"id":2,"text":"H2 in-memory","votesCount":3},{"id":3,"text":"Database dùng chung","votesCount":11},{"id":4,"text":"Không có test tích hợp","votesCount":32}],"allowMultipleVotes":false,"endDate":"2026-09-29T23:59:59+07:00"}'::jsonb, NULL, now() - INTERVAL '26 days', now() - INTERVAL '26 days'),
