    (100564, 'Đang tò mò mọi người làm thế nào. Bạn đo hiệu năng bằng chỉ số nào?', 'PUBLIC', 9001, 'POLL', 'APPROVED', '{"question":"Bạn đo hiệu năng bằng chỉ số nào?","options":[{"id":1,"text":"p50","votesCount":49},{"id":2,"text":"p95","votesCount":49},{"id":3,"text":"p99","votesCount":48},{"id":4,"text":"Trung bình","votesCount":49}],"allowMultipleVotes":false,"endDate":"2026-09-29T23:59:59+07:00"}'::jsonb, NULL, now() - INTERVAL '26 days', now() - INTERVAL '26 days'),
    (100565, 'Một câu thăm dò, không mất quá mười giây. Thư mục seed nên chạy ở đâu?', 'PUBLIC', 9242, 'POLL', 'APPROVED', '{"question":"Thư mục seed nên chạy ở đâu?","options":[{"id":1,"text":"Chỉ dev","votesCount":32},{"id":2,"text":"Dev và staging","votesCount":22},{"id":3,"text":"Cả production","votesCount":48},{"id":4,"text":"Không dùng seed","votesCount":2}],"allowMultipleVotes":true,"endDate":"2026-08-10T23:59:59+07:00"}'::jsonb, NULL, now() - INTERVAL '68 days', now() - INTERVAL '68 days'),
    (100566, 'Khảo sát nhanh, mong mọi người bấm giúp. Bạn deploy lên production bằng cách nào?', 'PUBLIC', 9326, 'POLL', 'APPROVED', '{"question":"Bạn deploy lên production bằng cách nào?","options":[{"id":1,"text":"Tự động khi merge","votesCount":17},{"id":2,"text":"Bấm tay qua CI","votesCount":14},{"id":3,"text":"Chạy script trên máy","votesCount":29},{"id":4,"text":"Có người trực deploy","votesCount":33}],"allowMultipleVotes":false,"endDate":"2026-11-28T23:59:59+07:00"}'::jsonb, NULL, now() - INTERVAL '26 days', now() - INTERVAL '26 days'),
    (100567, 'Tiện thể hỏi cả nhà một câu. Đội bạn viết tài liệu ở đâu?', 'PUBLIC', 9345, 'POLL', 'APPROVED', '{"question":"Đội bạn viết tài liệu ở đâu?","options":[{"id":1,"text":"Wiki nội bộ","votesCount":37},{"id":2,"text":"File markdown trong repo","votesCount":56},{"id":3,"text":"Google Docs","votesCount":35},{"id":4,"text":"Gần như không viết","votesCount":9}],"allowMultipleVotes":false,"endDate":"2026-11-28T23:59:59+07:00"}'::jsonb, NULL, now() - INTERVAL '26 days', now() - INTERVAL '26 days'),
    (100568, 'Bình chọn nhẹ cho vui, ai rảnh bấm giúp. Bạn giữ secret lúc dev thế nào?', 'PUBLIC', 9326, 'POLL', 'APPROVED', '{"question":"Bạn giữ secret lúc dev thế nào?","options":[{"id":1,"text":"Vault hoặc secret manager","votesCount":41},{"id":2,"text":"File .env không commit","votesCount":7},{"id":3,"text":"Biến môi trường máy","votesCount":24},{"id":4,"text":"Ghi thẳng trong config","votesCount":54}],"allowMultipleVotes":false,"endDate":"2026-09-29T23:59:59+07:00"}'::jsonb, NULL, now() - INTERVAL '26 days', now() - INTERVAL '26 days'),
    (100569, 'Đang tò mò mọi người làm thế nào. Nhánh chính của repo bạn tên gì?', 'PUBLIC', 9141, 'POLL', 'APPROVED', '{"question":"Nhánh chính của repo bạn tên gì?","options":[{"id":1,"text":"main","votesCount":57},{"id":2,"text":"master","votesCount":34},{"id":3,"text":"develop","votesCount":59},{"id":4,"text":"Tuỳ repo","votesCount":13}],"allowMultipleVotes":true,"endDate":"2026-08-10T23:59:59+07:00"}'::jsonb, NULL, now() - INTERVAL '53 days', now() - INTERVAL '53 days'),
    (100570, 'Một câu thăm dò, không mất quá mười giây. Bạn chạy CI trên đâu?', 'PUBLIC', 9001, 'POLL', 'APPROVED', '{"question":"Bạn chạy CI trên đâu?","options":[{"id":1,"text":"GitHub Actions","votesCount":47},{"id":2,"text":"GitLab CI","votesCount":9},{"id":3,"text":"Jenkins","votesCount":26},{"id":4,"text":"Tự dựng","votesCount":31}],"allowMultipleVotes":false,"endDate":"2026-09-09T23:59:59+07:00"}'::jsonb, NULL, now() - INTERVAL '26 days', now() - INTERVAL '26 days'),
