INSERT INTO socialapp.t_posts
    (id, content, visibility, author_id, post_type, moderation_status, images, created_at, updated_at) VALUES
    (100761, 'Vừa đọc xong một cuốn về thiết kế hệ thống chịu tải. Nhiều chỗ mình gật gù vì đã tự học được bằng cách làm sai.', 'PUBLIC', 9255, 'BOOK', 'APPROVED', NULL, now() - INTERVAL '47 days', now() - INTERVAL '47 days'),
    (100762, 'Gấp lại cuốn sách sau hai tuần, chủ đề thói quen làm việc của kỹ sư lâu năm. Chương giữa hơi lê thê, nhưng phần đầu và cuối rất đáng.', 'PUBLIC', 9021, 'BOOK', 'APPROVED', NULL, now() - INTERVAL '47 days', now() - INTERVAL '47 days'),
    (100763, 'Đọc chậm hết một cuốn nói về cách một đội nhỏ giữ chất lượng mã. Sẽ để trên bàn làm việc và đọc lại từng phần khi cần.', 'PUBLIC', 9071, 'BOOK', 'APPROVED', NULL, now() - INTERVAL '47 days', now() - INTERVAL '47 days'),
    (100764, 'Cuốn này mình đọc đi đọc lại, xoay quanh những quyết định kiến trúc từng đi sai. Hợp với người đã đi làm vài năm hơn là người mới.', 'PUBLIC', 9068, 'BOOK', 'APPROVED', NULL, now() - INTERVAL '47 days', now() - INTERVAL '47 days'),
    (100765, 'Mới xong phần hay nhất của một cuốn về kỹ năng viết và giao tiếp trong kỹ thuật. Có vài ví dụ cũ, nhưng nguyên tắc thì vẫn đúng.', 'PUBLIC', 9387, 'BOOK', 'APPROVED', NULL, now() - INTERVAL '47 days', now() - INTERVAL '47 days'),
    (100766, 'Một cuốn mỏng nhưng chắc, viết về vận hành hệ thống lúc nửa đêm. Đọc xong muốn viết lại một service theo cách sách gợi ý.', 'PUBLIC', 9377, 'BOOK', 'APPROVED', NULL, now() - INTERVAL '47 days', now() - INTERVAL '47 days'),
    (100767, 'Đọc xong và muốn giới thiệu, chủ đề cách đọc mã của người khác. Ai đang phân vân thì mượn mình bản giấy cũng được.', 'PUBLIC', 9099, 'BOOK', 'APPROVED', NULL, now() - INTERVAL '47 days', now() - INTERVAL '47 days'),
    (100768, 'Cuốn sách đầu năm mình đọc hết, về trả nợ kỹ thuật mà không viết lại từ đầu. Ngắn gọn, không lên gân, mình thích giọng văn này.', 'PUBLIC', 9142, 'BOOK', 'APPROVED', NULL, now() - INTERVAL '48 days', now() - INTERVAL '48 days'),
    (100769, 'Bỏ dở nửa năm rồi quay lại đọc nốt, chủ đề phỏng vấn và xây đội. Phần bài tập cuối chương mới là chỗ đáng giá nhất.', 'PUBLIC', 9152, 'BOOK', 'APPROVED', NULL, now() - INTERVAL '48 days', now() - INTERVAL '48 days'),
    (100770, 'Vừa khép lại một cuốn dày, nói về tư duy dữ liệu cho người làm sản phẩm. Không có công thức thần kỳ, chủ yếu là cách nghĩ.', 'PUBLIC', 9329, 'BOOK', 'APPROVED', NULL, now() - INTERVAL '48 days', now() - INTERVAL '48 days'),
    (100771, 'Đọc theo lời giới thiệu của đồng nghiệp, một cuốn về bảo mật nhìn từ phía người phòng thủ. Mình sẽ tóm tắt lại vài ý cho buổi chia sẻ tháng sau.', 'PUBLIC', 9371, 'BOOK', 'APPROVED', NULL, now() - INTERVAL '48 days', now() - INTERVAL '48 days'),
    (100772, 'Vừa đọc xong một cuốn về hiệu năng web đo bằng số thật. Nhiều chỗ mình gật gù vì đã tự học được bằng cách làm sai.', 'PUBLIC', 9234, 'BOOK', 'APPROVED', NULL, now() - INTERVAL '48 days', now() - INTERVAL '48 days'),
